// 自動產生。改 .ink 後重跑 build_v2.js
window.STORY = {"ch01":{"inkVersion":21,"root":[[{"->":"kaijuan"},["done",{"#n":"g-0"}],null],"done",{"kaijuan":[["#","^bg:嘉興城外_黃昏","/#","#","^fx:dust","/#","^嘉興城外有片亂葬崗，崗子後頭是一大片桑林。","\n","^桑林裡住著一個十三歲的男孩。他沒有屋子，睡在一座塌了半邊的土地廟裡。廟裡的泥菩薩缺了一隻手，他每回進門都要拍拍那個斷口，說一聲「回來了」。","\n","^他叫楊過。這名字是郭伯伯給取的，說是「有過則改」的意思。他自己覺得取得不怎麼樣，但他娘活著的時候喜歡叫，他就留著了。","\n","^他娘死了兩年。","\n","#","^clear","/#","^那天傍晚他餓得發昏，蹲在桑樹上，看見底下有戶人家的婆子在餵雞。","\n","^那隻蘆花雞肥得走路都晃。","\n","ev","str","^這就下去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^等天全黑再說","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["^ ",{"->":"tou"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.deng"},"\n",{"#f":5}]}],{"deng":["ev",{"VAR?":"pi"},1,"+",{"VAR=":"pi","re":true},"/ev","^他忍住了。","\n","^肚子叫得像有隻貓在裡頭抓。他就伸手按住，一邊按一邊跟它講道理：現在下去，人家看得見你；等天黑了，你就是個影子。","\n","^天黑了。他從樹上溜下來，腳底沒發出一點聲音——這兩年他學會的東西裡，走路不出聲是最有用的一樣。","\n",{"->":"tou"},null]}],"tou":[["#","^bg:農家後院_夜","/#","#","^fx:none","/#","^那隻雞很配合，被他一把掐住脖子，連叫都沒叫出來。","\n","^不配合的是那條狗。","\n","^狗叫了三聲，屋裡的燈就亮了。他抱著雞往桑林裡衝，身後有個漢子一邊追一邊罵。","\n","^罵的是他娘。","\n","#","^clear","/#","^他跑到一半停住了。","\n","^那人罵他什麼都行。罵他娘不行。","\n","ev","str","^回頭跟他理論","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^把雞扔回去","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^不理他，繼續跑","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"tou.lilun"},"\n",{"#f":5}],"c-1":["^ ",{"->":"tou.reng"},"\n",{"#f":5}],"c-2":["^ ",{"->":"tou.pao"},"\n",{"#f":5}]}],{"lilun":["ev",{"VAR?":"ao"},1,"+",{"VAR=":"ao","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他抱著雞轉過身，把雞往地上一放。","\n","#","^emo:楊過_少年_倔","/#","^楊過：你罵我可以。我娘死了兩年，她招你惹你了？","\n","^那漢子愣住。他大概沒想到一個偷雞的小賊會停下來跟他講這個。","\n","^漢子：你、你偷我的雞！","\n","^楊過：我偷你的雞，是我不對。你罵我娘，是你不對。兩碼事。","\n","^他說完蹲下去把雞抱起來，轉身就走。","\n","^那人在背後喊了幾句，沒有追。","\n","^那天晚上他把雞烤了，吃到一半哭了一場，哭完把剩下的吃乾淨。","\n",{"->":"ouyang"},null],"reng":["ev",{"VAR?":"ao"},1,"+",{"VAR=":"ao","re":true},"/ev","ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^他停下來，把雞往地上一放。","\n","^楊過：還你。","\n","^那漢子追到跟前，看看雞，又看看他。","\n","^漢子：你這小賊——","\n","^楊過：我不是賊了。雞還你了。","\n","^他說完就走。走了十幾步，肚子叫了一聲，他咬著牙沒回頭。","\n","^那晚他嚼了半宿的桑葉，苦得舌頭發麻。","\n","^但他睡得著。","\n",{"->":"ouyang"},null],"pao":["ev",{"VAR?":"pi"},1,"+",{"VAR=":"pi","re":true},"/ev","^他不理，繼續跑。","\n","^跑進桑林深處，那漢子追不上，罵聲越來越遠。","\n","^他把雞烤了。烤得外焦裡生，吃得滿嘴是油。","\n","^吃完他躺在乾草上，看著屋頂那個破洞。洞外頭有星星。","\n","^他跟自己說：罵就罵吧。人死了，聽不見。","\n","^說完他翻了個身，把臉埋進草裡。","\n",{"->":"ouyang"},null]}],"ouyang":[["#","^bg:桑林_清晨","/#","#","^fx:dust","/#","#","^clear","/#","^隔了幾天，桑林裡來了個瘋子。","\n","^那人倒著走路，說話顛三倒四，有時候盯著自己的手看半個時辰。但他會武功——楊過親眼看見他一掌把一棵碗口粗的桑樹震得落了一地葉子。","\n","^那瘋子看見楊過的第一句話是：","\n","^歐陽鋒：孩子。","\n","^楊過：我不是。","\n","^歐陽鋒：你是。你是我兒子。","\n","^他不是。他很清楚自己不是。","\n","^但這兩年來，這是第一次有人急著要他當自己的什麼人。","\n","ev","str","^「好。爹。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我不是你兒子。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔沒有承認，也沒有否認〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"ouyang.ren_yes"},"\n",{"#f":5}],"c-1":["^ ",{"->":"ouyang.ren_no"},"\n",{"#f":5}],"c-2":["^ ",{"->":"ouyang.ren_mo"},"\n",{"#f":5}]}],{"ren_yes":["ev",true,"/ev",{"VAR=":"renfu","re":true},"ev",{"VAR?":"xiaming"},2,"-","/ev",{"VAR=":"xiaming","re":true},"^「好。爹。」","\n","^他叫了。叫完自己也愣了一下。","\n","^那瘋子高興得像個孩子，當場就要教他功夫。那套功夫陰狠、不擇手段，出手時十指要彎成蛤蟆的形狀。","\n","^楊過學得很快。快到他自己都覺得不對勁。","\n","^〔學得：蛤蟆功（皮毛）〕","\n","^後來很多年，江湖上提起他，總要先提一句「那是西毒的乾兒子」。","\n","^那句話跟了他一輩子。","\n",{"->":"guojing"},null],"ren_no":["ev",{"VAR?":"ao"},1,"+",{"VAR=":"ao","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^「我不是你兒子。」","\n","^那瘋子看了他很久，然後哭了。","\n","^哭得很難看，像個真的失去孩子的人。","\n","^楊過站在那裡，第一次覺得——拒絕一件事，原來也可以這麼難受。","\n","^他沒有學到那套功夫。","\n","^但那天晚上他睡不著。他一直在想：那個人到底把我當成了誰。","\n",{"->":"guojing"},null],"ren_mo":["ev",true,"/ev",{"VAR=":"renfu","re":true},"ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","ev",{"VAR?":"pi"},1,"+",{"VAR=":"pi","re":true},"/ev","^他沒有承認，也沒有否認。","\n","^瘋子當他答應了。當天下午就教了他三招。","\n","^楊過一邊學一邊在心裡替自己辯解：我又沒有說「好」。","\n","^這個辯解他用了很多年。每一次用，都比前一次沒有說服力一點。","\n","^〔學得：蛤蟆功（皮毛）〕","\n",{"->":"guojing"},null]}],"guojing":[["#","^bg:桑林_清晨","/#","#","^clear","/#","^又過了幾天，土地廟外頭站著兩個人。","\n","^一個是那晚追他的漢子。另一個他從來沒見過——身量不高，臉方方的，穿一身洗得發白的布衣，看起來像個老實巴交的莊稼漢。","\n","^漢子指著他：就是他！就是這小賊！","\n","^那中年人卻沒看漢子一眼。他一直看著楊過的臉，看得很仔細，仔細到有點失禮。","\n","^看了很久，他忽然開口，聲音有點抖。","\n","^郭靖：你……你姓什麼？","\n","ev","str","^「關你什麼事。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「姓楊。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔警戒地後退一步〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.g_ying"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.g_da"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.g_tui"},"\n",{"#f":5}]}],{"g_ying":["ev",{"VAR?":"ao"},1,"+",{"VAR=":"ao","re":true},"/ev","^楊過：關你什麼事。","\n","^那人不但沒生氣，反而笑了一下。那笑很奇怪，像是鬆了一口氣，又像是要哭。","\n","^郭靖：你這脾氣……跟他一模一樣。","\n",{"->":"ren_chu"},null],"g_da":["^楊過：姓楊。怎麼樣。","\n","^中年人沉默了一會。","\n","^郭靖：你娘……是不是姓穆？","\n","^他退了半步。這兩年沒有人提過他娘的名字。","\n",{"->":"ren_chu"},null],"g_tui":["ev",{"VAR?":"pi"},1,"+",{"VAR=":"pi","re":true},"/ev","^他不答，往後退了一步，背抵住廟門。","\n","^門是壞的，一推就開。他心裡已經算好了：往後一撞，穿過廟，從後窗跳出去，三十步外就是桑林，進了桑林誰也追不上他。","\n","^那人像是看穿了他在想什麼。","\n","^郭靖：孩子，別怕。我不抓你。","\n","^郭靖：我找了你兩年了。","\n",{"->":"ren_chu"},null]}],"ren_chu":[["#","^clear","/#","^楊過看著他。","\n","^楊過：你是誰。","\n","^那人蹲下來，讓自己的眼睛跟他一樣高。這個動作很笨拙，他大概不常對人這樣。","\n","^郭靖：我叫郭靖。","\n","^郭靖：我跟你爹……是結拜兄弟。","\n","#","^clear","/#","^楊過沒有說話。","\n","^他在心裡把「結拜兄弟」這四個字翻來覆去地看。他不太懂這四個字有多重，只知道這個人為了這四個字找了他兩年。","\n","^郭靖：跟我走吧。我帶你回家。","\n","ev","str","^「我沒有家。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「好。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「我娘的墳在後山。要先去看她。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.jia_wu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.jia_hao"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.jia_fen"},"\n",{"#f":5}]}],{"jia_wu":["ev",{"VAR?":"ao"},1,"+",{"VAR=":"ao","re":true},"/ev","^楊過：我沒有家。","\n","^郭靖愣了一下，然後很認真地說：","\n","^郭靖：以後有了。","\n","^楊過看著他那張老實的臉，忽然覺得很煩躁。他說不上來為什麼煩躁。","\n","^很多年以後他才想明白：那是因為他信了。","\n",{"->":"leave"},null],"jia_hao":["^楊過：好。","\n","^他答應得很快。快到郭靖都有點意外。","\n","^其實他心裡想的是：先跟你走，有飯吃。不好就跑。","\n","^他一直是這樣活下來的。","\n",{"->":"leave"},null],"jia_fen":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：我娘的墳在後山。要先去看她。","\n","^郭靖：好。","\n","^兩個人一起去了。墳是楊過自己堆的，堆得不成樣子，石頭東倒西歪。","\n","^郭靖在墳前站了很久，然後跪下去磕了三個頭。","\n","^楊過站在旁邊，看著這個第一次見面的人給他娘磕頭。","\n","^他的鼻子很酸，但他忍住了。","\n",{"->":"leave"},null]}],"leave":["#","^bg:嘉興城外_黃昏","/#","#","^fx:dust","/#","#","^clear","/#","^他們動身那天是個晴天。","\n","^楊過臨走前回了一趟土地廟。他站在那個缺了一隻手的泥菩薩前面，站了一會。","\n","^然後他伸手拍了拍那個斷口。","\n","^楊過：我走了。","\n","^菩薩沒有回答。它兩年來從來沒有回答過。","\n","#","^clear","/#","^出了桑林是官道，官道往東是海。","\n","^郭靖說要坐船，說東邊海上有座島，島上住著一位夫人，還有幾個跟他差不多大的孩子。","\n","^楊過一路上都沒有問那位夫人是誰。","\n","^他有一種說不清楚的預感——有些地方，人家肯讓你進去，不代表肯讓你留下。","\n","^〔第一回終〕","\n","^〔俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",0,{"VAR=":"qingyi"},0,{"VAR=":"xiaming"},0,{"VAR=":"pi"},0,{"VAR=":"ao"},false,{"VAR=":"renfu"},"/ev","end",null]}],"listDefs":{}},"ch02":{"inkVersion":21,"root":[[{"->":"shang_dao"},["done",{"#n":"g-0"}],null],"done",{"shang_dao":[["#","^bg:桃花島_春日","/#","#","^fx:dust","/#","^船靠岸的時候是清晨。","\n","^楊過跳下船，第一個念頭是：這裡好乾淨。","\n","^不是掃過的那種乾淨。是每一棵樹都被安排過位置的那種乾淨——花開在該開的地方，石徑轉在該轉的地方，連海風吹過來的方向都像是有人算好的。","\n","^他走在上面，覺得自己是這座島上唯一沒有被安排過位置的東西。","\n","#","^clear","/#","^一個女人從花木後頭走出來。","\n","^她很好看，笑起來眼睛彎彎的，一開口就讓人覺得親切。","\n","^黃蓉：這就是過兒？","\n","^郭靖：是。","\n","^黃蓉：長得真像。","\n","^她說「真像」的時候，笑還在臉上，但眼睛裡的東西換了一下。","\n","^換得很快。快到楊過事後懷疑是不是自己看錯。","\n","#","^clear","/#","^那天她給他做了一桌菜，樣樣都好吃。她問他冷不冷、餓不餓、路上辛不辛苦，問得比郭靖細緻十倍。","\n","^她待他很好。","\n","^往後兩年，她一直待他很好。","\n","ev","str","^「謝謝郭伯母。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「你剛才說我像誰？」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔悶頭吃飯，什麼也沒問〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.xie"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.wen_xiang"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.chi"},"\n",{"#f":5}]}],{"xie":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：謝謝郭伯母。","\n","^黃蓉：跟我不用客氣。","\n","^她替他添了半碗湯。動作很自然，自然到楊過差點就信了。","\n",{"->":"xue_shu"},null],"wen_xiang":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你剛才說我像誰。","\n","^黃蓉的筷子停了一下。只停了一下。","\n","^黃蓉：像你爹。","\n","^楊過：我爹是什麼樣的人。","\n","^黃蓉：……很聰明。","\n","^她說完就低頭吃飯了。","\n","^「很聰明」這三個字，楊過想了兩年。他想不通這三個字為什麼會讓一整桌人都安靜下來。","\n",{"->":"xue_shu"},null],"chi":["^他悶頭吃飯，什麼也沒問。","\n","^這兩年他學會一件事：在別人家裡，話越少越安全。","\n","^黃蓉看著他吃，忽然說了一句：","\n","^黃蓉：這孩子很懂事。","\n","^郭靖聽了很高興。楊過沒有抬頭。","\n","^他知道「懂事」不是誇獎。「懂事」是說一個孩子已經學會不給人添麻煩了。","\n",{"->":"xue_shu"},null]}],"xue_shu":[["#","^bg:桃花島_春日","/#","#","^clear","/#","ev",{"VAR?":"shu"},3,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"shu_end"},{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"shu"},0,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 第二天，她開始教他讀書。 ",{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"shu"},1,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又一堂課。 ",{"->":".^.^.^.28"},null]}],"nop","\n","ev",{"VAR?":"shu"},2,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 再一堂。 ",{"->":".^.^.^.36"},null]}],"nop","\n","ev","str","^認真背","/str",{"CNT?":".^.^.k_bei"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^問她什麼時候學武功","/str",{"CNT?":".^.^.k_wen"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^看窗外","/str",{"CNT?":".^.^.k_kan"},"!","/ev",{"*":".^.c-2","flg":21},{"c-0":["^ ",{"->":".^.^.^.k_bei"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.k_wen"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.k_kan"},"\n",{"#f":5}]}],{"k_bei":["ev",{"VAR?":"shu"},1,"+",{"VAR=":"shu","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他背得很快。","\n","^快到她抬起頭來看了他一眼。","\n","^黃蓉：你記性很好。","\n","^楊過：嗯。","\n","^黃蓉：……","\n","^她低頭繼續翻書。那一眼裡有東西，但他當時看不懂。","\n","^很多年後他才想明白：那不是欣賞。那是「這孩子太聰明了」——而在她心裡，聰明是他爹的東西。","\n",{"->":".^.^"},{"#f":1}],"k_wen":["ev",{"VAR?":"shu"},1,"+",{"VAR=":"shu","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：郭伯母，我什麼時候可以學武功。","\n","^她的筆停了一下。只停了一下。","\n","^黃蓉：讀書比武功有用。","\n","^楊過：可是芙妹妹在學。","\n","^黃蓉：她是她。","\n","^這三個字說得很輕。輕到他花了很多年才聽懂那個重量。","\n",{"->":".^.^"},{"#f":1}],"k_kan":["ev",{"VAR?":"shu"},1,"+",{"VAR=":"shu","re":true},"/ev","^他在看窗外。","\n","^窗外有三個人在練武。兩個男孩，一個女孩。他們打得不好，但他們在打。","\n","^黃蓉：過兒。","\n","^楊過：在。","\n","^黃蓉：看書。","\n","^他把眼睛收回來。","\n","^那天他把整篇背完了，一個字不錯。她誇了他。","\n","^他一點也不高興。","\n",{"->":".^.^"},{"#f":1}]}],"shu_end":["#","^clear","/#","^三堂課變成三十堂，三十堂變成兩年。","\n","^他把她給的書都背完了，背得比島上任何一個孩子都熟。","\n","^沒有人稱讚他。因為沒有人是為了讓他背得好，才開始教他的。","\n",{"->":"guo_fu"},null],"guo_fu":[["#","^bg:桃花島_春日","/#","#","^clear","/#","^島上還有三個孩子。","\n","^郭芙是郭靖夫婦的女兒，比他小一點，長得很好看，脾氣也大。武家兄弟是寄養在島上的，一大一小，兩個人整天跟在郭芙後面轉。","\n","^他們一開始就不喜歡楊過。","\n","^武大：你會武功嗎。","\n","^楊過：不會。","\n","^武二：那你來這裡做什麼。","\n","^郭芙在旁邊，沒說話，也沒走開。","\n","ev","str","^「我來吃飯的。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「郭伯伯帶我來的。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔不理他們，轉身走〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"guo_fu.f_qiao"},"\n",{"#f":5}],"c-1":["^ ",{"->":"guo_fu.f_shi"},"\n",{"#f":5}],"c-2":["^ ",{"->":"guo_fu.f_zou"},"\n",{"#f":5}]}],{"f_qiao":["ev",{"VAR?":"wu"},1,"+",{"VAR=":"wu","re":true},"/ev","ev",{"f()":"pi_up"},"pop","/ev","\n","^楊過：我來吃飯的。你們家飯挺好吃。","\n","^武二一下子漲紅了臉。","\n","^武二：你——","\n","^楊過：我怎麼了。我又沒說是白吃的。","\n","^郭芙「噗」地笑了一聲，笑完自己趕緊板起臉。","\n","^那一聲笑楊過聽見了。他記了很久。","\n",{"->":"f_fight"},null],"f_shi":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：郭伯伯帶我來的。","\n","^武大：那你就是寄人籬下。","\n","^楊過：……","\n","^他沒有反駁。因為對方說的是實話。","\n","^實話是最難反駁的。","\n",{"->":"f_fight"},null],"f_zou":["ev",{"f()":"pi_up"},"pop","/ev","\n","^他不理，轉身就走。","\n","^走了幾步，背後有塊石子打在他小腿上。不重，但打得很準。","\n","^他停了一下，沒有回頭。","\n","^那天晚上他把褲管捲起來看，那裡有一小塊青。他看了很久，然後把褲管放下來。","\n",{"->":"f_fight"},null]}],"pi_up":["ev","void","/ev","~ret",null],"f_fight":[["#","^clear","/#","^事情總是要爆的。","\n","^那天下午，武二說了一句關於他爹的話。楊過沒聽清楚全部，但聽清楚了「漢奸」兩個字。","\n","^〔真氣 8〕","\n","ev","str","^直接撲上去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先問清楚他說什麼","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^忍住","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.fi_pu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.fi_wen"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.fi_ren"},"\n",{"#f":5}]}],{"fi_pu":["ev",{"VAR?":"wu"},2,"+","/ev",{"VAR=":"wu","re":true},"^他撲上去了。","\n","^沒有招式，就是撲。他不會武功，但他比他們餓過、跑過、挨過打——他知道怎麼把人壓在地上。","\n","^他壓住了武二。壓了大概三息。","\n","^然後武大從後面抱住他的腰，郭芙撿了根樹枝抽在他背上。","\n",{"->":"fi_end"},null],"fi_wen":["ev",{"f()":"pi_up"},"pop","/ev","\n","^楊過：你剛才說什麼。你再說一次。","\n","^武二：我說你爹是——","\n","^他還沒說完，楊過已經動了。","\n","^後來他一直記得這件事：他明明是想聽清楚，結果聽清楚之後反而更忍不住。","\n","ev",{"VAR?":"wu"},1,"+",{"VAR=":"wu","re":true},"/ev",{"->":"fi_end"},null],"fi_ren":["ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^他忍住了。","\n","^他握緊拳頭，指甲掐進掌心，然後轉身走了。","\n","^走出十幾步，他聽見背後那三個人在笑。","\n","^那天他一個人在海邊坐到天黑。他一直在想一個問題：忍住到底是對的還是錯的。","\n","^他到死都沒有想明白。","\n",{"->":"fi_end"},null]}],"fi_end":[["#","^clear","/#",["ev",{"VAR?":"wu"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^最後他躺在地上。鼻子在流血，一隻眼睛腫了起來。","\n","^武二比他傷得重，被他壓住的那三息，他下了狠手。","\n",{"->":".^.^.^.6"},null]}],["ev",{"VAR?":"wu"},1,"==","/ev",{"->":".^.b","c":true},{"b":["\n","^最後他躺在地上。他們三個都沒怎麼樣。","\n",{"->":".^.^.^.6"},null]}],[{"->":".^.b"},{"b":["\n","^他沒有打。這件事就這樣過去了——表面上過去了。","\n",{"->":".^.^.^.6"},null]}],"nop","\n","#","^clear","/#","^黃蓉來的時候，一眼就看清楚了現場。","\n",["ev",{"VAR?":"wu"},1,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^她先把武氏兄弟扶起來，問他們傷到哪裡。","\n","^問完了，才轉身看楊過，問他有沒有事。","\n","^順序。","\n","^他記住的是順序。","\n",{"->":".^.^.^.15"},null]}],[{"->":".^.b"},{"b":["\n","^她問了一句「怎麼了」，三個孩子搶著說。她聽完就明白了。","\n","^她沒有罵任何人。","\n","^她只是看了楊過一眼——那一眼裡有種很累的東西。","\n",{"->":".^.^.^.15"},null]}],"nop","\n","ev","str","^「我沒事。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「對不起。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔搖頭，什麼也不說〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"fi_end.h_mei"},"\n",{"#f":5}],"c-1":["^ ",{"->":"fi_end.h_dui"},"\n",{"#f":5}],"c-2":["^ ",{"->":"fi_end.h_yao"},"\n",{"#f":5}]}],{"h_mei":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：我沒事。","\n","^說得很平。平到黃蓉多看了他一眼。","\n","^那一眼裡是：這孩子太會忍了。","\n","^而她心裡的下一句是：他爹當年也很會忍。","\n",{"->":"song_zou"},null],"h_dui":["^楊過：對不起。","\n","^黃蓉：你沒有錯。","\n","^楊過：喔。","\n","^她說他沒有錯。","\n","^但被扶起來的順序不會因為這句話而改變。","\n",{"->":"song_zou"},null],"h_yao":["^他搖頭，什麼也不說。","\n","^黃蓉也沒有再問。","\n","^兩個人站在那裡，各自知道對方在想什麼，各自都沒有說出來。","\n",{"->":"song_zou"},null]}],"song_zou":[["#","^bg:桃花島_春日","/#","#","^clear","/#","^三天後，郭靖跟他說了一件事。","\n","^郭靖：終南山上有個全真教，教武功。我送你去。","\n","^楊過：是郭伯母的意思嗎。","\n","^郭靖：……是我的意思。","\n","^他當時信了。","\n","#","^clear","/#","^走的那天天氣很好。","\n","^郭芙來送。她站在很遠的地方，沒有走近。武家兄弟沒有來。","\n","^黃蓉給了他一個包袱。裡頭有兩件新衣服，尺寸比他大了一號。","\n","^黃蓉：孩子長得快，做大一點。","\n","^這是她對他說過最像家人的一句話。","\n","^也是最後一句。","\n","ev","str","^「我會好好學。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我知道了。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔接過包袱，什麼也沒說〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.zou_xue"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.zou_zhi"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.zou_mo"},"\n",{"#f":5}]}],{"zou_xue":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：我會好好學。","\n","^他是真心的。他想學好了回來，讓他們看看。","\n","^這個念頭跟了他很久，久到後來變成了別的東西。","\n",{"->":"ch2_close"},null],"zou_zhi":["ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^楊過：我知道了。","\n","^他知道的比他們以為的多。","\n","^黃蓉聽出來了。她張了張嘴，最後什麼也沒說。","\n",{"->":"ch2_close"},null],"zou_mo":["^他接過包袱，什麼也沒說。","\n","^要走的人，說什麼都是多的。","\n",{"->":"ch2_close"},null]}],"ch2_close":["#","^clear","/#","^船離岸的時候他十四歲。","\n","^包袱裡那兩件衣服，他一次也沒穿過。","\n","^太大了。","\n","^〔第二回終〕","\n","^〔俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",0,{"VAR=":"qingyi"},0,{"VAR=":"xiaming"},0,{"VAR=":"shu"},0,{"VAR=":"wu"},"/ev","end",null]}],"listDefs":{}},"ch03":{"inkVersion":21,"root":[[{"->":"shang_shan"},["done",{"#n":"g-0"}],null],"done",{"shang_shan":["#","^bg:全真教_道觀","/#","#","^fx:none","/#","^終南山的秋天來得早。","\n","^楊過跟著郭靖上山那天，霧大得看不見三丈外的路。道觀的輪廓一層一層從霧裡浮出來，灰瓦白牆，一進又一進，安靜得像沒有人住。","\n","^郭靖把他交給一個道人，說了很多客氣話，又反覆交代要好好管教。","\n","^那道人姓趙，叫趙志敬。他一直在笑，笑得很有分寸。","\n","#","^clear","/#","^郭靖走的時候，在山門口回頭看了他一眼。","\n","^郭靖：過兒，好好學。學成了我來接你。","\n","^楊過：嗯。","\n","^霧把他的背影吃掉的時候，楊過在心裡數了三下。","\n","^數到三，他轉身進去了。","\n","^他這兩年練出一個習慣：跟人道別的時候不要看太久，看久了會捨不得，捨不得就會軟。","\n",{"->":"gui_ju"},null],"gui_ju":[["#","^bg:全真教_道觀","/#","#","^clear","/#","^全真教什麼都有規矩。","\n","^什麼時辰起、什麼時辰睡、走路走哪一邊、跟師兄說話要低幾分頭。楊過最初幾天挨的罰，全是因為不知道有這些規矩。","\n","^他很快就學會了。他學東西一向快。","\n","#","^clear","/#","^真正的問題不在規矩。","\n","^問題在趙志敬教得很省。","\n","^每一路劍法他都留一手。留的那一手要等徒弟夠恭順才給——這是全真教下面幾代人心照不宣的事，只有楊過不知道。","\n","^或者說，只有楊過不肯裝作不知道。","\n","ev","str","^照著練，先不說破","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^當場問他哪裡沒教完","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^自己補那一招","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"gui_ju.lian"},"\n",{"#f":5}],"c-1":["^ ",{"->":"gui_ju.wen"},"\n",{"#f":5}],"c-2":["^ ",{"->":"gui_ju.bu"},"\n",{"#f":5}]}],{"lian":["ev",{"VAR?":"ren"},1,"+",{"VAR=":"ren","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他照著練。一遍，兩遍，第七遍。","\n","^趙志敬沒有喊停，他就一直練。","\n","^練到手腕發抖的時候他忽然明白了：對方不是在看他練得對不對，是在看他能忍多久。","\n","^那天他忍到了。","\n","^但他也記住了，這個人在看什麼。","\n",{"->":"shou_fa"},null],"wen":["ev",{"VAR?":"ding"},1,"+",{"VAR=":"ding","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：師父，這一路是不是還有三招沒教。","\n","^道觀的院子裡安靜了一下。有幾個師兄轉過頭來。","\n","^趙志敬臉上的笑沒有變，眼睛變了。","\n","^趙志敬：你怎麼知道還有三招。","\n","^楊過：招式走到第五招收不住，後面一定還有。","\n","^趙志敬：……你只要照做。","\n","^他沒有再問。","\n","^但那天之後，趙志敬教他的時候，留的手更多了。","\n",{"->":"shou_fa"},null],"bu":["ev",{"VAR?":"ding"},1,"+",{"VAR=":"ding","re":true},"/ev","ev",{"f()":"pi_ok"},"pop","/ev","\n","^他自己補。","\n","^補得不對，很難看，但那三招接上去之後，整路劍法居然走得完了。","\n","^他練了三個晚上，練成之後在院子裡走了一遍。","\n","^趙志敬正好經過。","\n","^趙志敬：誰教你的。","\n","^楊過：沒有人。","\n","^趙志敬：……","\n","^那晚他被罰跪在後山，罰到半夜。","\n",{"->":"shou_fa"},null]}],"pi_ok":["ev","void","/ev","~ret",null],"shou_fa":["#","^bg:全真教_道觀","/#","#","^clear","/#","^兩年就這樣過去了。","\n","^他學會了一路殘的劍法，學會了怎麼在挨罵的時候把臉放空，學會了道袍要怎麼疊才不會被挑毛病。","\n","^他也學會了一件更有用的事：這座山上，沒有一個人是站在他這邊的。","\n",["ev",{"VAR?":"ding"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","ev",false,"/ev",{"VAR=":"canjue","re":true},"^他不服的時候太多，被罰的次數也多。","\n","^但也因為他一次又一次自己去補那些缺口，那路劍法在他手上反而是完整的——","\n","^只是那三招是他自己的，不是全真的。","\n","^〔全真劍法：殘而自補〕","\n",{"->":".^.^.^.15"},null]}],["ev",{"VAR?":"ren"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","ev",true,"/ev",{"VAR=":"canjue","re":true},"^他忍得很好。忍到趙志敬都覺得這孩子大概是馴服了。","\n","^但馴服沒有換來那三招。","\n","^他後來想通了：聽話不是條件。聽話就只是聽話。","\n","^〔全真劍法：殘缺〕","\n",{"->":".^.^.^.15"},null]}],[{"->":".^.b"},{"b":["\n","ev",true,"/ev",{"VAR=":"canjue","re":true},"^他不算聽話，也不算不聽話。他就這樣過了兩年。","\n","^那路劍法始終少了三招。他一直沒有補上。","\n","^〔全真劍法：殘缺〕","\n",{"->":".^.^.^.15"},null]}],"nop","\n",{"->":"tao"},null],"tao":[["#","^bg:全真教_道觀","/#","#","^clear","/#","^第三年入冬那天，事情爆了。","\n","^起因很小——小到楊過後來自己都想不起來確切是哪一句話。他只記得趙志敬當著全院的人罰他跪，而他跪到一半站起來了。","\n","^站起來之後，滿院子的人都在看他。","\n","^趙志敬：你跪下。","\n","^楊過：我不跪。","\n","^趙志敬：你再說一次。","\n","^楊過：我不跪。","\n","#","^clear","/#","^那天夜裡下了第一場雪。","\n","^他從後山的矮牆翻出去。牆頭有霜，他的手在上頭滑了一下，掌心劃開一道口子。","\n","^他跳下去的時候想的是：不能回頭。回頭就會有人喊你。","\n","ev","str","^「我不會再回來了。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^〔什麼也沒說，只是走〕","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^回頭看了道觀最後一眼","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"tao.tao_hen"},"\n",{"#f":5}],"c-1":["^ ",{"->":"tao.tao_mo"},"\n",{"#f":5}],"c-2":["^ ",{"->":"tao.tao_kan"},"\n",{"#f":5}]}],{"tao_hen":["ev",{"VAR?":"ding"},1,"+",{"VAR=":"ding","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^他在心裡說：我不會再回來了。","\n","^這句話他說得太用力，用力到往後很多年，只要有人提起全真教三個字，他的胃就會縮一下。","\n",{"->":"ch3_close"},null],"tao_mo":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他什麼也沒說。","\n","^雪落在肩上，他一邊走一邊拍。拍到後來拍不完了，就不拍了。","\n",{"->":"ch3_close"},null],"tao_kan":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他回頭看了一眼。","\n","^道觀在雪裡只剩一個輪廓。燈都熄了，看不出跟白天有什麼不同。","\n","^他忽然想起郭靖走的時候也是這樣——霧把人吃掉，什麼都沒剩下。","\n","^他站了三息，然後轉身。","\n","^這一次他沒有數到三。","\n",{"->":"ch3_close"},null]}],"ch3_close":["#","^bg:終南山_雪坡黃昏","/#","#","^fx:snow","/#","#","^clear","/#","^雪下了三天。","\n","^他身上只有一件不合身的道袍——趙志敬的舊衣改的，袖子長出一截，跑起來得把兩隻手縮進袖子裡攥著。","\n","^他往山裡跑。山裡沒有路，但山裡也沒有人。","\n","^他跑了大半夜。天亮的時候已經不曉得自己在哪，只知道再走下去就要凍死。","\n","^而凍死跟被抓回去比起來，他寧可凍死。","\n","^這個念頭讓他有點得意。他想，我十六歲，我有骨氣。","\n","^然後他打了個噴嚏，得意就沒了。","\n","^〔第三回終〕","\n","^〔俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",0,{"VAR=":"qingyi"},0,{"VAR=":"xiaming"},false,{"VAR=":"canjue"},0,{"VAR=":"ren"},0,{"VAR=":"ding"},"/ev","end",null]}],"listDefs":{}},"ch04":{"inkVersion":21,"root":[[{"->":"ch4_open"},["done",{"#n":"g-0"}],null],"done",{"ch4_open":[["#","^bg:終南山_雪坡黃昏","/#","#","^fx:snow","/#","^到第四天上頭，雪還沒有要停的意思。","\n","^他已經走了一夜又半個白天。腳趾早就沒有知覺，只剩兩截木頭綁在腿底下，走一步撞一下地面。","\n","^他開始跟自己說話。說的都是些沒有用的：等一下要吃什麼，如果現在有一碗熱的東西他願意拿什麼去換，他娘煮的粥是什麼味道——想到第三件的時候他停住了，因為他發現自己已經想不起來那個味道了。","\n","^那件事比冷還難受。","\n","#","^clear","/#","^山壁上有一道縫，窄得像被誰用刀劈開又勉強合上。他本來要走過去的，走了兩步又退回來——","\n","^縫裡有風。","\n","^那風是暖的。","\n","^這時節，這座山上，不該有暖風。","\n","ev","str","^鑽進去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先在外頭喊一聲","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["^ ",{"->":".^.^.^.jin"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.han"},"\n",{"#f":5}]}],{"han":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他覺得不告而入不太像話，就對著那道縫喊了一聲：「有人嗎——」","\n","^聲音進去，沒有出來。","\n","^他等了一會，又喊：「我不是壞人！我是被人追的！」","\n","^還是沒有回音。","\n","^他站在雪地裡，忽然覺得自己這樣挺傻的。一個在雪山上快凍死的人，還講究禮數。","\n","^他娘要是看見，大概會笑他。","\n",{"->":".^.^.jin"},null],"jin":["#","^bg:石縫內_窄道","/#","#","^amb:tomb","/#","^他側著身子擠進去。","\n","^裡頭比外頭暖得多，暖到他鼻子先酸了。走了十幾步，道就寬了，腳下是鑿過的石階，一級一級往下。","\n","^石階很乾淨。乾淨得不像沒人走的地方。","\n",{"->":"popo_meet"},null]}],"popo_meet":[["#","^bg:古墓_甬道","/#","#","^center:孫婆婆","/#","^轉過一個彎，他撞上了一盞燈。","\n","^提燈的是個老婆婆，個子矮，背有點駝，一雙眼睛卻亮得嚇人。她把燈舉高照他的臉，看了半晌。","\n","^孫婆婆：小子，你怎麼進來的。","\n","^楊過：從那道縫。","\n","^孫婆婆：那道縫二十年沒人進來過。","\n","^楊過：那我運氣好。","\n","^老婆婆哼了一聲。那一聲聽起來像是笑。","\n","^孫婆婆：外頭全真教的人在找你？","\n","^楊過：……你怎麼知道。","\n","^孫婆婆：你身上那件道袍。改得不好，肩線都歪了。","\n","^他低頭看自己的肩膀，一時說不出話。","\n","#","^clear","/#","^老婆婆把燈放低了些，光就從他臉上移開。","\n","^孫婆婆：你叫什麼名字。","\n","^楊過：楊過。","\n","^孫婆婆：幾歲。","\n","^楊過：十六。","\n","^孫婆婆：吃過飯沒有。","\n","^這一句問得太突然。他愣了一下，才發現自己已經三天沒有好好吃過東西。","\n","ev","str","^「不用了，我歇一會就走。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「還沒。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「你們這裡有吃的？」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ke"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.shi"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.tan"},"\n",{"#f":5}]}],{"ke":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^「不用了，我歇一會就走。」","\n","^他嘴上這麼說，肚子卻很不給面子地叫了一聲。","\n","^老婆婆低頭看了看他的肚子，又抬頭看了看他的臉。","\n","^孫婆婆：你這孩子，嘴硬。","\n","^楊過：……","\n","^孫婆婆：跟我來。","\n",{"->":"in_tomb"},null],"shi":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^「還沒。」","\n","^他說得很老實。老實到他自己說完都有點意外——這兩年他早就學會了不承認自己需要什麼。","\n","^老婆婆點點頭，轉身就走。","\n","^孫婆婆：跟上。","\n",{"->":"in_tomb"},null],"tan":["^「你們這裡有吃的？」","\n","^孫婆婆：有。","\n","^楊過：好吃嗎。","\n","^孫婆婆：……你這孩子。","\n","^她一邊走一邊搖頭，燈影在石壁上晃。楊過跟在後頭，覺得這個婆婆有點意思。","\n",{"->":"in_tomb"},null]}],"in_tomb":[["#","^bg:古墓_主石室","/#","#","^center:none","/#","#","^clear","/#","^甬道盡頭是一間大石室。","\n","^楊過進去的第一個念頭是：這裡好乾淨。牆是白的，地是白的，連接縫都細得像用尺量過。石室頂上有一道窄縫，一束天光從那裡直直落下來，在地上照出一塊亮斑，光柱裡有細塵在慢慢地翻。","\n","^他從來沒見過這麼安靜的地方。安靜到他能聽見自己吞口水。","\n","#","^center:小龍女_背向","/#","^亮斑旁邊站著一個人。","\n","^穿白衣，很白，白得跟牆分不太出來。背對著他，沒有回頭。","\n","^孫婆婆：姑娘，這孩子是我帶進來的。","\n","^那個人沒有動。過了好一會才開口，聲音很淡，像在說一件跟自己無關的事。","\n","#","^center:小龍女","/#","#","^emo:小龍女","/#","^小龍女：帶進來的，就不能再出去。","\n","^孫婆婆：他還小。","\n","^小龍女：小也一樣。","\n","^楊過看看老婆婆，又看看那個白衣人。他忽然明白了：這裡不是他要不要留下的問題。","\n","ev","str","^「我又沒說要出去。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我吃完就走，不會給你們添麻煩。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「規矩是誰定的？」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ding"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.ke2"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.wenju"},"\n",{"#f":5}]}],{"ding":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^「我又沒說要出去。」","\n","^他說得又快又衝。說完自己都覺得有點賭氣。","\n","^那個白衣人轉過來了。第一次。","\n","^她的臉很白，眉眼是好看的，但沒有表情——不是冷，是那種好像從來沒學過怎麼有表情的樣子。她看了他大概三息。","\n","^小龍女：那你留下。","\n","^說完就轉回去了。","\n","^孫婆婆在旁邊悶著笑。楊過覺得自己好像贏了什麼，又說不上來贏了什麼。","\n",{"->":"after_meet"},null],"ke2":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^「我吃完就走，不會給你們添麻煩。」","\n","^小龍女：出不去。","\n","^楊過：為什麼出不去。","\n","^小龍女：進來的人不出去。這是規矩。","\n","^楊過：規矩是死的。","\n","^小龍女：……","\n","^她沒有再說。楊過本來還想接一句，但話到嘴邊發現對方根本沒有在跟他吵——她只是在陳述一件在她看來跟天會黑一樣的事。","\n","^跟這種人吵架是吵不起來的。","\n",{"->":"after_meet"},null],"wenju":["ev",{"VAR?":"wen"},1,"+",{"VAR=":"wen","re":true},"/ev","^「規矩是誰定的？」","\n","^小龍女：我師父。","\n","^楊過：你師父呢。","\n","^小龍女：死了。","\n","^楊過：那她不能改了。","\n","^小龍女：所以不能改。","\n","^楊過張了張嘴，發現這句話居然沒有破綻。","\n","^他這輩子第一次在鬥嘴上輸給一個沒有要跟他鬥嘴的人。","\n",{"->":"after_meet"},null]}],"after_meet":["#","^center:none","/#","#","^clear","/#","^孫婆婆帶他到旁邊一間小石室，端來一碗東西。","\n","^那是他這輩子吃過最難吃的一頓飯——沒有鹽，沒有油，煮得爛糊糊的，說是粥又不像粥。","\n","^他吃了三碗。","\n","^孫婆婆坐在旁邊看他吃，看著看著就嘆了口氣。","\n","^孫婆婆：你這孩子，餓成這樣。","\n","^楊過：我沒有。","\n","^孫婆婆：嗯，你沒有。","\n","^她伸手替他把碗添滿。那隻手很粗，指節腫得厲害，但動作很輕。","\n","^楊過低著頭吃，忽然不太敢抬起來。","\n","^上一個這樣看著他吃飯的人，是他娘。","\n",{"->":"quanzhen"},null],"quanzhen":["#","^bg:古墓_甬道","/#","#","^amb:tomb","/#","#","^clear","/#","^第三天，全真教的人找上門了。","\n","^他們站在墓門外，說話很大聲，說古墓派收留他們的逃徒，說要人。","\n","^孫婆婆走出去跟他們講理。她這輩子沒跟這麼多人講過話，講得很慢，一句一句，把道理擺出來。","\n","^那些人沒有要聽的意思。","\n","#","^clear","/#","^〔戰鬥　真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n","^〔真氣不是血。真氣是你這一場能做幾件事。〕","\n","^孫婆婆一個人擋在墓門口。楊過站在她身後三步。","\n",{"->":"fight_1"},null],"fight_1":[["^〔第一合〕","\n","^孫婆婆的掌風把最前面兩個逼退了半步。她背後的道袍下襬在抖——不是被風吹的。","\n","ev","str","^衝上去幫忙（真氣 −5）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^看她怎麼打，記招式（真氣 −2）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^繞到側面，找退路（真氣 −3）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.f1_chong"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.f1_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.f1_rao"},"\n",{"#f":5}]}],{"f1_chong":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他衝了。","\n","^他會的東西不多——趙志敬教的那點全真劍法，還是殘的。但他記得起手式，也記得怎麼把人的重心挑歪。","\n","^他挑歪了一個。那人踉蹌兩步，回手一掌把他掃了出去。","\n","^他撞在石壁上，眼前一黑。","\n","^孫婆婆：孩子！退後！","\n","^楊過：我不退！","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"fight_2"},null],"f1_kan":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"^他沒有動。","\n","^他盯著孫婆婆的手。她出掌的時候小指是收著的，收掌的時候先轉腕再收肘——這跟全真的路數完全不一樣，更省力，也更狠。","\n","^他把這幾下記在心裡。往後很多年，他每次用到那個轉腕的動作，都會想起這一天。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"fight_2"},null],"f1_rao":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"^他往側面挪，找有沒有別的出口。","\n","^石壁是實的。這條甬道只有一個進出口，而那個口子上站著孫婆婆。","\n","^他忽然明白了一件事：她不是在打，她是在堵。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"fight_2"},null]}],"fight_2":[["^〔第二合〕","\n","^對方的人一個一個往前壓。孫婆婆退了一步，又退了一步。","\n","^她的呼吸開始有聲音了。","\n","ev","str","^替她擋一下（真氣 −6）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^大喊一聲引開注意（真氣 −3）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^去拉她（真氣 −4）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.f2_dang"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.f2_han"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.f2_la"},"\n",{"#f":5}]}],{"f2_dang":["ev",{"VAR?":"zhenqi"},6,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^他從側面撲進去，用背替她擋了一掌。","\n","^那一掌打在他左肩上，他聽見自己骨頭裡有東西響了一下。","\n","^他沒有叫。他咬著牙站起來，站在她前面。","\n","^孫婆婆：你這孩子……","\n","^她的聲音是抖的。楊過一直記得那個抖。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"fight_end"},null],"f2_han":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"f()":"pi_shout"},"pop","/ev","\n","^他扯開嗓子喊了一聲，喊得又尖又長。","\n","^那些人愣了一下，有兩個回頭看他。","\n","^就那麼一瞬間，孫婆婆的掌打進去了。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"fight_end"},null],"f2_la":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他去拉她的袖子。","\n","^楊過：婆婆，走！不打了！我們走！","\n","^孫婆婆：走不了。門一開，他們就進來了。","\n","^楊過：那我們一起打！","\n","^孫婆婆：……好。","\n","^她笑了一下。那是他見過她唯一一次笑。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"fight_end"},null]}],"pi_shout":["ev","void","/ev","~ret",null],"fight_end":["#","^bg:古墓_甬道","/#","#","^amb:none","/#","#","^clear","/#","^後來楊過怎麼想都想不明白那一掌是怎麼落下來的。","\n","^他只記得有個道人的手掌收得太急，方向偏了；記得孫婆婆的身子往前一送，把他整個人擋在後面；記得那一聲很悶，不像打在人身上。","\n","^然後全真教的人就散了。他們也慌了。他們大概沒想過會出人命。","\n","#","^clear","/#","#","^bg:古墓_主石室","/#","#","^center:小龍女","/#","^小龍女把孫婆婆抱進石室，放在那束天光下面。","\n","^她抱人的姿勢很奇怪，是那種從來沒有抱過人的人的姿勢——兩隻手僵著，怕碰壞了什麼。","\n","^孫婆婆的眼睛還睜著。她先看了看小龍女，又轉過來找楊過。","\n","^楊過趕緊蹲下去，把耳朵湊過去。","\n","^孫婆婆：孩子……","\n","^楊過：婆婆，你別說話。","\n","^孫婆婆：……你嘴硬。這樣不行。以後要吃虧。","\n","^楊過的眼淚一下子就下來了。他這兩年沒哭過，一次都沒有。","\n","#","^clear","/#","^老婆婆費了很大的力氣，把手伸向小龍女。","\n","^孫婆婆：姑娘。","\n","^小龍女：嗯。","\n","^孫婆婆：我死了以後……你替我照顧他。","\n","^小龍女：……","\n","^孫婆婆：姑娘。你答應我。","\n","^石室裡很靜。那束天光裡的細塵還在慢慢地翻。","\n","#","^emo:小龍女_關","/#","^小龍女：好。我答應你。","\n","^孫婆婆的手就落下去了。","\n",{"->":"after_death"},null],"after_death":[["#","^bg:古墓_主石室","/#","#","^center:小龍女","/#","#","^clear","/#","ev",false,"/ev",{"VAR=":"popo_alive","re":true},"^他們把孫婆婆葬在墓後頭的石洞裡。","\n","^葬完之後，小龍女站在石室中央，看著楊過。看了很久。","\n","^楊過用袖子擦了把臉，擦得很用力，像是要把哭過的痕跡搓掉。","\n","^小龍女：我答應她照顧你。","\n","^楊過：嗯。","\n","#","^emo:小龍女_疑","/#","^小龍女：可是我不知道照顧是什麼。","\n","#","^clear","/#","^這句話她說得很平常，像在問路。","\n","^楊過抬起頭來看她。她站在那裡，是真的在等一個答案——不是客套，不是推託，她真的不知道。","\n","^他忽然覺得這個人有點可憐。","\n","^然後他又覺得，自己這樣想一個能一掌把他拍扁的人，實在有點好笑。","\n","ev","str","^「就是有飯給我吃，有地方給我睡。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「不用你照顧，我自己會活。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「你想想你師父怎麼照顧你的。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.zhao_jian"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.zhao_ying"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.zhao_shi"},"\n",{"#f":5}]}],{"zhao_jian":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^「就是有飯給我吃，有地方給我睡。」","\n","^小龍女：這個容易。","\n","^楊過：還有——","\n","^小龍女：還有什麼。","\n","^楊過：……沒有了。","\n","^其實還有很多。但他看著她那張認真的臉，忽然一句也說不出口。","\n",{"->":"tomb_life"},null],"zhao_ying":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^「不用你照顧，我自己會活。」","\n","^小龍女：我答應她了。","\n","^楊過：那是你們的事。","\n","^小龍女：我答應了就要做。","\n","^她說得很堅決。楊過發現這個人有一種很麻煩的特質：她不跟你講理，她只是照做。","\n","^跟這種人講不通。","\n","^小龍女：你吃飯。","\n","^楊過：……喔。","\n",{"->":"tomb_life"},null],"zhao_shi":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","ev",{"VAR?":"wen"},1,"+",{"VAR=":"wen","re":true},"/ev","^「你想想你師父怎麼照顧你的。」","\n","^她想了。她真的站在那裡想了很久，久到楊過都有點後悔問這句。","\n","^小龍女：她教我武功。她叫我睡寒玉床。她不准我笑。","\n","^楊過：……就這些？","\n","^小龍女：就這些。","\n","^楊過張了張嘴，又閉上。","\n","^他想說「那不叫照顧」，但他看著她，忽然覺得這句話說出來會傷人。","\n","^而她可能連被傷到都不知道。","\n",{"->":"tomb_life"},null]}],"tomb_life":[["#","^bg:古墓_主石室","/#","#","^center:none","/#","ev",{"VAR?":"days"},3,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"life_end"},{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"days"},0,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 第一天。 ",{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"days"},1,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 過了些日子。 ",{"->":".^.^.^.28"},null]}],"nop","\n","ev",{"VAR?":"days"},2,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又過了些日子。 ",{"->":".^.^.^.36"},null]}],"nop","\n","ev","str","^睡那張床","/str",{"CNT?":".^.^.act_bed"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^餵玉蜂","/str",{"CNT?":".^.^.act_feng"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^跟她練功","/str",{"CNT?":".^.^.act_gong"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^問她問題","/str",{"CNT?":".^.^.act_wen"},"!","/ev",{"*":".^.c-3","flg":21},{"c-0":["^ ",{"->":".^.^.^.act_bed"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.act_feng"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.act_gong"},"\n",{"#f":5}],"c-3":["^ ",{"->":".^.^.^.act_wen"},"\n",{"#f":5}]}],{"act_bed":["ev",{"VAR?":"days"},1,"+",{"VAR=":"days","re":true},"/ev","#","^bg:古墓_寒玉床房","/#","^她讓他睡寒玉床。","\n","^那床是整塊玉鑿的，白得不像石頭。他伸手碰了一下，整條手臂立刻麻到肩膀。","\n","^楊過：這個能睡？","\n","^小龍女：能。我睡了十八年。","\n","^楊過：那你一定很冷。","\n","^小龍女：習慣了就不冷。","\n","^他躺上去。第一個時辰他冷得發抖，第二個時辰他冷得說不出話，第三個時辰他忽然發現自己不抖了——不是不冷，是身體裡有一股熱從丹田那裡慢慢地頂上來。","\n","^他睜開眼，看見她坐在床邊的蒲團上，正看著他。","\n","^小龍女：你行的。","\n","^楊過：……你一直坐在這裡？","\n","^小龍女：嗯。","\n","^楊過：坐多久了。","\n","^小龍女：三個時辰。","\n","^他不說話了。","\n","^那天晚上他睡得很沉。","\n","ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev",{"->":".^.^"},{"#f":1}],"act_feng":["ev",{"VAR?":"days"},1,"+",{"VAR=":"days","re":true},"/ev","#","^bg:古墓_玉蜂房","/#","#","^amb:bees","/#","^墓後頭養著一群玉蜂，通身雪白，翅膀薄得能看見後面的石壁。","\n","^她餵的時候，蜂群安安靜靜。他伸手去餵，那群蜂繞著他轉了三圈才肯散。","\n","^楊過：牠們不喜歡我。","\n","^小龍女：牠們在認你。","\n","^楊過：認多久？","\n","^小龍女：不知道。我沒有算過。","\n","^他忽然想起一件事。","\n","^楊過：那你養了牠們多久？","\n","^小龍女：……","\n","^她停了很久。","\n","^小龍女：我也沒有算過。","\n","^楊過看著她的側臉，第一次意識到一件事：這個人不是不記得，是從來沒有人問過她，所以她從來沒有需要記得。","\n","ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev",{"->":".^.^"},{"#f":1}],"act_gong":["ev",{"VAR?":"days"},1,"+",{"VAR=":"days","re":true},"/ev","#","^bg:古墓_主石室","/#","^她教他玉女心經。","\n","^教得很慢。慢到他一度以為她在敷衍——後來他才發現不是。她只是不知道怎麼把一件事講給另一個人聽。她這輩子沒有需要過。","\n","^小龍女：手抬到這裡。","\n","^楊過：這裡？","\n","^小龍女：不對。","\n","^楊過：那是哪裡。","\n","^小龍女：……這裡。","\n","^她伸手過來，握住他的手腕，把他的手擺到正確的位置。","\n","^她的手很涼。","\n","^擺好之後她沒有立刻放開。她低頭看著自己的手，像是在確認什麼。","\n","#","^emo:小龍女_關","/#","^小龍女：你的手是熱的。","\n","^楊過：人的手本來就是熱的。","\n","^小龍女：我的不是。","\n","^她說完就鬆開了，退回去三尺，繼續講下一招。","\n","^那天剩下的時間裡，楊過一招也沒有練好。","\n","ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},{"->":".^.^"},{"#f":1}],"act_wen":["ev",{"VAR?":"days"},1,"+",{"VAR=":"days","re":true},"/ev","ev",{"VAR?":"wen"},2,"+","/ev",{"VAR=":"wen","re":true},"#","^bg:古墓_石堂","/#","^石堂裡有兩個蒲團，隔著三尺。深的那個坐得發亮，淺的那個幾乎沒有痕跡。","\n","^楊過坐在淺的那個上頭。","\n","^楊過：這個是誰的。","\n","^小龍女：我師父的師妹。","\n","^楊過：她人呢。","\n","^小龍女：出去了。","\n","^楊過：出去哪。","\n","^小龍女：不知道。她走的時候我還沒出生。","\n","^楊過看著那兩個蒲團之間的三尺。","\n","^楊過：你師父後來有想過她嗎。","\n","^小龍女：……","\n","^她沉默了很久。久到楊過以為她不打算回答了。","\n","^小龍女：我師父每天都擦那個蒲團。擦了四十年。","\n","^小龍女：我以前不懂她為什麼要擦一個沒有人坐的東西。","\n","^她說到這裡停住了，像是後半句自己也沒想清楚。","\n","^楊過沒有追問。","\n","^他只是把自己坐的那個蒲團，往深的那個挪近了半尺。","\n","^她看見了。她什麼也沒說。","\n","ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev",{"->":".^.^"},{"#f":1}]}],"life_end":["#","^bg:古墓_主石室","/#","#","^clear","/#","^日子就這樣過。","\n","^古墓裡沒有白天黑夜，時間靠她起床和睡覺分段。他慢慢也用同一種方式過日子，不知不覺就過了大半年。","\n","^有一天他發現自己已經很久沒有想過外面了。","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n",{"->":"suxin_intro"},null],"suxin_intro":["#","^bg:古墓_主石室","/#","#","^center:小龍女","/#","#","^amb:none","/#","#","^music:suxin_partial","/#","^小龍女：玉女心經的最後一篇，要兩個人。","\n","^楊過：一個人不行嗎。","\n","^小龍女：一個人是另外一套。那套我不教。","\n","^楊過：為什麼不教。","\n","^小龍女：因為那套是給沒有人陪的人用的。","\n","^她說完就站到他對面，三尺遠——跟石堂裡那兩個蒲團一樣遠。","\n","^小龍女：這套叫玉女素心劍法。兩個人的劍要走在一起。","\n","^楊過：怎麼樣算走在一起。","\n","^小龍女：我出手的時候，你要知道我要往哪裡。","\n","^楊過：那我怎麼知道。","\n","^小龍女：……我也不知道。","\n","^她想了想，又補了一句。","\n","^小龍女：師父說，心裡想著對方就行。","\n","^她說這句話的時候，臉上什麼表情也沒有。楊過卻覺得耳朵有點燙。","\n",{"->":"suxin_1"},null],"suxin_1":[["^〔第一合　情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^〕","\n","^她的劍先動。","\n","ev","str","^跟著她的劍走","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^走她沒有走的那一半","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^先停一下，看清楚再說","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.s1_gen"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.s1_bu"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.s1_ting"},"\n",{"#f":5}]}],{"s1_gen":["^他跟著她的劍走。","\n","^兩把劍走在同一條線上，力道疊在一起，聲勢很大。","\n","^小龍女：不對。","\n","^楊過：怎麼不對，這樣不是更有力嗎。","\n","^小龍女：兩個人做同一件事，那是一個人。","\n","^她收劍。","\n","^小龍女：再來。","\n",{"->":"suxin_2"},null],"s1_bu":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他沒有跟。","\n","^她的劍往左，他就往右——不是相反，是補上她沒有顧到的那一半。","\n","^兩把劍在中間交錯而過，差了不到一寸。","\n","^小龍女：……嗯。","\n","^楊過：對了嗎。","\n","^小龍女：對了。","\n","^她說「對了」的時候，語氣跟平常一模一樣。但楊過發現她的耳根紅了一點點。","\n","^只有一點點。他也不確定是不是自己看錯。","\n",{"->":"suxin_2"},null],"s1_ting":["ev",{"VAR?":"wen"},1,"+",{"VAR=":"wen","re":true},"/ev","^他停下來，把劍放低。","\n","^楊過：我先看你走三招。","\n","^小龍女：好。","\n","^她走了三招。他站在原地看，一動也不動。","\n","^第三招收勢的時候，他忽然說：","\n","^楊過：你的劍走到第二招的時候會慢半分。","\n","^小龍女：……會嗎。","\n","^楊過：會。因為你在等人接。","\n","^她沒有回答。","\n","^過了一會她才說：","\n","^小龍女：那你接。","\n",{"->":"suxin_2"},null]}],"suxin_2":[["^〔第二合　情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^〕","\n","ev",{"VAR?":"qingyi"},6,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^這一合開始，他發現一件很怪的事——他不用看她，也知道她的劍在哪裡。","\n",{"->":".^.^.^.13"},null]}],"nop","\n","ev","str","^搶在她前面出手","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^等她先動","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^同時","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.s2_qiang"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.s2_deng"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.s2_tong"},"\n",{"#f":5}]}],{"s2_qiang":["^他先出手了。","\n","^她接得上，但接得勉強。兩把劍撞在一起，發出很難聽的一聲。","\n","^小龍女：你太快了。","\n","^楊過：我怕你來不及。","\n","^小龍女：我不會來不及。","\n","^她頓了一下。","\n","^小龍女：你不用替我擔心。","\n","^楊過張了張嘴。他想說「我沒有替你擔心」，但那是假話，而在這個人面前說假話好像特別沒有意思。","\n",{"->":"suxin_end"},null],"s2_deng":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他等她先動。","\n","^她的劍出去了，他的劍在半息之後跟上，剛好補在她收勢的空當上。","\n","^一來一往，像有人在說話，也像有人在答話。","\n","^小龍女：這樣可以。","\n","^楊過：這樣是不是叫「走在一起」。","\n","^小龍女：……應該是。","\n",{"->":"suxin_end"},null],"s2_tong":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^兩個人同時動了。","\n","^沒有誰先誰後，也沒有誰讓誰。","\n","^兩把劍在中間交會，然後分開，然後又交會。三尺的距離在那一瞬間變得剛剛好——不多不少，正好夠兩把劍走完各自的路，又正好夠它們碰得到對方。","\n","^一整套走完，他們都停在原地，沒有動。","\n","^石室裡很安靜。那束天光還在，細塵還在慢慢地翻。","\n","^小龍女：楊過。","\n","^楊過：嗯。","\n","^小龍女：剛才那一下，你是不是沒有看我。","\n","^楊過：……沒有。","\n","^小龍女：那你怎麼知道我在哪裡。","\n","^他答不出來。","\n","^她也沒有再問。","\n",{"->":"suxin_end"},null]}],"suxin_end":["#","^clear","/#",["ev",{"VAR?":"qingyi"},8,">=","/ev",{"->":".^.b","c":true},{"b":["\n","ev",true,"/ev",{"VAR=":"suxin","re":true},"^〔玉女素心劍法：已練成〕","\n","^那天之後，他們的劍再也沒有撞在一起過。","\n","^這套劍法有個很麻煩的地方：它只能兩個人使。一個人使的時候，招式會在該有下半句的地方停住，像一句話講到一半沒了聲音。","\n","^這件事很多年以後他才真正明白是什麼意思。","\n",{"->":".^.^.^.6"},null]}],["ev",{"VAR?":"qingyi"},5,">=","/ev",{"->":".^.b","c":true},{"b":["\n","ev",true,"/ev",{"VAR=":"suxin","re":true},"^〔玉女素心劍法：已練成（不穩）〕","\n","^他學會了。但每一次出手之前，他還是要先想一下她會往哪裡走。","\n","^要想，就是還沒到。","\n",{"->":".^.^.^.6"},null]}],[{"->":".^.b"},{"b":["\n","^〔玉女素心劍法：未成〕","\n","^她沒有說他學不會。她只是不再提這件事。","\n","^往後很多年，楊過每次想起這一段，都會想：如果那時候他多問她幾句話，是不是就不一樣了。","\n",{"->":".^.^.^.6"},null]}],"nop","\n",{"->":"ch4_close"},null],"ch4_close":["#","^bg:古墓_主石室","/#","#","^center:none","/#","#","^amb:tomb","/#","#","^music:none","/#","#","^clear","/#","^那年冬天特別長。","\n","^古墓裡照樣沒有白天黑夜，照樣是那束天光，照樣是滴水的聲音。楊過睡寒玉床，餵玉蜂，練玉女心經，跟她鬥嘴——她從來不接招，但他還是要鬥。","\n","^有一天他在石堂裡坐著，忽然想起自己是怎麼進來的。","\n","^那道石縫，那陣暖風，那個提著燈的老婆婆。","\n","^他坐了很久。","\n","^然後他起身，去把孫婆婆的那個蒲團擦了一遍。","\n","^擦完他才反應過來，自己做了一件跟小龍女的師父一模一樣的事。","\n","#","^clear","/#","^〔第四章結束〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","ev",{"VAR?":"suxin"},"/ev",[{"->":".^.b","c":true},{"b":["^ 〔玉女素心劍法：可用〕 ",{"->":".^.^.^.50"},null]}],"nop","\n","end",null],"global decl":["ev",0,{"VAR=":"qingyi"},0,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},true,{"VAR=":"popo_alive"},0,{"VAR=":"days"},0,{"VAR=":"wen"},false,{"VAR=":"suxin"},"/ev","end",null]}],"listDefs":{}},"ch05":{"inkVersion":21,"root":[[{"->":"chu_mu"},["done",{"#n":"g-0"}],null],"done",{"chu_mu":["#","^bg:古墓_主石室","/#","#","^fx:dust","/#","^那年開春，古墓裡進了外人。","\n","^全真教的人翻出了一件舊事——說古墓派的傳人跟全真的逃徒住在一起，說這不合規矩。這一次他們帶了更多人，也帶了掌教的令。","\n","^小龍女站在石門後面，聽他們在外頭喊了半個時辰。","\n","^小龍女：我們出去。","\n","^楊過：出去做什麼。","\n","^小龍女：他們要一個交代。我給他們一個交代。","\n","#","^clear","/#","^她說「我們」的時候，楊過的心跳漏了一下。","\n","^這兩年他聽過她說「你」，說「我」，很少聽她說「我們」。","\n",{"->":"chongyang"},null],"chongyang":[["#","^bg:重陽宮_夜","/#","#","^fx:none","/#","#","^clear","/#","^重陽宮的石板廣場上站滿了人。","\n","^道人排成兩列，燈籠一路掛到殿門。楊過跟在小龍女身後走進去的時候，聽見兩旁有人在低聲說話，說的是「就是那個」。","\n","^他把頭抬高了一點。","\n","#","^clear","/#","^殿前的問話很難聽。","\n","^他們問小龍女跟一個少年獨處兩年成何體統，問她師門的規矩何在，問到後來已經不是問，是判。","\n","^小龍女一句也沒有辯。她只說了一句：","\n","^小龍女：他是我徒弟。我教他武功。","\n","^這句話說得又平又直，像在報一件天氣。","\n","^而在場所有人都聽出來——她根本不覺得自己需要辯解。","\n","ev","str","^「我師父沒有錯。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「你們管得著嗎。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔站到她前面〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.cy_hu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.cy_ding"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.cy_zhan"},"\n",{"#f":5}]}],{"cy_hu":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：我師父沒有錯。是我硬要留下的。","\n","^他把話全攬到自己身上。","\n","^小龍女轉頭看了他一眼。她大概不明白他為什麼要這樣說——在她看來，事情不是這樣的，事情就是事情。","\n","^但她沒有反駁他。","\n",{"->":"cy_fight"},null],"cy_ding":["ev",{"VAR?":"xiaming"},2,"-","/ev",{"VAR=":"xiaming","re":true},"ev",{"VAR?":"zhui"},1,"+",{"VAR=":"zhui","re":true},"/ev","^楊過：我們兩個人在哪裡住、住幾年，關你們什麼事。","\n","^滿場譁然。","\n","^有個老道氣得手指發抖：「你這孽障——」","\n","^楊過：我是孽障。那你們是什麼。","\n","^這句話說完，他自己都知道完了。","\n",{"->":"cy_fight"},null],"cy_zhan":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^他沒有說話，只是往前走了兩步，站到她前面。","\n","^他個子還沒她高，這樣站著其實擋不住什麼。","\n","^但他站住了。","\n","^小龍女低頭看了看他的後腦勺。過了一會，她伸手，很輕地按在他肩上。","\n","^那是她第一次主動碰他。","\n",{"->":"cy_fight"},null]}],"cy_fight":["#","^clear","/#","^事情還是打起來了。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n","^道人從三個方向圍上來。小龍女的劍已經出鞘。","\n",{"->":"f1"},null],"f1":[["^〔第一合〕","\n","ev","str","^單獨出手（真氣 −3）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^跟她走同一路劍（真氣 −5）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^先守，看她要往哪（真氣 −2）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"f1.f1_dan"},"\n",{"#f":5}],"c-1":["^ ",{"->":"f1.f1_he"},"\n",{"#f":5}],"c-2":["^ ",{"->":"f1.f1_shou"},"\n",{"#f":5}]}],{"f1_dan":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"^他自己打自己的。","\n","^玉女心經一個人使，招式走到一半就沒有下半句。他打了七八招，招招都在該接的地方空掉。","\n","^有個道人的劍尖劃過他的手背。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"f2"},null],"f1_he":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},["ev",{"VAR?":"qingyi"},8,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他往左，她往右。","\n","^兩把劍在中間交錯，補上了對方沒顧到的那一半——玉女素心劍法。","\n","^圍上來的三個人同時退了。他們沒見過這種打法：兩個人，一套劍，中間沒有空隙。","\n","^小龍女：好。","\n","^楊過：什麼好。","\n","^小龍女：你沒有看我。","\n",{"->":".^.^.^.8"},null]}],[{"->":".^.b"},{"b":["\n","^他想跟她走同一路，但他跟不上。","\n","^她的劍到了，他的劍還在半途。兩個人的節奏差了半息——半息就是差。","\n","^他們沒有輸，但也沒有那種「兩個人是一套劍」的感覺。","\n",{"->":".^.^.^.8"},null]}],"nop","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"f2"},null],"f1_shou":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"wen"},1,"+",{"VAR=":"wen","re":true},"/ev","^他不打，只守。","\n","^守了六招，他看出來了：她一直在往同一個方向走——不是殺出去，是往山門的方向挪。","\n","^她不想傷人。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"f2"},null]}],"f2":[["^〔第二合〕","\n","^前面的人退了，後面的人補上來。石板廣場上到處是燈籠的影子。","\n","ev","str","^搶在她前面開路（真氣 −6）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^護住她的背後（真氣 −4）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^拉著她直接衝出去（真氣 −5）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"f2.f2_qiang"},"\n",{"#f":5}],"c-1":["^ ",{"->":"f2.f2_hu"},"\n",{"#f":5}],"c-2":["^ ",{"->":"f2.f2_chong"},"\n",{"#f":5}]}],{"f2_qiang":["ev",{"VAR?":"zhenqi"},6,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他衝到前面去開路。","\n","^他用的是全真劍法——他在這座山上學了兩年的東西，現在用來打教他的人。","\n",["ev",{"VAR?":"qingyi"},10,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他打得很順。順到他自己都意外。","\n",{"->":".^.^.^.18"},null]}],[{"->":".^.b"},{"b":["\n","^那路劍法少了三招，打到第五招他就沒有東西可以接下去了。","\n","^他硬著頭皮亂補，補得很難看，但也衝出去了。","\n",{"->":".^.^.^.18"},null]}],"nop","\n",{"->":"f_end"},null],"f2_hu":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他退到她背後，貼著她轉。","\n","^她往哪邊出劍，他就補哪一邊。兩個人像一個人在原地轉了一圈。","\n","^小龍女：不要護我。","\n","^楊過：我沒有護你。","\n","^小龍女：……你有。","\n",{"->":"f_end"},null],"f2_chong":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"zhui"},1,"+",{"VAR=":"zhui","re":true},"/ev","^他抓住她的手腕就往外衝。","\n","^抓得很用力。她的手腕很細，涼的。","\n","^衝出山門的時候他才發現自己一直沒有放開。","\n","^他放開了。放得很快，快到像被燙到。","\n",{"->":"f_end"},null]}],"f_end":["#","^bg:山道_雨後","/#","#","^fx:dust","/#","#","^clear","/#","^〔脫身〕","\n","^他們一路跑到山下。","\n","^天在半路上亮了。雨也停了——那是一場整夜的雨，泥路上全是積水，水裡照著剛裂開的雲。","\n","^兩個人在一塊石頭上坐下來，喘氣。","\n","^楊過忽然笑了。","\n","^小龍女：你笑什麼。","\n","^楊過：我不知道。","\n","^楊過：可能是因為我們出來了。","\n","^她看著他笑，沒有跟著笑，也沒有阻止。","\n","^那天早上他十八歲。","\n","#","^clear","/#","^〔往後很多年，他一直覺得那是他這輩子最好的一個早上。〕","\n",{"->":"bian"},null],"bian":[["#","^bg:江南水鄉_午後","/#","#","^clear","/#","^他們往南走。","\n","^沒有目的地。她不說要去哪，他也不問——他心裡想的是走多久都行。","\n","^頭幾天很好。她開始問一些奇怪的問題：市集為什麼那麼吵，人為什麼要買不能吃的東西，橋為什麼要做成拱的。他一一回答，答不出來的就編。","\n","^她也不拆穿。","\n","#","^clear","/#","^第八天上，她變了。","\n","^不是吵架，不是生氣。是她忽然不太看他了。","\n","^他跟她說話，她要慢半拍才回。晚上住店，她要兩間房。他問她怎麼了，她說沒有。","\n","^再問，她還是說沒有。","\n","ev","str","^繼續追問","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^不問了，等她自己說","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^問她是不是因為重陽宮那件事","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"bian.b_zhui"},"\n",{"#f":5}],"c-1":["^ ",{"->":"bian.b_deng"},"\n",{"#f":5}],"c-2":["^ ",{"->":"bian.b_cai"},"\n",{"#f":5}]}],{"b_zhui":["ev",{"VAR?":"wen"},2,"+","/ev",{"VAR=":"wen","re":true},"ev",{"VAR?":"zhui"},1,"+",{"VAR=":"zhui","re":true},"/ev","^楊過：你告訴我。到底怎麼了。","\n","^小龍女：沒有怎麼。","\n","^楊過：你騙人。","\n","^小龍女：……","\n","^她沉默了很久。久到他以為她要說了。","\n","^小龍女：楊過。","\n","^楊過：嗯。","\n","#","^emo:小龍女_關","/#","^小龍女：有些事情，我不知道要怎麼講。","\n","^她說完就進房了。","\n","^門關上的聲音很輕。輕得像是怕吵到誰。","\n",{"->":"b_end"},null],"b_deng":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他沒有再問。","\n","^他想：她會說的。她一向想到什麼就說什麼，她不會藏事情。","\n","^他錯了。她確實不會藏事情——她是不知道那件事該用什麼字講。","\n","^一個從來沒有人教過她怎麼描述感覺的人，遇到一件她自己都不明白的事，只能不說。","\n",{"->":"b_end"},null],"b_cai":["ev",{"VAR?":"wen"},1,"+",{"VAR=":"wen","re":true},"/ev","^楊過：是不是因為重陽宮那晚。","\n","^小龍女：……","\n","^楊過：是不是他們說的那些話。","\n","^她抬起頭看他。她的眼睛裡有東西，但那個東西他讀不懂。","\n","^小龍女：不是他們的事。","\n","^楊過：那是誰的事。","\n","^小龍女：……","\n","^她沒有回答。她轉身走了。","\n",{"->":"b_end"},null]}],"b_end":[["#","^bg:客棧_夜","/#","#","^clear","/#","^第十天早上，她不見了。","\n","^床鋪整整齊齊，像沒有人睡過。她的劍不在。桌上什麼也沒留——沒有字條，沒有記號，沒有一句可以拿來反覆讀的話。","\n","^楊過在房裡站了很久。","\n","^他先想的是：她出去買東西。","\n","^然後想的是：她被人擄走了。","\n","^再然後他想的是：她走了。","\n","^這三個念頭他花了整整一天才想完。","\n","ev","str","^立刻去追","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先回古墓看看","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^在客棧等她","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"b_end.zhui_ji"},"\n",{"#f":5}],"c-1":["^ ",{"->":"b_end.hui_mu"},"\n",{"#f":5}],"c-2":["^ ",{"->":"b_end.deng_ta"},"\n",{"#f":5}]}],{"zhui_ji":["ev",{"VAR?":"zhui"},2,"+","/ev",{"VAR=":"zhui","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他當天就走了。","\n","^往南追了三百里，往東追了兩百里，見人就問，問到後來連自己在問什麼都糊塗了。","\n","^他問的是：有沒有見過一個穿白衣服的姑娘，很白，不太說話，比我高半個頭。","\n","^說到「比我高半個頭」的時候他會停一下。","\n","^因為他不確定現在還是不是。","\n",{"->":"ch5_close"},null],"hui_mu":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^他先回了古墓。","\n","^石門推得動。裡面什麼都沒變——寒玉床還在，蒲團還在，那束天光還在，細塵還在慢慢地翻。","\n","^只是沒有人。","\n","^他在石室裡坐了三天。第三天他起身，把孫婆婆的蒲團擦了一遍，然後出去了。","\n","^出去的時候他把石門帶上。他沒有回頭看。","\n",{"->":"ch5_close"},null],"deng_ta":["ev",{"VAR?":"wen"},1,"+",{"VAR=":"wen","re":true},"/ev","^他在客棧等了七天。","\n","^第一天他確信她會回來。第三天他開始跟掌櫃打聽有沒有人來找過他。第七天他把那間房退了。","\n","^退房的時候掌櫃問他：那位姑娘呢。","\n","^他張了張嘴，發現自己答不出來。","\n",{"->":"ch5_close"},null]}],"ch5_close":["#","^bg:荒野_黃昏獨行","/#","#","^fx:dust","/#","#","^clear","/#","^那年他十八歲，開始一個人走路。","\n","^他後來走了很多地方，見了很多人，學了很多東西。江湖上開始有人記得他的名字——不是什麼好名聲，但總算是名聲。","\n","^他問過很多人。有幾個說見過，他跑了很遠，都不是。","\n","^有一次是個穿白衣的老婦人。他站在人家門口，看了很久才走。","\n","#","^clear","/#",["ev",{"VAR?":"wen"},3,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他一直想不通她為什麼走。","\n","^他把在一起的每一天都想過一遍，找那一天。他找到了很多可能的那一天。","\n","^每一個都說不通，但每一個他都信過一陣子。","\n",{"->":".^.^.^.23"},null]}],["ev",{"VAR?":"zhui"},3,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他不想原因。他只是走。","\n","^只要還在走，就還沒有到「找不到」那一步。","\n",{"->":".^.^.^.23"},null]}],[{"->":".^.b"},{"b":["\n","^他想過很多種解釋，最後留下最簡單的一種：","\n","^她有她的理由，而她沒有告訴他。","\n","^這個解釋最不傷人，所以他留著。","\n",{"->":".^.^.^.23"},null]}],"nop","\n","^〔第五回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",8,{"VAR=":"qingyi"},0,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},0,{"VAR=":"wen"},0,{"VAR=":"zhui"},"/ev","end",null]}],"listDefs":{}},"ch06":{"inkVersion":21,"root":[[{"->":"lu_shang"},["done",{"#n":"g-0"}],null],"done",{"lu_shang":[["#","^bg:江南水鄉_午後","/#","#","^fx:dust","/#","^那是他一個人走的第三年。","\n","^三年裡他學會了很多不成套的東西：一點打狗棒法，一點旁門左道，一點怎麼在陌生的鎮上找到最便宜的飯館。他的個子抽高了，說話還是那麼欠揍。","\n","^那天他在一座石橋上啃燒餅，看見底下有個姑娘一瘸一拐地跑過來。","\n","^她跑得很難看，但很快——那是一個練過武、腿卻壞了的人才跑得出來的樣子。","\n","^她後頭有兩個人在追。","\n","ev","str","^跳下去攔","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先看清楚誰有理","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^裝作沒看見","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.lu_lan"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.lu_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.lu_bu"},"\n",{"#f":5}]}],{"lu_lan":["ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"ev",{"VAR?":"wushuang"},1,"+",{"VAR=":"wushuang","re":true},"/ev","^他把剩下半個燒餅塞進嘴裡，翻身就跳下去了。","\n","^落地的時候他還在嚼。","\n","^那兩個人一愣：「你是誰。」","\n","^楊過（嘴裡有餅）：路過的。","\n",{"->":"lu_meet"},null],"lu_kan":["ev",{"VAR?":"wushuang"},1,"+",{"VAR=":"wushuang","re":true},"/ev","^他沒有馬上動。他在橋上多看了三息。","\n","^三息夠了——追的那兩個人手上有刀，跑的那個姑娘手上沒有。而且那兩個人一邊追一邊笑。","\n","^他跳下去了。","\n",{"->":"lu_meet"},null],"lu_bu":["ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^他裝作沒看見。","\n","^這三年他學會的另一件事是：別人的事，少管。","\n","^那姑娘從橋下跑過去的時候抬頭看了他一眼。那一眼裡沒有求救，只有一種「果然」。","\n","^他被那一眼看得渾身不對勁。","\n","^三息之後他跳下去了。","\n","^楊過（對自己）：真是有病。","\n",{"->":"lu_meet"},null]}],"lu_meet":[["#","^clear","/#","^那兩個人不經打。楊過用的是不成套的雜學，打得很難看，但夠用。","\n","^打完他轉身，那姑娘正拄著一根木棍看他。","\n","^她長得挺好看，眉眼很利，臉上一點感激也沒有。","\n","^陸無雙：誰要你多事。","\n","^楊過：……啊？","\n","^陸無雙：我自己會跑。","\n","^楊過：你跑得贏他們？","\n","^陸無雙：跑不贏也是我的事。","\n","^楊過看著她，忽然笑了。","\n","^楊過：我懂了。你是那種被人救了會生氣的人。","\n","^陸無雙：你才是那種救了人要人謝的人。","\n","^楊過：我沒要你謝。","\n","^陸無雙：那你笑什麼。","\n","^楊過：我笑你腿瘸了嘴還這麼快。","\n","#","^clear","/#","^她愣了半晌，然後抄起木棍打他。","\n","^他一邊躲一邊笑。這是三年來他第一次笑得這麼放鬆。","\n","ev","str","^「我叫楊過。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「你腿怎麼了。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔什麼也沒問，跟著她走〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.lu_ming"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.lu_tui"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.lu_gen"},"\n",{"#f":5}]}],{"lu_ming":["ev",{"VAR?":"wushuang"},1,"+",{"VAR=":"wushuang","re":true},"/ev","^楊過：我叫楊過。你呢。","\n","^陸無雙：不告訴你。","\n","^楊過：那我叫你什麼。","\n","^陸無雙：不用叫。","\n","^楊過：那我叫你姑娘。","\n","^陸無雙：……你叫我傻蛋好了。","\n","^楊過：好啊。傻蛋。","\n","^陸無雙：我沒有說我是傻蛋！我是說——","\n","^她說到一半就知道自己上當了。","\n","^從那天起他一直叫她傻蛋。她一直很生氣。生氣了三年。","\n",{"->":"cheng_ying"},null],"lu_tui":["ev",{"VAR?":"wushuang"},2,"+","/ev",{"VAR=":"wushuang","re":true},"^楊過：你腿怎麼了。","\n","^她的臉一下子沉下來。","\n","^陸無雙：關你什麼事。","\n","^楊過：不關我的事。我就是問問。","\n","^陸無雙：……被人打的。","\n","^楊過：誰。","\n","^陸無雙：我師父。","\n","^她說完就走了，走得很快，快得腿更瘸了。","\n","^楊過在原地站了一會。","\n","^他想：原來不只我一個人是被自己該信的人弄成這樣的。","\n",{"->":"cheng_ying"},null],"lu_gen":["ev",{"VAR?":"wushuang"},1,"+",{"VAR=":"wushuang","re":true},"/ev","^他什麼也沒問，就跟著她走。","\n","^走了半里她停下來：「你跟著我做什麼。」","\n","^楊過：順路。","\n","^陸無雙：你知道我要去哪嗎。","\n","^楊過：不知道。","\n","^陸無雙：那你怎麼知道順路。","\n","^楊過：我沒有要去的地方。所以哪裡都順路。","\n","^她看了他一眼。那一眼比剛才軟了一點點。","\n",{"->":"cheng_ying"},null]}],"cheng_ying":[["#","^bg:客棧_夜","/#","#","^fx:none","/#","#","^clear","/#","^當天夜裡，他們在一間破屋裡歇腳。","\n","^屋裡已經有人——一個蒙著面紗的姑娘，正在吹一支竹簫。","\n","^她見了他們也不驚，把簫放下，倒了兩碗水推過來。","\n","^程英：外頭風大，進來吧。","\n","^她的聲音很輕，輕得像怕碰壞什麼。","\n","^陸無雙看了她一眼，什麼也沒說就把水喝了。楊過發現這兩個姑娘之間有種奇怪的默契——像是很早以前認識，又像是誰也不打算承認。","\n","ev","str","^問她為什麼蒙面","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^問她那支曲子叫什麼","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^道謝，然後閉嘴","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.cy_wen"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.cy_qu"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.cy_xie"},"\n",{"#f":5}]}],{"cy_wen":["^楊過：姑娘為什麼蒙著臉。","\n","^程英：不好看。","\n","^楊過：我不信。","\n","^程英：……","\n","^她沒有再說。但楊過注意到，她的耳朵紅了。","\n","^陸無雙在旁邊翻了個白眼：「你這人真沒禮貌。」","\n","^楊過：我這是關心。","\n","^陸無雙：你這是嘴賤。","\n",{"->":"cy_night"},null],"cy_qu":["ev",{"VAR?":"chengying"},2,"+","/ev",{"VAR=":"chengying","re":true},"^楊過：剛才那支曲子叫什麼。","\n","^程英：沒有名字。是我自己亂吹的。","\n","^楊過：好聽。","\n","^程英：……","\n","^她低下頭去，把簫收進袖子裡。","\n","^過了一會她說：","\n","^程英：你要是喜歡，我以後再吹。","\n","^「以後」這兩個字她說得很輕。輕到楊過根本沒聽見裡頭的東西。","\n","^陸無雙聽見了。她看了程英一眼，什麼也沒說。","\n",{"->":"cy_night"},null],"cy_xie":["ev",{"VAR?":"chengying"},1,"+",{"VAR=":"chengying","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：多謝姑娘。","\n","^說完他就靠著牆坐下，閉上眼睛。","\n","^程英看了他一會，把自己的外衫脫下來蓋在他身上。","\n","^他沒有睜眼，但他知道。","\n","^他一整夜都沒有動——動了就要說謝，說了謝就顯得他知道，知道了就麻煩。","\n",{"->":"cy_night"},null]}],"cy_night":["#","^clear","/#","^半夜裡，外頭起了風。","\n","^不是風。是一種很淡的香氣，混在風裡飄進來。","\n","^陸無雙的臉「唰」地白了。","\n","^陸無雙：她來了。","\n","^楊過：誰。","\n","^陸無雙：李莫愁。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_fight"},null],"li_fight":["#","^bg:客棧_夜","/#","#","^clear","/#","^她穿黃衫，拿拂塵，看起來不到三十歲。","\n","^她走進屋裡的時候沒有踢門，也沒有喊話。她就是走進來了，像走進自己家。","\n","^李莫愁：無雙，跟我回去。","\n","^陸無雙：我不回去。","\n","^李莫愁：那我把你的另一條腿也弄斷。","\n","^她說這句話的時候臉上帶著笑。","\n","#","^clear","/#","^他一眼就知道自己贏不了。","\n","^那就只剩另一件事可做——活下來。","\n",{"->":"li_1"},null],"li_1":[["^〔第一合〕","\n","ev","str","^正面接一招（真氣 −5）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^護住兩個姑娘退向門口（真氣 −4）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^用嘴拖時間（真氣 −1）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"li_1.li1_jie"},"\n",{"#f":5}],"c-1":["^ ",{"->":"li_1.li1_hu"},"\n",{"#f":5}],"c-2":["^ ",{"->":"li_1.li1_zui"},"\n",{"#f":5}]}],{"li1_jie":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"^他接了一招。","\n","^只接了一招他就知道自己錯了——那不是一個層級的東西。她的拂塵掃過來的時候，他連往哪裡閃都沒想清楚。","\n","^三道血痕留在他臉上。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_2"},null],"li1_hu":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他不接招，只往兩個姑娘前面站，一步一步往門口挪。","\n","^李莫愁看出來了，也不急。她只是慢慢地跟著走。","\n","^貓看老鼠就是這種走法。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_2"},null],"li1_zui":["ev",{"VAR?":"zhenqi"},1,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chengying"},1,"+",{"VAR=":"chengying","re":true},"/ev","^楊過：前輩留步。晚輩有句話想請教。","\n","^李莫愁：說。","\n","^楊過：前輩打人的時候是笑著的。這個習慣是天生的，還是後來練出來的。","\n","^屋裡安靜了一瞬。","\n","^李莫愁臉上的笑淡了一點。那一點就夠了——程英已經把陸無雙拉到門邊。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_2"},null]}],"li_2":[["^〔第二合〕","\n","^她收了笑。這比她笑的時候可怕得多。","\n","ev","str","^硬拚一次（真氣 −7）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^找退路（真氣 −3）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^問她認不認得古墓的招式（真氣 −2）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"li_2.li2_pin"},"\n",{"#f":5}],"c-1":["^ ",{"->":"li_2.li2_tui"},"\n",{"#f":5}],"c-2":["^ ",{"->":"li_2.li2_gu"},"\n",{"#f":5}]}],{"li2_pin":["ev",{"VAR?":"zhenqi"},7,"-","/ev",{"VAR=":"zhenqi","re":true},"^他拚了一次。","\n","^用的是雜學裡最狠的幾下。她只用了半條拂塵就化掉了。","\n","^拚完他知道：這輩子在她手上，他都不可能贏。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_end"},null],"li2_tui":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"^他一邊擋一邊看。","\n","^窗是死的，門口有她的人，只有後牆是土坯的。","\n","^土坯的牆可以撞。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_end"},null],"li2_gu":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他使了一招玉女心經。","\n","^一個人使，招式走到一半就停住了。","\n","^李莫愁的手停在半空。","\n","^李莫愁：這是古墓的。","\n","^楊過：是。","\n","^李莫愁：誰教你的。","\n","^楊過：……","\n","^李莫愁：她人呢。","\n","^楊過沒有答。","\n","^李莫愁看著他，忽然笑了——這次是真的覺得好笑。","\n","^李莫愁：她也不知道你在哪，是不是。","\n","^那一句比拂塵狠。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"li_end"},null]}],"li_end":["#","^bg:荒野_黃昏獨行","/#","#","^fx:dust","/#","#","^clear","/#","^〔逃〕","\n","^後牆是土坯的。他撞開了。","\n","^三個人跑進田裡，跑到腿軟，跑到吐。李莫愁追了半里就停了——不是追不上，是覺得沒意思。","\n","^天亮的時候他們坐在一條田埂上。","\n","^陸無雙的頭髮全散了，程英的面紗掉了一半，楊過臉上三道血痕。","\n","^三個人你看我我看你，然後不知道是誰先笑出來的。","\n","^笑了很久。","\n","#","^clear","/#","^〔他這輩子學到的第一條江湖規矩：有些對手不能贏，只能活。〕","\n",{"->":"ch6_close"},null],"ch6_close":["#","^bg:江南水鄉_午後","/#","#","^clear","/#","^他跟她們同行了兩個月。","\n","^那兩個月他過得很好。傻蛋每天罵他，程英每天替他們煮飯，晚上有簫聲。他有時候會忘記自己在找人。","\n","^想起來的時候他會很自責。","\n","#","^clear","/#","^分開那天在一個渡口。","\n",["ev",{"VAR?":"chengying"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^程英把一支簫塞給他。","\n","^程英：路上悶了可以吹。","\n","^楊過：我不會。","\n","^程英：亂吹也行。我當初也是亂吹的。","\n","^她說完就轉身上船了。她沒有回頭——楊過後來才明白，那是因為她不想讓他看見。","\n",{"->":".^.^.^.19"},null]}],[{"->":".^.b"},{"b":["\n","^程英跟他點了點頭，什麼也沒說就上船了。","\n",{"->":".^.^.^.19"},null]}],"nop","\n",["ev",{"VAR?":"wushuang"},3,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^陸無雙站在跳板上罵了他最後一句。","\n","^陸無雙：喂，傻蛋。","\n","^楊過：你才是傻蛋。","\n","^陸無雙：……你要是找到她了，記得跟我說一聲。","\n","^楊過：為什麼要跟你說。","\n","^陸無雙：因為你找不到的話很難看。我要看。","\n","^她說完就跑了。跑得一瘸一拐，跑得很快。","\n",{"->":".^.^.^.23"},null]}],[{"->":".^.b"},{"b":["\n","^陸無雙什麼也沒說就上船了。她一直沒有回頭。","\n",{"->":".^.^.^.23"},null]}],"nop","\n","#","^clear","/#","^船走了。","\n","^楊過在渡口站到看不見帆為止，然後轉身，繼續往南。","\n","^他還是沒有找到她。","\n","^但那年冬天他不太冷。","\n","^〔第六回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",8,{"VAR=":"qingyi"},4,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},0,{"VAR=":"wushuang"},0,{"VAR=":"chengying"},"/ev","end",null]}],"listDefs":{}},"ch07":{"inkVersion":21,"root":[[{"->":"ru_guan"},["done",{"#n":"g-0"}],null],"done",{"ru_guan":[["#","^bg:大勝關_廳堂","/#","#","^fx:dust","/#","^大勝關的英雄大會開了三天。","\n","^天下有頭有臉的人都來了。廳很深，兩排立柱，四周擺著成排的座席，坐滿了名字比人響亮的人。","\n","^楊過坐在最後面。沒有人認識他，也沒有人問他是誰——這種場合，坐最後面的人本來就不需要有名字。","\n","#","^clear","/#","^第三天上，蒙古人派了個使者來下戰書。","\n","^那人姓霍，年紀不大，一身錦衣，笑得很客氣。他很客氣地打贏了三個人。","\n","^第四個人站起來的時候，廳裡已經沒有人敢喊好了。","\n","^第四個人也輸了。","\n","#","^clear","/#","^霍都：還有嗎。","\n","^沒有人動。","\n","^有幾個老前輩低頭喝茶。有幾個年輕人握緊了拳頭又鬆開。","\n","ev","str","^站起來","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^再等一等，看有沒有人先出手","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^先問清楚賭注是什麼","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.zhan"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.deng"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.wen_du"},"\n",{"#f":5}]}],{"deng":["ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^他等了。","\n","^等了三息、五息、十息。沒有人動。","\n","^他心裡忽然冒出一個很不客氣的念頭：這一屋子的人，加起來大概還沒有傻蛋一個人有膽子。","\n","^想到這裡他就站起來了。","\n",{"->":".^.^.zhan"},null],"wen_du":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：這位霍兄，贏了怎麼樣，輸了又怎麼樣。","\n","^霍都：贏了，我便走。輸了，這裡的事你們說了算。","\n","^楊過：那我輸了呢。","\n","^霍都：那你就別開口。","\n","^楊過笑了。","\n","^楊過：好。那我可要贏。","\n",{"->":".^.^.zhan"},null],"zhan":["#","^clear","/#","^他站起來的時候，前面幾百個人都回頭了。","\n","^那些眼睛裡有各種東西：好奇、輕視、看熱鬧、還有幾個是純粹的「這誰啊」。","\n","^他一路走到廳中央，走得很慢。他這輩子沒有被這麼多人同時看過。","\n","^霍都：閣下高姓。","\n","^楊過：等我贏了再說。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h1"},null]}],"h1":[["^〔第一合〕","\n","ev","str","^先讓他出三招，看路數（真氣 −2）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^搶攻（真氣 −5）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^用不成套的雜學試他（真氣 −4）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"h1.h1_kan"},"\n",{"#f":5}],"c-1":["^ ",{"->":"h1.h1_qiang"},"\n",{"#f":5}],"c-2":["^ ",{"->":"h1.h1_za"},"\n",{"#f":5}]}],{"h1_kan":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"sheng"},1,"+",{"VAR=":"sheng","re":true},"/ev","^他讓對方先出三招。","\n","^三招之後他看明白了：這個人的功夫很整齊，整齊到沒有意外。每一招都在該在的地方，也就表示每一招都可以預先算出來。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h2"},null],"h1_qiang":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"^他一上來就搶攻。","\n","^打得又急又猛。霍都退了兩步——那兩步是真的退。","\n","^但他自己的真氣也去了一大截。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h2"},null],"h1_za":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"sheng"},1,"+",{"VAR=":"sheng","re":true},"/ev","^他用的是這三年撿來的雜學。","\n","^一招全真的起手，接一招打狗棒法的變化，再接一招不知道從哪裡學來的野路子。","\n","^霍都皺眉了。","\n","^霍都：你這是什麼武功。","\n","^楊過：不知道。撿的。","\n","^廳裡有人笑出聲。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h2"},null]}],"h2":[["^〔第二合〕","\n","ev","str","^等他重複同一招（真氣 −3）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^一口氣打完（真氣 −7）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^讓他打中一下，換一個破綻（真氣 −5）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"h2.h2_deng"},"\n",{"#f":5}],"c-1":["^ ",{"->":"h2.h2_kuai"},"\n",{"#f":5}],"c-2":["^ ",{"->":"h2.h2_rang"},"\n",{"#f":5}]}],{"h2_deng":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"sheng"},2,"+","/ev",{"VAR=":"sheng","re":true},"^他等。","\n","^等到第七招，霍都用了跟第二招一樣的起手。","\n","^就這一下。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h_end"},null],"h2_kuai":["ev",{"VAR?":"zhenqi"},7,"-","/ev",{"VAR=":"zhenqi","re":true},"^他不等了，一口氣打完。","\n","^真氣去得太急，最後三招他已經是硬撐。","\n","^但他撐完了。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h_end"},null],"h2_rang":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"sheng"},1,"+",{"VAR=":"sheng","re":true},"/ev","^他故意讓對方打中肩膀一下。","\n","^那一下很疼。但霍都收招的時候露出了一個空當——一個只有在得手之後才會出現的空當。","\n","^他鑽進去了。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"h_end"},null]}],"h_end":[["#","^clear","/#","^〔勝〕","\n",["ev",{"VAR?":"sheng"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^霍都退出廳外，臉色很難看，但他沒有多說一句。","\n","^廳裡站起來了。有人喊好，有人拍桌子，有幾個老前輩站起來朝他拱手。","\n",{"->":".^.^.^.7"},null]}],[{"->":".^.b"},{"b":["\n","^他贏得很難看。兩個人都掛了彩。","\n","^沒有人喊好。但也沒有人再說話。","\n",{"->":".^.^.^.7"},null]}],"nop","\n","#","^clear","/#","^有人問他叫什麼。","\n","ev","str","^「楊過。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「在下姓楊。」","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["^ ",{"->":"h_end.ming_zhi"},"\n",{"#f":5}],"c-1":["^ ",{"->":"h_end.ming_wan"},"\n",{"#f":5}]}],{"ming_zhi":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：楊過。","\n",{"->":".^.^.ming_hou"},null],"ming_wan":["^楊過：在下姓楊。","\n",{"->":".^.^.ming_hou"},null],"ming_hou":["#","^clear","/#","^整個廳安靜了三息。","\n","^因為那個姓，是一個十幾年前死掉的、名聲很壞的人的姓。","\n","^安靜過去之後，還是有人朝他拱手了。","\n","^〔他現在有發言權了。全廳都在等他說話。〕","\n",{"->":"chong_feng"},null]}],"chong_feng":[["#","^clear","/#","^然後他看見了她。","\n","^她站在廳門口，一身白衣，站在陽光照不到的地方。她不知道站了多久，也沒有人注意到她是什麼時候進來的。","\n","^三年。","\n","^楊過站在廳中央，手裡還握著剛才贏來的東西。他覺得自己應該說點什麼，或者做點什麼。","\n","^他什麼也沒做。他就站在那裡看著她。","\n","#","^clear","/#","^後來她走過來了。","\n","^她走過幾百個人中間，沒有看任何一個人。走到他面前三尺處停下——三尺，跟石堂裡那兩個蒲團一樣遠。","\n","#","^emo:小龍女_睜","/#","^小龍女：你長高了。","\n","^楊過：……嗯。","\n","^小龍女：比我高了。","\n","^她說這句話的時候，語氣跟在說天氣一樣。","\n","^而楊過站在那裡，忽然覺得眼睛很燙。","\n","^他把臉別開，假裝在看別的地方。","\n","ev","str","^「你這三年去哪了。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「你回來就好。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔什麼也說不出來〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.cf_wen"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.cf_hao"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.cf_mo"},"\n",{"#f":5}]}],{"cf_wen":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你這三年去哪了。","\n","^小龍女：走了很多地方。","\n","^楊過：為什麼不告訴我。","\n","^小龍女：……","\n","^她沒有答。她從來沒有答過這個問題，往後也不會。","\n","^但她伸出手，很輕地按在他的手背上。","\n","^那隻手還是涼的。","\n",{"->":"cf_end"},null],"cf_hao":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^楊過：你回來就好。","\n","^他沒有問為什麼走，一句也沒有問。","\n","^小龍女看了他很久。","\n","^小龍女：你不問。","\n","^楊過：不問。","\n","^小龍女：……好。","\n","^她說「好」的時候聲音有一點點抖。全場只有他一個人聽見。","\n",{"->":"cf_end"},null],"cf_mo":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他什麼也說不出來。","\n","^三年裡他想過幾百種見面時要說的話。真到了這一刻，一句都想不起來。","\n","^兩個人在幾百個人中間站著，誰也沒有說話。","\n","^後來有人在旁邊咳了一聲。","\n",{"->":"cf_end"},null]}],"cf_end":[["#","^clear","/#","^那個咳嗽的人是主人家。他很客氣地問：","\n","^「這位姑娘是？」","\n","^廳裡幾百雙眼睛看過來。","\n","^楊過知道他該說什麼。他該說「這是家師」，然後這件事就過去了，他今天贏來的東西還在。","\n","^他也知道自己不會那樣說。","\n","ev","str","^「我要娶她。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「這是我師父。我要娶她。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「她叫小龍女。她教過我武功——我要娶她。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"cf_end.xg_zhi"},"\n",{"#f":5}],"c-1":["^ ",{"->":"cf_end.xg_quan"},"\n",{"#f":5}],"c-2":["^ ",{"->":"cf_end.xg_wan"},"\n",{"#f":5}]}],{"xg_zhi":["ev",3,"/ev",{"VAR=":"xuangao","re":true},"ev",{"VAR?":"qingyi"},3,"+","/ev",{"VAR=":"qingyi","re":true},"ev",{"VAR?":"xiaming"},6,"-","/ev",{"VAR=":"xiaming","re":true},"^楊過：我要娶她。","\n","^四個字。","\n","^他說得又快又清楚，快到沒有給自己反悔的餘地。","\n",{"->":"hou_guo"},null],"xg_quan":["ev",2,"/ev",{"VAR=":"xuangao","re":true},"ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"ev",{"VAR?":"xiaming"},5,"-","/ev",{"VAR=":"xiaming","re":true},"^楊過：這是我師父。我要娶她。","\n","^他自己把最要命的那兩個字說出來了。","\n","^他大可以不說。但他不想她被人當成什麼見不得光的東西。","\n",{"->":"hou_guo"},null],"xg_wan":["ev",1,"/ev",{"VAR=":"xuangao","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","ev",{"VAR?":"xiaming"},4,"-","/ev",{"VAR=":"xiaming","re":true},"^楊過：她叫小龍女。她教過我武功——我要娶她。","\n","^他想把這件事說得體面一點。","\n","^沒有用。他們聽見的只有最後四個字。","\n",{"->":"hou_guo"},null]}],"hou_guo":[["#","^clear","/#","^師徒。","\n","^在這個廳裡，這兩個字比蒙古人嚴重。","\n","#","^clear","/#","^先是沒有聲音，然後全部一起有聲音。","\n","^有人拍案而起。有人說不知羞恥。有人說果然是那個人的兒子。","\n","^還有一些人什麼也沒說，只是站起來走了——走的那些人傷他傷得最重。","\n","#","^clear","/#","^剛才朝他拱手的那幾位老前輩，現在一個也沒有看他。","\n","^他站在廳中央，手裡還握著半個時辰前贏來的東西。","\n","^那個東西在他說完那句話的瞬間就沒有了。","\n","^〔發言權：作廢〕","\n","ev","str","^喊回去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^看著小龍女","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^站著不動","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.hg_han"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.hg_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.hg_zhan"},"\n",{"#f":5}]}],{"hg_han":["ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^楊過：你們懂什麼！","\n","^他喊了。喊得很大聲。","\n","^喊完他忽然發現一件事：喊回去的音量，跟他有多在乎這些人的看法成正比。","\n","^他不想在乎的。但他喊了。","\n",{"->":"ch7_close"},null],"hg_kan":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^他沒有理那些聲音。他轉頭看她。","\n","^她站在那裡，臉上還是什麼表情也沒有。她大概不太明白這些人為什麼忽然這麼吵。","\n","^她只是往他身邊走近了半尺。","\n","^半尺。三尺變成兩尺半。","\n","^那半尺是她能給的全部，而對楊過來說，那半尺比整個廳都大。","\n",{"->":"ch7_close"},null],"hg_zhan":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他站著不動。","\n","^聲音在他周圍，但沒有進去。","\n","^他這一輩子被人罵過很多次。他發現這一次跟以前不一樣——以前他是被罵的那個人，這次他是選擇被罵的那個人。","\n","^選擇過的，就沒有那麼難受。","\n",{"->":"ch7_close"},null]}],"ch7_close":["#","^bg:荒野_黃昏獨行","/#","#","^fx:dust","/#","#","^clear","/#","^他們是走出去的，不是被趕出去的。","\n","^出了大勝關的門，天已經黃昏。官道很長，兩邊的野草被風吹得伏下去又起來。","\n","^兩個人走了很久都沒有說話。","\n","#","^clear","/#",["ev",{"VAR?":"xuangao"},3,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^小龍女：楊過。","\n","^楊過：嗯。","\n","^小龍女：你剛才說要娶我。","\n","^楊過：嗯。","\n","^小龍女：那是什麼意思。","\n","^楊過停下腳步。","\n","^他花了整整一炷香的時間，跟一個從來沒有人教過她這些事的人，解釋什麼叫娶。","\n","^解釋完她想了想，說：","\n","#","^emo:小龍女_笑","/#","^小龍女：好。","\n","^就這樣。全天下都反對的一件事，她只用了一個字。","\n",{"->":".^.^.^.20"},null]}],[{"->":".^.b"},{"b":["\n","^小龍女：他們為什麼那麼生氣。","\n","^楊過：因為我們不合規矩。","\n","^小龍女：規矩是誰定的。","\n","^楊過：……不知道。很多人一起定的吧。","\n","^小龍女：那些人現在在哪裡。","\n","^楊過：早就死了。","\n","^小龍女：死了的人定的規矩，還算數嗎。","\n","^楊過答不出來。","\n","^他忽然覺得，這輩子最厲害的那句話不是他今天在廳裡說的那四個字，","\n","^而是身邊這個人隨口問的這一句。","\n",{"->":".^.^.^.20"},null]}],"nop","\n","#","^clear","/#","^那天晚上他們在官道邊的破廟裡歇。","\n","^楊過睡不著。他一直在想廳裡那幾百張臉。","\n","^想到後來他翻了個身，看見她坐在門口，背對著他，看外頭的月亮。","\n","^他就不想那些臉了。","\n","^〔第七回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",9,{"VAR=":"qingyi"},6,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},0,{"VAR=":"sheng"},0,{"VAR=":"xuangao"},"/ev","end",null]}],"listDefs":{}},"ch08":{"inkVersion":21,"root":[[{"->":"ru_gu"},["done",{"#n":"g-0"}],null],"done",{"ru_gu":[["#","^bg:絕情谷_晨霧","/#","#","^fx:dust","/#","^那座山谷在南邊，很難找。","\n","^他們是聽人說的——說谷裡有位神醫，什麼傷都治得好。楊過肩上那道舊傷落了病根，每逢陰雨就抬不起來，小龍女聽說了就記在心上。","\n","^記在心上這件事她自己不覺得有什麼。是楊過發現的：她從來不說「我擔心你」，她只是忽然知道要往哪裡走。","\n","#","^clear","/#","^谷口有霧。","\n","^霧散開的時候，他們看見兩側石壁上長滿了藤蔓，藤上開著細碎的小花。","\n","^那花是紅的。","\n","^不是楓的紅，也不是血的紅。是一種很淺的紅，看久了會覺得那不是顏色，是溫度。","\n","^小龍女：這種花我沒見過。","\n","^楊過：好看。","\n","^小龍女：你別碰。","\n","ev","str","^伸手碰了","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^沒有碰","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["^ ",{"->":"ru_gu.peng"},"\n",{"#f":5}],"c-1":["^ ",{"->":"ru_gu.bu_peng"},"\n",{"#f":5}]}],{"bu_peng":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他把手收回來了。","\n","^他這輩子難得聽一次勸。","\n","^但走了三十步他還是回頭多看了一眼——那片紅實在太好看了。","\n",{"->":".^.^.peng"},null],"peng":["#","^clear","/#","^他還是碰了。","\n","^花莖上有刺。刺很細，細到扎進去的時候一點也不痛。","\n","^痛是後來才來的。而且不是從手上來的。","\n",{"->":"du_fa"},null]}],"du_fa":["ev",{"VAR?":"du"},1,"+",{"VAR=":"du","re":true},"/ev","#","^clear","/#","^那一下來得毫無道理。","\n","^他那時候正在想一件很小的事——想她剛才說「你別碰」的語氣，想那三個字裡有沒有一點點別的東西。","\n","^然後心口就像被人攥住了。","\n","^痛得他跪下去。","\n","#","^clear","/#",["ev",{"VAR?":"qingyi"},12,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^痛得很深。深到他一時分不清是心口痛還是別的什麼痛。","\n",{"->":"du_fa.23"},null]}],["ev",{"VAR?":"qingyi"},8,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^痛了大概十息。十息很長。","\n",{"->":"du_fa.23"},null]}],[{"->":".^.b"},{"b":["\n","^痛了一下就過去了。他還以為是自己岔了氣。","\n",{"->":"du_fa.23"},null]}],"nop","\n","^有個人從霧裡走出來，看了他一眼，說：","\n","#","^emo:公孫止","/#","^公孫止：情花的毒，想一次，痛一次。","\n","^公孫止：不想的人不會痛。你能不想嗎。","\n",{"->":"gongsun"},null],"gongsun":[["#","^bg:絕情谷_石屋","/#","#","^clear","/#","^那人是谷主，姓公孫。四十上下，長得端正，說話有條理。","\n","^他把他們請進谷裡，安排了住處，送了藥，樣樣周到。","\n","^周到到楊過一開始沒看出來哪裡不對。","\n","#","^clear","/#","^三天後他看出來了。","\n","^公孫止跟小龍女說話的時候，會多站近半步。他問她的來歷，問她師承，問她有沒有許過人家。","\n","^問到第三次的時候，楊過忍不住了。","\n","ev","str","^當場點破","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先不動聲色，看他要做什麼","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^問小龍女要不要走","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.gs_po"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.gs_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.gs_zou"},"\n",{"#f":5}]}],{"gs_po":["ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","ev",{"VAR?":"du"},1,"+",{"VAR=":"du","re":true},"/ev","^楊過：谷主，我師父已經許過人家了。","\n","^公孫止：喔？許了誰。","\n","^楊過：我。","\n","^公孫止臉上的笑沒有變。","\n","^公孫止：小兄弟，你可知道『師徒』兩個字在江湖上是什麼分量。","\n","^楊過：知道。大勝關幾百個人已經教過我了。","\n","^他說完就開始痛。","\n","^情花毒不管你講得多硬氣。你想到她一次，它就收一次。","\n",{"->":"gs_dan"},null],"gs_kan":["ev",{"VAR?":"zhenqi"},1,"+",{"VAR=":"zhenqi","re":true},"/ev","^他忍住了，什麼也沒說。","\n","^他開始留意谷裡的事——留意那些下人看谷主的眼神，留意谷裡為什麼沒有一個女眷，留意後院那間鎖著的屋子。","\n","^他發現這座谷比它看起來危險得多。","\n",{"->":"gs_dan"},null],"gs_zou":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","ev",{"VAR?":"du"},1,"+",{"VAR=":"du","re":true},"/ev","^楊過：我們走吧。","\n","^小龍女：你的傷還沒治。","\n","^楊過：不治了。","\n","^小龍女：為什麼。","\n","^楊過：……","\n","^他答不出來。他不知道要怎麼跟一個不懂人心的人解釋，那個人對她有什麼企圖。","\n","^小龍女：你又在想事情。","\n","^楊過：嗯。","\n","^小龍女：想我嗎。","\n","^楊過：……嗯。","\n","^然後他就痛了。","\n","^小龍女看著他跪下去，第一次露出了一點不知所措。","\n",{"->":"gs_dan"},null]}],"gs_dan":[["#","^bg:絕情谷_石屋","/#","#","^clear","/#","^情花的毒有藥。","\n","^那藥叫絕情丹，谷裡有，而且只有一顆。","\n","^公孫止把那顆藥放在桌上，推到他們面前。","\n","^公孫止：一顆。","\n","^公孫止：中毒的是這位小兄弟。不過——","\n","^他看了小龍女一眼。","\n","^公孫止：谷裡的規矩，藥不能白給。","\n","ev","str","^「你開條件。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「這藥我不要了。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔一把抓過藥丸〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"gs_dan.dan_tiao"},"\n",{"#f":5}],"c-1":["^ ",{"->":"gs_dan.dan_bu"},"\n",{"#f":5}],"c-2":["^ ",{"->":"gs_dan.dan_qiang"},"\n",{"#f":5}]}],{"dan_tiao":["ev",1,"/ev",{"VAR=":"dan","re":true},"^楊過：你開條件。","\n","^公孫止：留下來。","\n","^楊過：留誰。","\n","^公孫止：……","\n","^他沒有說名字。他只是又看了小龍女一眼。","\n","^楊過把那顆藥推了回去。","\n","^楊過：那我不要。","\n",{"->":"dan_end"},null],"dan_bu":["ev",2,"/ev",{"VAR=":"dan","re":true},"ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^楊過：這藥我不要了。","\n","^他說得很快，快到小龍女都愣了一下。","\n","^小龍女：你不要藥，那你怎麼辦。","\n","^楊過：不怎麼辦。忍著。","\n","^小龍女：忍多久。","\n","^楊過：忍到你不會被人拿走為止。","\n","^她沒有聽懂這句話。","\n","^但她看見了他的臉，於是她也把那顆藥推了回去。","\n",{"->":"dan_end"},null],"dan_qiang":["ev",3,"/ev",{"VAR=":"dan","re":true},"ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"^他伸手就抓。","\n","^公孫止的手比他快。兩隻手在桌上撞了一下，藥丸滾到地上，滾進了石縫。","\n","^滿屋子的人都僵住。","\n","^公孫止慢慢地笑了。","\n","^公孫止：小兄弟，這下誰也沒得吃了。","\n",{"->":"dan_end"},null]}],"dan_end":["#","^clear","/#","^事情就從那一刻起壞掉的。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n","^公孫止不再假裝客氣。他的人堵住了門。","\n",{"->":"g1"},null],"g1":[["^〔第一合〕","\n","ev","str","^一個人打（真氣 −5）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^跟她合手（真氣 −6）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^先找出口（真氣 −3）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"g1.g1_dan"},"\n",{"#f":5}],"c-1":["^ ",{"->":"g1.g1_he"},"\n",{"#f":5}],"c-2":["^ ",{"->":"g1.g1_chu"},"\n",{"#f":5}]}],{"g1_dan":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"^他自己上。","\n","^玉女心經一個人使，招式走到一半就停住——這個毛病三年了，一直沒好。","\n","^公孫止看出來了。","\n","^公孫止：你這套功夫少一個人。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"g2"},null],"g1_he":["ev",{"VAR?":"zhenqi"},6,"-","/ev",{"VAR=":"zhenqi","re":true},["ev",{"VAR?":"qingyi"},12,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^兩把劍同時動。","\n","^他往左，她往右，中間沒有空隙。玉女素心劍法在這種地方第一次真的派上用場——不是對練，是要命的。","\n","^公孫止退了三步。他這輩子沒見過兩個人可以打成一個人。","\n",{"->":".^.^.^.8"},null]}],[{"->":".^.b"},{"b":["\n","^他們想合手，但差了半息。","\n","^半息在對練場上不算什麼，在這裡就是一道口子。","\n","^楊過的肋下挨了一刀。","\n",{"->":".^.^.^.8"},null]}],"nop","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"g2"},null],"g1_chu":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"^他不戀戰，先看門窗。","\n","^前門有人，後窗太高，只有側邊那條通往後院的迴廊沒人守——因為那條路通向鎖著的屋子。","\n","^他記住了。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"g2"},null]}],"g2":[["^〔第二合〕","\n","ev",{"VAR?":"du"},2,">=","/ev",[{"->":".^.b","c":true},{"b":["^ 他的心口又開始收緊。這個時候毒發是最要命的。 ",{"->":"g2.0.8"},null]}],"nop","\n","ev","str","^拚了（真氣 −7）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^護著她退（真氣 −4）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^往後院衝（真氣 −5）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"g2.g2_pin"},"\n",{"#f":5}],"c-1":["^ ",{"->":"g2.g2_hu"},"\n",{"#f":5}],"c-2":["^ ",{"->":"g2.g2_hou"},"\n",{"#f":5}]}],{"g2_pin":["ev",{"VAR?":"zhenqi"},7,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"du"},1,"+",{"VAR=":"du","re":true},"/ev","^他拚了。","\n","^打到一半毒發，劍脫手落地，發出很脆的一聲。","\n","^他撿起來的時候手在抖。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"g_end"},null],"g2_hu":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他退到她背後。","\n","^小龍女：不要護我。","\n","^楊過：我沒有。","\n","^小龍女：你又有。","\n","^她一邊說一邊出劍，替他擋了兩下。","\n","^兩個人誰也沒有承認自己在護對方。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"g_end"},null],"g2_hou":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他拉著她往後院衝。","\n","^迴廊盡頭那間鎖著的屋子被他一腳踹開——裡頭關著一個瘦得脫形的婦人。","\n","^那婦人抬起頭，看了公孫止一眼，然後笑了。","\n","^那個笑讓公孫止的臉色第一次變了。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"g_end"},null]}],"g_end":["#","^bg:絕情谷_晨霧","/#","#","^fx:dust","/#","#","^clear","/#","^〔慘勝〕","\n","^他們出了谷。","\n","^出谷的時候楊過已經走不太動了。小龍女架著他的手臂，一步一步往外挪。","\n","^走到谷口那片花底下的時候，他吐了一次血。","\n","^那是情花毒第幾次發作，他已經數不清了。","\n","#","^clear","/#",["ev",{"VAR?":"dan"},2,"==","/ev",{"->":".^.b","c":true},{"b":["\n","^小龍女：你當初該吃那顆藥的。","\n","^楊過：吃了你怎麼辦。","\n","^小龍女：我又沒有中毒。","\n","^楊過：……","\n","^他忽然發現她真的不明白。","\n","^他也就沒有解釋。有些話解釋了就變味了。","\n",{"->":"g_end.25"},null]}],["ev",{"VAR?":"dan"},3,"==","/ev",{"->":".^.b","c":true},{"b":["\n","^那顆藥掉進石縫裡，誰也沒吃到。","\n","^楊過後來想起這件事，總覺得那是老天在暗示什麼。","\n","^暗示什麼他不知道，但總不是什麼好事。","\n",{"->":"g_end.25"},null]}],[{"->":".^.b"},{"b":["\n","^那顆藥留在公孫止手上。","\n","^往後很多年，每次毒發的時候，楊過都會想起桌上那顆推來推去的藥丸。","\n",{"->":"g_end.25"},null]}],"nop","\n","#","^clear","/#","^走出十里之後她把他放下來歇。","\n","^他靠著一塊石頭坐著，抬頭看天。天很藍，雲很高，什麼事都沒有發生過的樣子。","\n","^楊過：我可能活不了太久。","\n","^小龍女：那我陪你。","\n","^楊過：陪我做什麼。","\n","^小龍女：不做什麼。就陪著。","\n","^她說完就在他旁邊坐下了。","\n","^三尺。","\n","^還是三尺。","\n","^〔第八回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^　毒發 ","ev",{"VAR?":"du"},"out","/ev","^ 次〕","\n","end",null],"global decl":["ev",12,{"VAR=":"qingyi"},1,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},0,{"VAR=":"du"},0,{"VAR=":"dan"},"/ev","end",null]}],"listDefs":{}},"ch09":{"inkVersion":21,"root":[[{"->":"ying_ying"},["done",{"#n":"g-0"}],null],"done",{"ying_ying":[["#","^bg:襄陽_城外大營","/#","#","^fx:none","/#","^那年秋天他在襄陽。","\n","^宋軍在城外紮了大營，帳篷排到看不見邊。楊過是被請來的——他這幾年在江湖上做了些事，有些人開始覺得他有用。","\n","^有用不等於被喜歡。這兩件事他分得很清楚。","\n","#","^clear","/#","^郭芙也在。","\n","^她長大了，嫁了人，是郭家的女兒，也是營裡有名有姓的人物。她看見楊過的第一眼，臉就沉了。","\n","^那不是恨。楊過看得出來——那是一種更麻煩的東西：**她一看見他就覺得自己不對勁**，而她不知道為什麼，於是她把那份不對勁算在他頭上。","\n","^十幾年了。從桃花島那個院子開始，一直到現在。","\n","ev","str","^主動打招呼","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^當作沒看見","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^說一句刺她的話","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.zhao"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.bu_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.ci"},"\n",{"#f":5}]}],{"zhao":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：郭姑娘。","\n","^他叫得很客氣。","\n","^郭芙愣了一下，大概沒想到他會先開口。她「嗯」了一聲，轉身就走。","\n","^走了幾步她又停下來，像是想說什麼，最後還是走了。","\n","^楊過看著她的背影想：她大概也希望這件事可以不要這麼難。","\n",{"->":"chong_tu"},null],"bu_kan":["^他當作沒看見。","\n","^這幾年他學會了：有些人你越理，越有事。","\n","^但他沒有算到——不理也是一種態度，而且是更傷人的那一種。","\n",{"->":"chong_tu"},null],"ci":["ev",{"VAR?":"jin"},1,"+",{"VAR=":"jin","re":true},"/ev","ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^楊過：郭姑娘還是老樣子。看見我就像看見欠錢的。","\n","^郭芙的臉一下子紅了。","\n","^郭芙：楊過你——","\n","^楊過：我怎麼了。我又沒說錯。","\n","^他說完就走了。","\n","^他這輩子的毛病一直沒改：明知道會壞事，那句話還是要說。","\n",{"->":"chong_tu"},null]}],"chong_tu":[["#","^clear","/#","^事情是為了一件小事爆的。","\n","^小到楊過後來自己都想不起來確切是哪一句話。他只記得那天營裡吵了起來，起因跟武氏兄弟有關，跟一句舊帳有關，跟他的姓有關。","\n","^他記得郭芙站在他對面，臉漲得通紅，手在發抖。","\n","^他記得自己說了一句很不客氣的話。","\n","ev","str","^道歉，把事情按下去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^再頂一句","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^轉身走開","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ya"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.ding"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.zou"},"\n",{"#f":5}]}],{"ya":["ev",{"VAR?":"hui"},1,"+",{"VAR=":"hui","re":true},"/ev","^楊過：算了。是我不好。","\n","^他說完就準備轉身。","\n","^其實那一刻事情已經要過去了——如果他就這樣走掉，什麼也不會發生。","\n","^但他停了半息。","\n","^那半息裡他想的是：我憑什麼要道歉。","\n",{"->":"na_yi_jian"},null],"ding":["ev",{"VAR?":"jin"},1,"+",{"VAR=":"jin","re":true},"/ev","ev",{"VAR?":"hui"},2,"+","/ev",{"VAR=":"hui","re":true},"^他又頂了一句。","\n","^那句話很短，也很準。準到郭芙整個人僵在原地。","\n","^滿營的人都聽見了。","\n",{"->":"na_yi_jian"},null],"zou":["ev",{"VAR?":"hui"},1,"+",{"VAR=":"hui","re":true},"/ev","^他轉身就走。","\n","^走了三步。","\n","^三步之後他聽見身後有拔劍的聲音。","\n","^他沒有回頭。","\n",{"->":"na_yi_jian"},null]}],"na_yi_jian":["#","^clear","/#","^那把劍下來的時候，楊過沒有擋。","\n","#","^clear","/#","^他不是不能擋。以他那時候的功夫，郭芙那一劍，他閉著眼睛都躲得掉。","\n","#","^clear","/#","^他沒有擋，是因為——","\n","^那是郭芙。","\n","^是他從小認識的、會生氣會摔東西、會跟他吵一整個下午的郭芙。是那個他們三個人打他一個人的時候，站在旁邊沒有走開的郭芙。","\n","^他這輩子沒有防過她。","\n",[["ev",{"^->":"na_yi_jian.21.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^他根本沒有想到，這件事需要防。**",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"na_yi_jian.21.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n","#","^clear","/#","^右臂落在地上的時候，他還在看她的臉。","\n","#","^emo:楊過_斷臂_慟","/#","^他看見她臉上的表情從憤怒變成茫然，再從茫然變成一種他從來沒有在任何人臉上看過的東西。","\n","^那把劍從她手裡掉下來。","\n","^她比他先叫出聲。","\n",{"->":"zhi_hou"},{"#f":5}]}],null],"zhi_hou":[["#","^clear","/#","^後面的事他記得很亂。","\n","^有人喊軍醫。有人按住他。有人在他耳邊說話，說了很多，他一句也沒聽進去。","\n","^他一直在想一件很沒有道理的事：","\n","^那件衣服的袖子，明天要怎麼辦。","\n","#","^clear","/#",["ev",{"VAR?":"hui"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^郭芙被人架走了。她一路都在掙扎，一路在喊什麼，但沒有人聽得清楚。","\n","^後來有人告訴楊過，她那天喊的是「我不是故意的」。","\n","^他信。他從來沒有懷疑過那不是故意的。","\n","^但這件事不會因為不是故意的就長回來。","\n",{"->":".^.^.^.16"},null]}],[{"->":".^.b"},{"b":["\n","^郭芙站在原地，一動也不動。","\n","^她沒有哭，也沒有道歉。她就站在那裡，像是要把眼前這件事看清楚一點。","\n","^很多年以後楊過想起這一幕，忽然明白了：她那時候大概正在明白一件事——","\n","^她剛剛做的事情，是這輩子都改不回來的。","\n",{"->":".^.^.^.16"},null]}],"nop","\n","ev","str","^「不關她的事。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^〔什麼也沒說〕","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^看了她最後一眼","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.hou_bu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.hou_mo"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.hou_kan"},"\n",{"#f":5}]}],{"hou_bu":["ev",{"VAR?":"xiaming"},3,"+","/ev",{"VAR=":"xiaming","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：不關她的事。","\n","^他是在昏過去之前說的。聲音很小，但旁邊的人都聽見了。","\n","^這句話後來傳遍了襄陽。人們說神鵰俠斷了一條手臂，第一句話是替傷他的人開脫。","\n","^從那天起，江湖上開始有人真心敬他。","\n","^而楊過自己並不知道這件事。他當時只是覺得——追究也沒有用。","\n",{"->":"long_nv"},null],"hou_mo":["^他什麼也沒說。","\n","^他咬著牙，一聲也沒有出。","\n","^這是他從十一歲那年開始練的本事：疼的時候不要叫，叫了也沒有人來。","\n",{"->":"long_nv"},null],"hou_kan":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他看了她最後一眼。","\n","^那一眼裡沒有恨。他自己也覺得奇怪——應該要有恨的，可是沒有。","\n","^只有一種很累的東西。","\n","^他那時候想：原來一件事情壞到某個程度，就連生氣都生不動了。","\n",{"->":"long_nv"},null]}],"long_nv":[["#","^bg:荒野_黃昏獨行","/#","#","^fx:dust","/#","#","^clear","/#","^小龍女是第三天到的。","\n","^沒有人通知她。她就是知道了——楊過後來一直沒有問她是怎麼知道的，因為他隱約覺得答案會讓他難受。","\n","^她進帳的時候，他正背對著門躺著。","\n","^她沒有問傷得怎麼樣，也沒有問是誰做的。","\n","^她坐下來，把他的手拉過去握著。","\n","^握了很久。","\n","#","^clear","/#","^楊過：你不問嗎。","\n","^小龍女：問什麼。","\n","^楊過：問誰砍的。","\n","^小龍女：……","\n","^她想了想。","\n","#","^emo:小龍女_關","/#","^小龍女：問了他就會長回來嗎。","\n","^楊過：不會。","\n","^小龍女：那就不問。","\n","#","^clear","/#","^那天晚上他哭了。","\n","^不是為了手臂。他自己也說不上來是為了什麼。","\n","^她沒有勸他，也沒有問。她只是一直握著他剩下的那隻手，握到他睡著。","\n","ev","str","^「以後我沒有用了。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我還是我。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔什麼也沒說，只是握緊〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ye_wu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.ye_shi"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.ye_wo"},"\n",{"#f":5}]}],{"ye_wu":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：以後我沒有用了。","\n","^小龍女：什麼叫有用。","\n","^楊過：……會武功，能打，能保護人。","\n","^小龍女：那你以前有用嗎。","\n","^楊過：……","\n","^她問這句話一點惡意也沒有。她是真的在問。","\n","^楊過想了半天，忽然笑了一聲——那是他這三天第一次笑。","\n","^楊過：好像也沒有。","\n","^小龍女：那就一樣。","\n",{"->":"ch9_close"},null],"ye_shi":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^楊過：我還是我。","\n","^小龍女：嗯。","\n","^楊過：你信嗎。","\n","#","^emo:小龍女_關","/#","^小龍女：我又不是因為那隻手才跟你在一起的。","\n","^她說得很平常，平常到她根本不知道自己剛才說了一句多重的話。","\n","^楊過把臉轉過去，很久沒有出聲。","\n",{"->":"ch9_close"},null],"ye_wo":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^他什麼也沒說。","\n","^他只是把剩下的那隻手握緊了。","\n","^她感覺到了，就也握緊了一點。","\n","^兩個人在黑暗裡握著手，誰也沒有說話。這是他們認識以來話最少、也最近的一夜。","\n",{"->":"ch9_close"},null]}],"ch9_close":["#","^clear","/#","^傷口長了很久。","\n","^長好之後，那條空袖子他一直沒有剪短——他嫌麻煩，後來就習慣了。習慣之後別人反而覺得那樣好看。","\n","^他學會用一隻手做所有的事：吃飯、束髮、繫腰帶。最難的是穿衣服，他花了兩個月才不用人幫。","\n","^〔他二十多歲那年，失去了一條手臂。〕","\n","^〔往後六十年，他都是這樣過的。〕","\n","#","^clear","/#",["ev",{"VAR?":"qingyi"},16,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^那段日子她一直在。","\n","^她不會安慰人，一句好聽的話也不會說。她只是每天都在。","\n","^很多年以後楊過想：他這輩子最感激她的，不是她救過他幾次命，","\n","^是那兩個月她什麼也沒有說。","\n",{"->":".^.^.^.18"},null]}],[{"->":".^.b"},{"b":["\n","^那段日子他不太說話。","\n","^她也不太說話。","\n","^兩個人就這樣坐著，一天一天過去。","\n",{"->":".^.^.^.18"},null]}],"nop","\n","^〔第九回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",14,{"VAR=":"qingyi"},2,{"VAR=":"xiaming"},3,{"VAR=":"du"},0,{"VAR=":"jin"},0,{"VAR=":"hui"},"/ev","end",null]}],"listDefs":{}},"ch10":{"inkVersion":21,"root":[[{"->":"shen_diao"},["done",{"#n":"g-0"}],null],"done",{"shen_diao":[["#","^bg:山道_雨後","/#","#","^fx:dust","/#","^那隻鵰是他自己找上門的。","\n","^很大，很醜，羽毛稀稀落落，一隻腳有點跛。它不會飛——楊過後來確定它是真的不會，不是不肯。","\n","^它站在山路中間，擋住他的去路，看了他很久。","\n","^看完它轉身就走，走兩步回頭一次，像是在等他跟上。","\n","ev","str","^跟上去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^不理它","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^問它要做什麼","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.gen"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.bu_li"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.wen_diao"},"\n",{"#f":5}]}],{"bu_li":["^他繞過去了。","\n","^走了半里，那隻鵰又出現在他前面。","\n","^再繞，它再擋。","\n","^第三次的時候楊過站住了：「你到底要幹嘛。」","\n","^那隻鵰歪著頭看他。","\n",{"->":".^.^.gen"},null],"wen_diao":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你要帶我去哪。","\n","^那鵰當然不會回答。","\n","^但楊過發現一件事：這是三個月以來，他第一次主動跟什麼東西說話。","\n","^他跟上去了。","\n",{"->":".^.^.gen"},null],"gen":["#","^clear","/#","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他跟著那隻鵰走了三天。","\n","^三天裡它帶他繞過山、涉過溪、鑽過一片人走不進去的密林。有兩次楊過覺得自己走不動了，那隻鵰就停下來等，等到他起身為止。","\n","^第三天傍晚，他們到了一個沒有路的地方。","\n",{"->":"jian_zhong"},null]}],"jian_zhong":[["#","^bg:劍塚_荒谷","/#","#","^clear","/#","^那是一處山坳，四面是崖，只有一線天。","\n","^地上並排插著三把劍，劍身大半沒入土石。旁邊立著一塊粗糙的石碑，上頭的刻痕已經風化得不太看得清。","\n","^第一把劍很利。劍身青光閃閃，一看就知道是好東西。","\n","^第二把很輕。輕到楊過用一隻手都能舉起來揮個滿圈。","\n","^第三把不像劍。那是一段從山裡挖出來的黑鐵，沒有開鋒，鈍得像塊石頭，插在那裡像是誰隨手扔下的。","\n","ev","str","^拿第一把","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^拿第二把","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^看那塊黑鐵","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.j_li"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.j_qing"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.j_hei"},"\n",{"#f":5}]}],{"j_li":["^他先拔了那把利劍。","\n","^拔出來的瞬間他就知道不對——這把劍太快了。快到不容許出手的人有半分猶豫。","\n","^而他現在只有一隻手。一隻手的人，不能賭一擊。","\n","^他把它插回去了。","\n",{"->":".^.^.j_hei"},null],"j_qing":["ev",{"VAR?":"zhenqi"},1,"+",{"VAR=":"zhenqi","re":true},"/ev","^他拿了那把輕劍。","\n","^輕，好使，換手快。以他現在的狀況，這應該是最合適的一把。","\n","^他揮了幾下，越揮越順。","\n","^然後他停下來了。","\n","^他忽然明白自己在做什麼——他在找一把「適合殘廢的人用」的劍。","\n","^他把它插回去了。","\n",{"->":".^.^.j_hei"},null],"j_hei":["#","^clear","/#","ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他走到第三把前面。","\n","^那塊黑鐵埋得很深。他用一隻手拔，拔了三次沒拔動。第四次他整個人的重量都壓上去，才把它拖出來。","\n","^拖，不是拔。","\n","#","^clear","/#","^石碑上的字他認出了幾個。刻字的人說：這把劍重、鈍，四十歲之前他用它橫行天下。","\n","^四十歲之前。","\n","^楊過看著那行字，忽然笑了。","\n","#","^clear","/#","^楊過（對那隻鵰）：他四十歲之前用這個。他四十歲之後用什麼？","\n","^那隻鵰沒有回答。","\n","^楊過蹲下來，把石碑後面的土撥開，發現後面還有一行——","\n","^字說：後來他不用劍了。","\n","#","^clear","/#","^楊過在那塊碑前面坐了一整夜。","\n","^天亮的時候他站起來，把那塊黑鐵背在背上。","\n","^背，不是拿。他背了三天才習慣，習慣之後又花了兩個月才學會怎麼用一隻手把它從背上取下來而不摔倒。","\n","ev",true,"/ev",{"VAR=":"xuantie","re":true},"^〔得：玄鐵重劍〕","\n",{"->":"hai_chao"},null]}],"hai_chao":["#","^bg:海潮_暴雨","/#","#","^fx:none","/#","#","^clear","/#","^那隻鵰把他帶到海邊。","\n","^它站在礁石上看著他，然後用喙指了指海。","\n","^楊過：你要我下去？","\n","^那鵰不動。","\n","^楊過：這是海。","\n","^那鵰還是不動。","\n","^楊過罵了一句，把外衣脫了，拖著那塊黑鐵下水。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c1"},null],"c1":[["^〔第一次〕","\n","^潮從很遠的地方來。來的時候沒有聲音，到了才有。","\n","ev","str","^硬劈（真氣 −6）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^等它到跟前再動（真氣 −3）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^讓它打（真氣 −4）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"c1.c1_pi"},"\n",{"#f":5}],"c-1":["^ ",{"->":"c1.c1_deng"},"\n",{"#f":5}],"c-2":["^ ",{"->":"c1.c1_rang"},"\n",{"#f":5}]}],{"c1_pi":["ev",{"VAR?":"zhenqi"},6,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chao"},1,"+",{"VAR=":"chao","re":true},"/ev","^他劈。","\n","^太慢。潮先到。","\n","^他被推回岸上，滾了三圈，滿嘴是沙。","\n","^那隻鵰在岸上看著，一動也不動。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c2"},null],"c1_deng":["ev",{"VAR?":"zhenqi"},3,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chao"},2,"+","/ev",{"VAR=":"chao","re":true},"^他不動，只看。","\n","^看浪從遠處堆起、成形、往前推。看到最後一刻他才出手。","\n","^黑鐵下去的時候，浪的前緣碎了一小塊。","\n","^一小塊。比他的巴掌還小。","\n","^但那是海。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c2"},null],"c1_rang":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chao"},1,"+",{"VAR=":"chao","re":true},"/ev","^他不擋，讓潮打過來。","\n","^那一下把他打得整個人離地。","\n","^他在水裡翻了兩圈才站起來。站起來的時候他發現自己還握著那塊黑鐵——一隻手，握住了。","\n","^他忽然很想笑。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c2"},null]}],"c2":[["^〔第二次〕","\n","ev",{"VAR?":"chao"},2,">=","/ev",[{"->":".^.b","c":true},{"b":["^ 這一次他知道要看哪裡了。 ",{"->":"c2.0.8"},null]}],"nop","\n","ev","str","^順著浪的方向走（真氣 −4）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^逆著浪站住（真氣 −7）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^在浪碎的那一瞬出手（真氣 −5）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"c2.c2_shun"},"\n",{"#f":5}],"c-1":["^ ",{"->":"c2.c2_ni"},"\n",{"#f":5}],"c-2":["^ ",{"->":"c2.c2_sui"},"\n",{"#f":5}]}],{"c2_shun":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chao"},1,"+",{"VAR=":"chao","re":true},"/ev","^他不跟海硬拚，順著浪走。","\n","^浪推他，他就走；浪退，他就跟。","\n","^走了半個時辰他發現一件事：他不必比海強。他只要不被帶走。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c_end"},null],"c2_ni":["ev",{"VAR?":"zhenqi"},7,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chao"},2,"+","/ev",{"VAR=":"chao","re":true},"^他把腳踩進沙裡，逆著浪站住。","\n","^第一波把他推退了三尺。第二波兩尺。第三波一尺。","\n","^第七波的時候他沒有退。","\n","^他站在那裡，水到胸口，一隻手拖著一塊沒開鋒的黑鐵。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c_end"},null],"c2_sui":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"chao"},2,"+","/ev",{"VAR=":"chao","re":true},"^他等浪碎的那一瞬。","\n","^浪頭翻過來、往下砸、就要碎的那半息——那是整道浪最弱的地方。","\n","^他劈進去了。","\n","^水從中間分開，分了大概一尺寬。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"c_end"},null]}],"c_end":["#","^clear","/#","^他在海邊待了半年。","\n","^半年裡他不說話，也沒有人跟他說話。那隻鵰每天蹲在同一塊礁石上看他，偶爾去抓條魚給他。","\n","^半年之後他上岸，把黑鐵從背上取下來——一隻手，一個動作，沒有摔倒。","\n",["ev",{"VAR?":"chao"},5,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^那半年他練出來的不是招式。","\n","^是一種很難講的東西：他不再想「我少了一隻手」，他開始想「我這隻手能做什麼」。","\n","^這兩件事聽起來一樣，其實差很多。","\n",{"->":"c_end.12"},null]}],["ev",{"VAR?":"chao"},3,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^那半年他把重劍練順了。","\n","^他知道自己還沒到，但他知道路在哪裡。","\n",{"->":"c_end.12"},null]}],[{"->":".^.b"},{"b":["\n","^那半年他勉強能用了。","\n","^他覺得自己還差得遠。","\n",{"->":"c_end.12"},null]}],"nop","\n",{"->":"ch10_close"},null],"ch10_close":[["#","^bg:荒野_黃昏獨行","/#","#","^fx:dust","/#","#","^clear","/#","^離開海邊那天，他站在礁石上跟那隻鵰說話。","\n","^楊過：喂。","\n","^那鵰看他。","\n","^楊過：你叫什麼名字。","\n","^那鵰當然沒有回答。","\n","^楊過想了想。","\n","ev","str","^「以後你跟著我。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「你不用跟著我。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^替牠取個名字","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ming_gen"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.ming_bu"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.ming_qu"},"\n",{"#f":5}]}],{"ming_gen":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：以後你跟著我。","\n","^那隻鵰動也沒動。","\n","^但他走的時候，它跟上了。","\n","^從那天起牠跟了他很多年，久到楊過後來會忘記自己曾經是一個人。","\n",{"->":"ch10_end"},null],"ming_bu":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：你不用跟著我。我這個人不太值得跟。","\n","^那隻鵰歪著頭看他，然後轉身，往他要去的方向先走了。","\n","^楊過在後面愣了一下，罵了一句，跟上去。","\n",{"->":"ch10_end"},null],"ming_qu":["^楊過：我叫你……","\n","^他想了半天，一個名字也想不出來。","\n","^楊過：算了。你也不需要名字。","\n","^楊過：反正這世上會叫你的只有我一個。","\n","^他說完自己愣了一下——這句話聽起來怎麼有點慘。","\n","^那隻鵰啄了他一下。","\n",{"->":"ch10_end"},null]}],"ch10_end":["#","^clear","/#","^那年他二十多歲，一隻手，一塊沒開鋒的黑鐵，一隻不會飛的鵰。","\n","^他往北走。","\n","^北邊在打仗，而他知道她在北邊。","\n","^〔第十回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^　玄鐵重劍：","ev",{"VAR?":"xuantie"},"out","/ev","^〕","\n","end",null],"global decl":["ev",16,{"VAR=":"qingyi"},5,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},false,{"VAR=":"xuantie"},0,{"VAR=":"chao"},"/ev","end",null]}],"listDefs":{}},"ch11":{"inkVersion":21,"root":[[{"->":"wei_cheng"},["done",{"#n":"g-0"}],null],"done",{"wei_cheng":[["#","^bg:襄陽_城外大營","/#","#","^fx:none","/#","^蒙古人圍了襄陽。","\n","^圍了三個月，城裡的糧開始算著吃，城外的營帳排到看不見邊。城牆上每天都有人下來，也每天都有人上去。","\n","^楊過跟小龍女在城裡。他們不是為了守城來的——他們是路過，然後就走不了了。","\n","#","^clear","/#","^那晚郭夫人生了。","\n","^生了兩個，一男一女。城裡打了半年仗，這是頭一件讓人高興的事。","\n","^楊過在院子外頭聽著裡面的動靜，聽了半個時辰。","\n","^小龍女：你在聽什麼。","\n","^楊過：聽小孩。","\n","^小龍女：小孩有什麼好聽的。","\n","^楊過：……不知道。就是想聽。","\n","#","^clear","/#","^他自己也說不上來為什麼。","\n","^可能是因為這座城裡每天都在死人，而剛才有兩個人出生。","\n","ev","str","^進去看看","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^在外頭站著就好","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^問她想不想要小孩","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.jin_kan"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.wai_zhan"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.wen_hai"},"\n",{"#f":5}]}],{"jin_kan":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他進去了。","\n","^那兩個孩子皺巴巴的，紅通通的，一點也不好看。他看了很久。","\n","^黃蓉躺在床上，臉色很白。她看見楊過，愣了一下。","\n","^十幾年沒見了。上一次見面的時候他還是個孩子。","\n","^黃蓉：過兒。","\n","^楊過：郭伯母。","\n","^兩個人都沒有再往下說。有些帳算不清楚，也就不算了。","\n",{"->":"li_lai"},null],"wai_zhan":["^他站在院子外頭，一直站到天亮。","\n","^裡頭的燈熄了又亮。有人進進出出，端水端布，沒有人注意到他。","\n","^他就這樣站著。他也不知道自己在等什麼。","\n",{"->":"li_lai"},null],"wen_hai":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你想不想要小孩。","\n","^小龍女：……","\n","^她想了很久。久到楊過以為她沒聽懂。","\n","^小龍女：我不知道那是什麼感覺。","\n","^楊過：什麼感覺。","\n","^小龍女：有一個人，是從你這裡長出來的。","\n","^她說完自己也覺得這句話怪，就沒有再說。","\n","^楊過看著她的側臉，忽然覺得心口很緊——不是毒發，是別的。","\n",{"->":"li_lai"},null]}],"li_lai":["#","^clear","/#","^第二天夜裡，那個女嬰不見了。","\n","^滿城翻遍了，沒有。城門守得死死的，人出不去。","\n","^楊過是最先想到的：出不去的人，不代表出不去的路。","\n","^他在城西一段廢棄的水道口找到了痕跡——一縷黃色的衣料，和一股很淡的香氣。","\n","^那個香氣他這輩子忘不掉。","\n","#","^clear","/#","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n","^李莫愁抱著孩子站在水道盡頭的空地上。","\n","^十幾年了。她一點也沒有老。","\n","^李莫愁：楊過。","\n","^楊過：把孩子放下。","\n","^李莫愁：這孩子姓郭。郭家欠我的。","\n","^楊過：她三天大。","\n","^李莫愁笑了。","\n","^李莫愁：我妹妹死的時候也沒多大。","\n",{"->":"jiu_1"},null],"jiu_1":[["^〔第一合〕","\n","ev","str","^先搶孩子（真氣 −6）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^跟她說話，拖時間（真氣 −2）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^跟小龍女合手（真氣 −5）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"jiu_1.j1_qiang"},"\n",{"#f":5}],"c-1":["^ ",{"->":"jiu_1.j1_shuo"},"\n",{"#f":5}],"c-2":["^ ",{"->":"jiu_1.j1_he"},"\n",{"#f":5}]}],{"j1_qiang":["ev",{"VAR?":"zhenqi"},6,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"jiu"},1,"+",{"VAR=":"jiu","re":true},"/ev","^他直接撲上去搶。","\n","^李莫愁沒有躲——她把孩子往旁邊一送，正好擋在楊過的手要去的位置。","\n","^他硬生生把力道收住。收得太急，肋下被拂塵抽中。","\n","^李莫愁：你不敢傷她。那你就打不贏我。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"jiu_2"},null],"j1_shuo":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"jiu"},2,"+","/ev",{"VAR=":"jiu","re":true},"^楊過：那孩子在哭。","\n","^李莫愁：關我什麼事。","\n","^楊過：她餓了。你抱了她一整夜，她一口奶都沒喝。","\n","^李莫愁低頭看了看懷裡。","\n","^就那一眼。她的手臂鬆了半分。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"jiu_2"},null],"j1_he":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},["ev",{"VAR?":"qingyi"},16,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^兩把劍同時動。玉女素心劍法。","\n","^李莫愁退了兩步——她這輩子沒見過兩個人可以打成一個人。","\n","^李莫愁：這是……古墓的？","\n","^她的臉第一次變了。","\n",{"->":".^.^.^.8"},null]}],[{"->":".^.b"},{"b":["\n","^十六年沒有一起出過手的兩個人，是接不上的。","\n","^她的劍在等他，他的劍在等她——兩個人都在等，那就是空的。","\n","^李莫愁從那個空隙裡穿過去，拂塵掃過楊過的臉，留下三道血痕。","\n",{"->":".^.^.^.8"},null]}],"nop","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"jiu_2"},null]}],"jiu_2":[["^〔第二合〕","\n","ev",{"VAR?":"du"},4,">=","/ev",[{"->":".^.b","c":true},{"b":["^ 他的心口忽然收緊。這個時候毒發，最要命。 ",{"->":".^.^.^.8"},null]}],"nop","\n","ev","str","^硬拚（真氣 −7）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^讓小龍女去接孩子，自己纏住她（真氣 −5）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^用玄鐵重劍砸地（真氣 −4）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"jiu_2.j2_pin"},"\n",{"#f":5}],"c-1":["^ ",{"->":"jiu_2.j2_chan"},"\n",{"#f":5}],"c-2":["^ ",{"->":"jiu_2.j2_za"},"\n",{"#f":5}]}],{"j2_pin":["ev",{"VAR?":"zhenqi"},7,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"du"},1,"+",{"VAR=":"du","re":true},"/ev","^他拚了。","\n","^拚到一半毒發，重劍脫手，砸在地上震起一片塵。","\n","^他撲上去用一隻手抱住了孩子，背上結結實實挨了一下。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"jiu_end"},null],"j2_chan":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"jiu"},2,"+","/ev",{"VAR=":"jiu","re":true},"ev",true,"/ev",{"VAR=":"zhen","re":true},"^楊過：龍兒，接孩子！","\n","^他整個人撞上去纏住李莫愁。小龍女從側面切進來，一把把孩子接住。","\n","^接住的那一瞬，李莫愁反手一揚。","\n","^一點寒光。很細，很快。","\n","^小龍女沒有躲——她兩隻手都抱著孩子。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"jiu_end"},null],"j2_za":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"jiu"},1,"+",{"VAR=":"jiu","re":true},"/ev","^他用重劍砸地。","\n","^那塊沒有開鋒的黑鐵砸下去，整片空地都震了一下。李莫愁站不穩，孩子從她手裡滑出來。","\n","^楊過用一隻手接住了。","\n","^接住之後他才發現自己的手在抖。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"jiu_end"},null]}],"jiu_end":["#","^clear","/#","^〔孩子救回來了〕","\n",["ev",{"VAR?":"zhen"},"/ev",{"->":".^.b","c":true},{"b":["\n","^但小龍女中了針。","\n","^那針很細，扎在肩上，只有一個小點，連血都沒怎麼流。","\n","^她自己都沒發現。是楊過看見的。","\n","^楊過：你的肩膀。","\n","^小龍女：怎麼了。","\n","^楊過：……沒事。","\n","^他撒了謊。他這輩子沒有對她撒過謊，這是第一次。","\n","^因為他認得那種針。他在陸家那兩個姑娘身上見過那種傷。","\n",{"->":".^.^.^.7"},null]}],[{"->":".^.b"},{"b":["\n","^李莫愁走了。她走得很快，快到不像是打輸了。","\n","^楊過抱著孩子站在空地上，忽然覺得不太對勁——她不是打不過。","\n","^她只是不想在這裡把事情做完。","\n",{"->":".^.^.^.7"},null]}],"nop","\n",{"->":"huan_hai"},null],"huan_hai":[["#","^bg:襄陽_城外大營","/#","#","^clear","/#","^他把孩子抱回城裡。","\n","^天已經亮了。城牆上的人看見他一隻手抱著個嬰兒走進來，先是愣住，然後有人喊了一聲。","\n","^那一聲之後，滿城的人都在喊。","\n","#","^clear","/#","^黃蓉接過孩子的時候，手在抖。","\n","^她看著楊過，張了張嘴，最後只說了兩個字。","\n","^黃蓉：謝謝。","\n","^十幾年來她對他說過很多話。這兩個字是最短的，也是唯一一句她說得完全沒有保留的。","\n","ev","str","^「不用謝。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「這孩子叫什麼。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔搖搖頭，轉身要走〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.h_bu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.h_ming"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.h_zou"},"\n",{"#f":5}]}],{"h_ming":["ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：這孩子叫什麼。","\n","^黃蓉：還沒取。","\n","^楊過：那我能不能……","\n","^他說到一半就停了。他覺得自己沒有資格。","\n","^黃蓉看著他，忽然說：","\n","^黃蓉：她生在襄陽。就叫襄兒吧。","\n","#","^clear","/#","^〔郭襄。〕","\n","^〔十六年後，這個名字會在這個故事裡再出現一次。〕","\n",{"->":"ch11_close"},null],"h_bu":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：不用謝。","\n","^他說得很快，快到像在躲什麼。","\n","^黃蓉看著他的背影，忽然明白了一件她十幾年前沒明白的事——","\n","^這孩子從來不是他父親。他只是長得像。","\n",{"->":"ch11_close"},null],"h_zou":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他搖搖頭，轉身要走。","\n","^走了兩步，黃蓉在後面說：","\n","^黃蓉：過兒。","\n","^楊過：嗯。","\n","^黃蓉：……你長大了。","\n","^他沒有回頭。他怕一回頭就會問出那個問了十幾年的問題。","\n",{"->":"ch11_close"},null]}],"ch11_close":["#","^clear","/#","^那天下午，他在城牆上找到小龍女。","\n","^她坐在垛口邊上，看著城外的營帳，看了很久。","\n","#","^clear","/#",["ev",{"VAR?":"zhen"},"/ev",{"->":".^.b","c":true},{"b":["\n","^楊過：你的肩膀還痛嗎。","\n","^小龍女：不痛。","\n","^楊過：真的不痛？","\n","^小龍女：真的。","\n","^她說的是實話。那種針的可怕之處就在這裡——中了之後不痛。","\n","^等到痛的時候，就已經來不及了。","\n","#","^clear","/#","^楊過坐到她旁邊。","\n","^楊過：我們去找解藥。","\n","^小龍女：什麼解藥。","\n","^楊過：……我的。情花的。","\n","^小龍女：喔。","\n","^她答應得很輕鬆。","\n","^她一直到很後來才知道，那天他要找的解藥，其實是兩份。","\n",{"->":".^.^.^.12"},null]}],[{"->":".^.b"},{"b":["\n","^楊過：你在看什麼。","\n","^小龍女：那些帳篷。","\n","^楊過：怎麼了。","\n","^小龍女：它們排得很整齊。","\n","^她說得很認真。","\n","^楊過忽然笑了。他這輩子認識的人裡，只有她會在一座被圍了三個月的城牆上，評論敵軍的帳篷排得整不整齊。","\n",{"->":".^.^.^.12"},null]}],"nop","\n","#","^clear","/#","^太陽落下去的時候，他的心口又收緊了一次。","\n","^他沒有讓她看見。","\n","^〔第十一回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^　毒發 ","ev",{"VAR?":"du"},"out","/ev","^ 次〕","\n","end",null],"global decl":["ev",17,{"VAR=":"qingyi"},6,{"VAR=":"xiaming"},12,{"VAR=":"zhenqi"},4,{"VAR=":"du"},false,{"VAR=":"zhen"},0,{"VAR=":"jiu"},"/ev","end",null]}],"listDefs":{}},"ch12":{"inkVersion":21,"root":[[{"->":"hui_gu"},["done",{"#n":"g-0"}],null],"done",{"hui_gu":["#","^bg:絕情谷_晨霧","/#","#","^fx:dust","/#","^他們回了絕情谷。","\n","^去的時候小龍女已經走不快了。那根針的毒是慢的，慢到你以為它不存在，然後有一天早上你發現自己的手抬不起來。","\n","^楊過背她走了最後那三十里。一隻手背不動人，他就把她綁在背上。","\n","^綁的時候她說：","\n","^小龍女：這樣很難看。","\n","^楊過：難看就難看。","\n","^小龍女：……好。","\n","#","^clear","/#","^谷口那片花還在開。","\n","^那種很淺的紅，看久了會覺得那不是顏色，是溫度。","\n","^三年前他在這裡伸手碰了一下，痛到現在。","\n",{"->":"yao"},null],"yao":[["#","^bg:絕情谷_石屋","/#","#","^clear","/#","^谷裡換了主人。當年那位谷主已經死了，谷底那個被關了很多年的婦人成了新的主事者。","\n","^她給了他們一顆藥。","\n","^只有一顆。","\n","#","^clear","/#","^那是絕情丹。谷裡最後一顆。","\n","^婦人：吃了它，情花的毒就解了。","\n","^楊過：那她的毒呢。","\n","^婦人：她的毒我沒有藥。","\n","^她說得很直接，直接到楊過一時反應不過來。","\n","^婦人：不過那孩子的毒是慢的。你的是快的。","\n","^婦人：你要是不吃，你活不過半年。她還能撐一兩年。","\n","#","^clear","/#","^那顆藥放在桌上。","\n","^兩個人都沒有伸手。","\n","ev","str","^「你吃。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我不吃。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔把藥收進懷裡，什麼也沒說〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"yao.yao_ni"},"\n",{"#f":5}],"c-1":["^ ",{"->":"yao.yao_bu"},"\n",{"#f":5}],"c-2":["^ ",{"->":"yao.yao_shou"},"\n",{"#f":5}]}],{"yao_ni":["ev",1,"/ev",{"VAR=":"dan","re":true},"ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你吃。","\n","^小龍女：這是解情花毒的。我沒有中情花毒。","\n","^楊過：那也吃。","\n","^小龍女：吃了沒有用。","\n","^楊過：吃了我心裡有用。","\n","^她看著他，過了很久才開口。","\n","^小龍女：楊過。","\n","^楊過：嗯。","\n","^小龍女：你這樣講話，我不知道要怎麼回。","\n",{"->":"yao_hou"},null],"yao_bu":["ev",2,"/ev",{"VAR=":"dan","re":true},"ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^楊過：我不吃。","\n","^婦人：你會死。","\n","^楊過：那就死。","\n","^小龍女在旁邊聽著，忽然說：","\n","^小龍女：他不吃，我也不吃。","\n","^婦人：這藥對你沒有用。","\n","^小龍女：那更好。那我陪他。","\n","^婦人看著這兩個人，嘆了口氣，什麼也沒再說。","\n",{"->":"yao_hou"},null],"yao_shou":["ev",3,"/ev",{"VAR=":"dan","re":true},"^他把藥收進懷裡。","\n","^他沒有說要給誰吃，也沒有說不吃。","\n","^小龍女沒有問。她大概以為他是要留著慢慢想。","\n","^其實他心裡已經想好了——他要等她睡著，然後想辦法讓她吃下去。","\n","^他一直沒有找到機會。","\n",{"->":"yao_hou"},null]}],"yao_hou":["#","^clear","/#","^那天晚上他們住在谷裡。","\n","^半夜楊過醒過來，發現她不在床上。","\n","^他找出去，看見她站在院子裡，抬頭在看天。","\n","^那晚沒有月亮，天上只有幾顆很淡的星。","\n","^小龍女：楊過。","\n","^楊過：嗯。","\n","^小龍女：人死了以後會去哪裡。","\n","^楊過：……不知道。","\n","^小龍女：喔。","\n","^她沒有再問。","\n","^楊過站在她背後，忽然很想說一句什麼，但他想不出來有哪一句話在這種時候不是廢話。","\n",{"->":"huang_rong"},null],"huang_rong":[["#","^clear","/#","^第三天，黃蓉來了。","\n","^她是從襄陽趕來的，走了六天。她見到小龍女的第一眼就知道了——她是懂醫的人，一眼就看得出還剩多久。","\n","^她把楊過拉到一邊。","\n","#","^clear","/#","^黃蓉：過兒，我跟你說一件事。","\n","^楊過：什麼事。","\n","^黃蓉：南海有一位神尼，醫術通天。她能解這種毒。","\n","^楊過的呼吸停了一下。","\n","^黃蓉：不過她的規矩很怪。她要病人在她那裡住滿十六年，一天也不能少。十六年之內，外人不能見。","\n","^楊過：十六年。","\n","^黃蓉：十六年。","\n","#","^clear","/#","ev","str","^信了","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「你騙我。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔看著她，沒有說話〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.hr_xin"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.hr_po"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.hr_kan"},"\n",{"#f":5}]}],{"hr_xin":["ev",0,"/ev",{"VAR=":"zhi","re":true},"^他信了。","\n","^他抓著這句話，像抓著一塊浮木。","\n","^十六年很長，但十六年之後她會回來——這比「她活不過兩年」好太多了，好到他來不及去想這件事有多不合理。","\n","^他後來想了很多年才明白：一個人在快要失去一切的時候，會相信任何給得出希望的東西。","\n",{"->":"duan_chang"},null],"hr_po":["ev",2,"/ev",{"VAR=":"zhi","re":true},"ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：郭伯母，你騙我。","\n","^黃蓉的臉色變了一下。","\n","^楊過：世上沒有這種規矩。哪有醫人要醫十六年的。","\n","^黃蓉沉默了很久。","\n","^黃蓉：……那你要我怎麼說。","\n","^黃蓉：我要怎麼跟你說，才能讓你不跟著她一起死。","\n","#","^clear","/#","^楊過看著她。","\n","^這是他這輩子第一次看見黃蓉沒有辦法。","\n","^他忽然明白了：她騙他，是因為她想不出別的方法讓他活下去。","\n","^那天他沒有再拆穿。他假裝信了。","\n","^兩個人各自知道對方在演，各自都演完了。","\n",{"->":"duan_chang"},null],"hr_kan":["ev",1,"/ev",{"VAR=":"zhi","re":true},"^他看著她，沒有說話。","\n","^黃蓉是何等聰明的人——她從那個眼神裡看出來，這孩子多半是不信的。","\n","^但她還是把話說完了。她必須說完。","\n","^而楊過也讓她說完了。","\n",{"->":"duan_chang"},null]}],"duan_chang":["#","^bg:斷腸崖_日落","/#","#","^fx:dust","/#","#","^clear","/#","^第十天早上，小龍女不見了。","\n","#","^clear","/#","^楊過找遍了谷裡每一個地方。找到日頭偏西，他才想起谷後那座崖。","\n","^那座崖沒有名字。谷裡的人叫它斷腸崖，因為崖下是一片看不見底的雲。","\n","#","^clear","/#","^他跑上去的時候，太陽正好落在雲海的另一端。","\n","^整片雲被染成橙金與桃紅。崖壁是深藍色的剪影。天空的上半部已經轉成深青，有一顆很亮的星剛剛出來。","\n","#","^clear","/#","^崖邊沒有人。","\n","^只有崖壁上多了兩行字。","\n","#","^clear","/#","^那兩行字刻得很淺。","\n","^刻的人手上沒有力氣，每一筆都是斷斷續續拖出來的。有幾個字刻到一半歪掉了，又重新描過。","\n","^字說：十六年後，在此相會。","\n","^第二行說：夫妻情深，勿失信約。","\n","#","^clear","/#","^楊過站在那兩行字前面。","\n","^他一開始沒有反應過來。他讀了一遍，讀了第二遍，讀到第三遍的時候他忽然跪下去了。","\n","#","^clear","/#","^他跪在那裡，把那兩行字又讀了幾十遍。","\n","^他讀的是「十六年後」。","\n","^他一直讀的都是「十六年後」。","\n","#","^clear","/#","^〔他沒有讀出另一件事。〕","\n","^〔一個要走十六年的人，不會挑一塊崖來寫字。〕","\n","^〔她不是要他等十六年。〕","\n","^〔她是要他活十六年。〕","\n",{"->":"after"},null],"after":[["#","^clear","/#","^天黑透了他才站起來。","\n","^他在崖邊坐了一整夜。第二天他下到谷底去找——繩子不夠長，他就跳。水很深，深到他沉下去的時候還有時間想事情。","\n","^谷底沒有屍體。","\n","#","^clear","/#","^沒有屍體這件事，可以有兩種解釋。","\n","^一種是她被水沖走了。","\n","^一種是她還活著。","\n","#","^clear","/#","ev","str","^選相信她還活著","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^兩種都想過，然後不再想","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「我下去找她。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"after.xin_huo"},"\n",{"#f":5}],"c-1":["^ ",{"->":"after.bu_xiang"},"\n",{"#f":5}],"c-2":["^ ",{"->":"after.xia_qu"},"\n",{"#f":5}]}],{"xin_huo":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^他選了對他比較好的那一種。","\n","^然後他在那個解釋上面，住了十六年。","\n","^他知道自己在做什麼。他不是傻。","\n","^他只是發現，人要活下去，總得抓住一點什麼。","\n",{"->":"ch12_close"},null],"bu_xiang":["ev",{"VAR?":"zhi"},1,"+",{"VAR=":"zhi","re":true},"/ev","^兩種他都想過。","\n","^想到後來他把這件事收起來，放在心裡一個不常打開的地方。","\n","^他跟自己說：等十六年到了再打開。","\n","^十六年裡他打開過很多次。每一次都趕快關上。","\n",{"->":"ch12_close"},null],"xia_qu":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：我下去找她。","\n","^那隻鵰擋在他前面。","\n","^他推它，它不動。他罵它，它也不動。","\n","^最後他坐在地上，跟一隻鵰吵了一個時辰。吵到最後他自己也不知道在吵什麼。","\n","^那隻鵰一直站在那裡，等他吵完。","\n",{"->":"ch12_close"},null]}],"ch12_close":["#","^bg:斷腸崖_日落","/#","#","^clear","/#","^他在絕情谷底找了整整一年。","\n","^每一塊石頭都翻過。翻完一遍，他從頭再翻一遍，因為第一遍可能漏了。","\n","#","^clear","/#","^一年之後他上來了。","\n","^他上來的時候身上什麼也沒有，只有背上那塊沒有開鋒的黑鐵，和身邊那隻不會飛的鵰。","\n","^他在崖邊站了很久，然後伸手，把那兩行字描了一遍。","\n","^描的時候他的手很穩。","\n","#","^clear","/#","^〔那年他二十九歲。〕","\n","^〔他要等到四十五歲。〕","\n","^〔第十二回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",19,{"VAR=":"qingyi"},8,{"VAR=":"xiaming"},5,{"VAR=":"du"},0,{"VAR=":"dan"},0,{"VAR=":"zhi"},"/ev","end",null]}],"listDefs":{}},"ch13":{"inkVersion":21,"root":[[{"->":"nian_biao"},["done",{"#n":"g-0"}],null],"done",{"nian_biao":[["#","^bg:雪原_夜行","/#","#","^fx:snow","/#","ev",{"VAR?":"nian"},6,">=","/ev",[{"->":".^.b","c":true},{"b":["^ ",{"->":"shi_liu_nian"},{"->":".^.^.^.12"},null]}],"nop","\n","ev",{"VAR?":"nian"},0,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 第一年他在谷底。第二年他上來了。 ",{"->":".^.^.^.20"},null]}],"nop","\n","ev",{"VAR?":"nian"},1,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又過了兩年。 ",{"->":".^.^.^.28"},null]}],"nop","\n","ev",{"VAR?":"nian"},2,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又過了兩年。 ",{"->":".^.^.^.36"},null]}],"nop","\n","ev",{"VAR?":"nian"},3,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又過了三年。 ",{"->":".^.^.^.44"},null]}],"nop","\n","ev",{"VAR?":"nian"},4,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又過了兩年。 ",{"->":".^.^.^.52"},null]}],"nop","\n","ev",{"VAR?":"nian"},5,"==","/ev",[{"->":".^.b","c":true},{"b":["^ 又過了三年。 ",{"->":".^.^.^.60"},null]}],"nop","\n","#","^clear","/#","ev","str","^〈名〉","/str",{"CNT?":".^.^.u_ming"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^〈燈〉","/str",{"CNT?":".^.^.u_deng"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^〈冬〉","/str",{"CNT?":".^.^.u_dong"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^〈數〉","/str",{"CNT?":".^.^.u_shu"},"!","/ev",{"*":".^.c-3","flg":21},"ev","str","^〈鵰〉","/str",{"CNT?":".^.^.u_diao"},"!","/ev",{"*":".^.c-4","flg":21},"ev","str","^〈傳〉","/str",{"CNT?":".^.^.u_chuan"},"!","/ev",{"*":".^.c-5","flg":21},{"c-0":["^ ",{"->":".^.^.^.u_ming"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.u_deng"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.u_dong"},"\n",{"#f":5}],"c-3":["^ ",{"->":".^.^.^.u_shu"},"\n",{"#f":5}],"c-4":["^ ",{"->":".^.^.^.u_diao"},"\n",{"#f":5}],"c-5":["^ ",{"->":".^.^.^.u_chuan"},"\n",{"#f":5}]}],{"u_ming":[["ev",{"VAR?":"nian"},1,"+",{"VAR=":"nian","re":true},"/ev","#","^bg:山道_雨後","/#","#","^fx:dust","/#","^那年他在漢水邊上，替一個村子趕走了一夥搶糧的兵。","\n","^事情辦完他就要走。村口有個老人追上來，跪下去磕頭，磕得額頭碰在泥地上。","\n","^老人：多謝神鵰大俠！","\n","#","^clear","/#","^楊過停住了。","\n","^他從來沒有告訴過任何人自己的名字。這個稱呼是別人替他取的——因為他身邊有一隻很大的、不會飛的鵰。","\n","ev","str","^「我不是什麼大俠。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^〔沒有應，轉身就走〕","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「起來吧。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.^.m_bu"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.^.m_zou"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.^.m_qi"},"\n",{"#f":5}]}],{"#f":1}],"m_bu":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：我不是什麼大俠。","\n","^老人抬起頭看他，一臉茫然。","\n","^楊過：我就是路過。","\n","^老人：那……那也謝謝路過的大俠。","\n","^楊過忽然不知道要說什麼了。","\n","^他走了幾十步，回頭看了一眼。那個老人還跪在那裡。","\n",{"->":".^.^"},null],"m_zou":["ev",{"VAR?":"ming"},1,"+",{"VAR=":"ming","re":true},"/ev","^他沒有應。","\n","^他這輩子被叫過很多稱呼：小賊、孽障、西毒的乾兒子。這是第一個好聽的。","\n","^正因為好聽，他更不敢應。","\n","^他覺得自己配不上。","\n",{"->":".^.^"},null],"m_qi":["ev",{"VAR?":"ming"},1,"+",{"VAR=":"ming","re":true},"/ev","ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^楊過：起來吧。地上涼。","\n","^他伸手把老人扶起來——用一隻手，扶得有點笨。","\n","^那老人握著他的手不放，一直說謝謝。","\n","^楊過站在那裡讓他握著。","\n","^他忽然想起很多年前，有一個人也是這樣蹲下來，讓自己的眼睛跟他一樣高。","\n",{"->":".^.^"},null],"u_deng":[["ev",{"VAR?":"nian"},1,"+",{"VAR=":"nian","re":true},"/ev","#","^bg:客棧_夜","/#","#","^fx:none","/#","^那年冬天他在一戶人家借宿。","\n","^那家人姓什麼他沒問。他們給他一碗熱湯，一張草蓆，還有一盞留在門邊的油燈。","\n","^半夜他醒過來，發現那盞燈還亮著。","\n","^他起身去吹，被人攔住了。","\n","#","^clear","/#","^那是家裡的小女兒，六七歲，抱著膝蓋坐在門檻上。","\n","^女孩：不要吹。","\n","^楊過：為什麼。","\n","^女孩：我娘說，家裡有客人的時候，燈要留一夜。","\n","^楊過：為什麼。","\n","^女孩：這樣客人半夜醒來，就知道自己不是在外頭。","\n","#","^clear","/#","^楊過在門檻上坐下來，跟那個女孩一起看著那盞燈。","\n","^看了很久。","\n","ev","str","^「你們家的規矩很好。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^問她長大要做什麼","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔什麼也沒說，一直坐到天亮〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.^.d_hao"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.^.d_wen"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.^.d_zuo"},"\n",{"#f":5}]}],{"#f":1}],"d_hao":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：你們家的規矩很好。","\n","^女孩：本來就有的啊。","\n","^楊過：……嗯。本來就有的。","\n","^他這輩子住過破廟、住過古墓、住過荒山野嶺。","\n","^沒有人替他留過燈。","\n",{"->":".^.^"},null],"d_wen":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你長大要做什麼。","\n","^女孩：我要跟我娘一樣。","\n","^楊過：跟你娘一樣做什麼。","\n","^女孩：留燈啊。","\n","^楊過笑了。","\n","^他發現這是他這三年來第一次真的笑。","\n",{"->":".^.^"},null],"d_zuo":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他什麼也沒說。","\n","^那個女孩坐了一會就睡著了，頭靠在門框上。楊過把自己的外衣脫下來蓋在她身上。","\n","^他一個人看著那盞燈，看到天亮。","\n","^天亮的時候燈自己滅了。","\n","^他忽然很想哭，但他不知道為什麼。","\n",{"->":".^.^"},null],"u_dong":[["ev",{"VAR?":"nian"},1,"+",{"VAR=":"nian","re":true},"/ev","#","^bg:雪原_夜行","/#","#","^fx:snow","/#","^那一年他沒有跟人說過話。","\n","^不是刻意的，是沒有必要。他走的都是沒有人的地方，遇到的都是不需要交談的事。","\n","#","^clear","/#","^年底他在一座荒山裡過冬。有天早上他咳了一聲。","\n","^被自己的聲音嚇到。","\n","#","^clear","/#","^他坐在雪地裡愣了很久，然後試著出聲說一句話。","\n","ev","str","^「今天很冷。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^叫那隻鵰","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^叫她的名字","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.^.g_leng"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.^.g_diao"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.^.g_ming"},"\n",{"#f":5}]}],{"#f":1}],"g_leng":["^楊過：今天……很冷。","\n","^聲音是啞的，難聽得很。","\n","^他清了清嗓子，又說了一次。","\n","^第二次好一點。第三次就正常了。","\n","^他一個人在雪地裡練了半個時辰的說話。練完他覺得自己有點可笑，然後就笑了。","\n","^笑聲也很啞。","\n",{"->":".^.^"},null],"g_diao":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：喂。","\n","^那隻鵰從石頭後面轉過來看他。","\n","^楊過：沒事。我就是……試試看。","\n","^那鵰歪著頭。","\n","^楊過：你也不會說話。所以你不會懂。","\n","^楊過：算了。","\n","^他站起來拍掉身上的雪。走了幾步他又回頭：","\n","^楊過：謝了。","\n","^那隻鵰不知道他在謝什麼。楊過自己也不太知道。","\n",{"->":".^.^"},null],"g_ming":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^他張開嘴，叫了一聲她的名字。","\n","^叫完他就後悔了。","\n","^那兩個字在空曠的雪地上散得很快，快到聽起來像是沒有人叫過。","\n","^他一個人站在那裡，站到腿麻。","\n","#","^clear","/#","^〔那一年他學會一件事：有些話說出來，比不說更空。〕","\n",{"->":".^.^"},null],"u_shu":[["ev",{"VAR?":"nian"},1,"+",{"VAR=":"nian","re":true},"/ev","#","^bg:斷腸崖_日落","/#","#","^fx:dust","/#","ev",{"VAR?":"miao"},1,"+",{"VAR=":"miao","re":true},"/ev","^那年他照例回斷腸崖描字。","\n","^他每年來一次。用刀尖沿著那兩行淺淺的刻痕描一遍，描完坐一會就走。","\n","#","^clear","/#","^那天他描完之後，坐下來算日子。","\n","^算著算著他發現不對。","\n","#","^clear","/#","^他把手指頭掰完又重新掰了一遍。","\n","^問題出在谷底那一年——他在谷底找了整整一年，那一年他沒有數，因為那一年他還不相信這件事需要數。","\n","^所以不是還剩八年。","\n","^是還剩九年。","\n","ev","str","^把數字改過來","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^不改，就當是八年","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^不再數了","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.^.s_gai"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.^.s_bu"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.^.s_ting"},"\n",{"#f":5}]}],{"#f":1}],"s_gai":["ev",{"VAR?":"miao"},1,"+",{"VAR=":"miao","re":true},"/ev","^他把數字改過來了。","\n","^改的時候手很穩。","\n","^多一年就多一年。他這輩子最不缺的就是時間。","\n","#","^clear","/#","^〔他當時是這樣想的。〕","\n","^〔後來他才知道，那一年他其實不太好過。〕","\n",{"->":".^.^"},null],"s_bu":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他不改。","\n","^他跟自己說：算多算少有什麼差別，反正她會來。","\n","^這個想法很好，好到他用了三年。","\n","^第三年年底他忽然發現自己在騙自己，於是他還是把數字改了。","\n","^改的時候他的手在抖。","\n",{"->":".^.^"},null],"s_ting":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他不數了。","\n","^從那年起他不再算還剩幾年。他只記得一件事：每年這個時候要回來描一次字。","\n","#","^clear","/#","^不數之後日子反而好過了。","\n","^他有時候會想：如果早幾年就不數，是不是這十六年會短一點。","\n","^然後他又想：不會。一天就是一天。誰數都一樣。","\n",{"->":".^.^"},null],"u_diao":[["ev",{"VAR?":"nian"},1,"+",{"VAR=":"nian","re":true},"/ev","#","^bg:山道_雨後","/#","#","^fx:dust","/#","^那隻鵰老了。","\n","^它走路開始慢，慢到楊過得停下來等。它抓魚的次數也少了——以前一天三條，後來兩天一條，再後來牠不抓了，只在他吃東西的時候在旁邊看著。","\n","#","^clear","/#","^有天早上牠沒有起來。","\n","^楊過蹲在牠旁邊看了很久，然後伸手摸了摸牠的背。","\n","^牠睜開眼睛看他一眼，又閉上了。","\n","#","^clear","/#","^那天他哪裡也沒去。","\n","ev","str","^跟牠說話","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^替牠找吃的","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^就坐在旁邊","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.^.e_shuo"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.^.e_zhao"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.^.e_zuo"},"\n",{"#f":5}]}],{"#f":1}],"e_shuo":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：你不要死。","\n","^他說完自己都覺得這句話很沒有道理。","\n","^楊過：你活了那麼久了，多活幾年也不差。","\n","^楊過：……你要是走了，就沒有人跟我一起等了。","\n","^那隻鵰沒有反應。","\n","#","^clear","/#","^牠第二天早上又能走了。","\n","^楊過假裝那天什麼也沒發生過。但從那以後，他走得比以前慢。","\n",{"->":".^.^"},null],"e_zhao":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^他下水抓了三條魚。","\n","^用一隻手抓魚很難。他花了一整個下午，弄得渾身濕透。","\n","^抓回來的時候那隻鵰已經自己站起來了，正在啄一隻死掉的野兔。","\n","^楊過站在原地，手裡拎著三條魚。","\n","^楊過：……你行啊。","\n","^那鵰看了他一眼，繼續啄。","\n",{"->":".^.^"},null],"e_zuo":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他什麼也沒做，就坐在旁邊。","\n","^坐了一整天。","\n","^他忽然想起一件事：這隻鵰在遇到他之前就已經活了很久了。牠可能見過那個刻碑的人。","\n","^他從來沒有想過這一點——他一直以為這隻鵰是屬於他的。","\n","#","^clear","/#","^〔那年他四十歲。〕","\n","^〔他第一次想到：有東西會比他先走。〕","\n",{"->":".^.^"},null],"u_chuan":[["ev",{"VAR?":"nian"},1,"+",{"VAR=":"nian","re":true},"/ev","#","^bg:客棧_夜","/#","#","^fx:none","/#","^那年他在一家客棧裡聽見有人講神鵰俠。","\n","#","^clear","/#","^講的人說得很起勁。他說神鵰大俠一劍劈開三丈厚的城牆，救出八百口人；說他身邊那隻神鵰通人性，能聽懂人話；說他一隻手是被天雷劈掉的，因為他年輕時得罪過神仙。","\n","^滿座的人聽得入神。","\n","#","^clear","/#","^楊過坐在角落裡，把整個故事聽完了。","\n","^故事講得很好。比真的好。","\n","#","^clear","/#","^他左邊的袖子是空的——這是全天下最好認的特徵。","\n","^但那些人講得太投入了，沒有人往旁邊看。","\n","ev","str","^走過去糾正他","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^替那個說書的付了酒錢","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^聽完就走","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.^.c_zheng"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.^.c_fu"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.^.c_zou"},"\n",{"#f":5}]}],{"#f":1}],"c_zheng":["ev",{"VAR?":"xiaming"},1,"-",{"VAR=":"xiaming","re":true},"/ev","^他走過去，說：不是天雷。","\n","^說書的抬頭：「那是什麼？」","\n","^楊過：是一把劍。","\n","^說書的：誰的劍？","\n","^楊過：……一個小姑娘的。","\n","^滿座哄堂大笑。","\n","^有人說這位客官編得比說書的還離譜。","\n","^楊過也笑了。他發現真話說出來反而沒有人信——這件事居然讓他鬆了一口氣。","\n",{"->":".^.^"},null],"c_fu":["ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^他把酒錢付了，什麼也沒說就走了。","\n","^那個說書的追出來要謝他。","\n","^說書的：這位大爺貴姓？","\n","^楊過：不貴。","\n","^說書的：那……小的替您編一段？","\n","^楊過：不用了。","\n","^楊過：你們講的那個人，比我好。留著他吧。","\n",{"->":".^.^"},null],"c_zou":["ev",{"VAR?":"ming"},1,"+",{"VAR=":"ming","re":true},"/ev","^他聽完就走了。","\n","^出了門外頭在下雪。他站在屋簷下聽裡面的笑聲，聽了一會。","\n","#","^clear","/#","^〔他忽然明白一件事：〕","\n","^〔那個叫神鵰俠的人，跟他已經不是同一個人了。〕","\n","^〔而那個人比他過得好。〕","\n",{"->":".^.^"},null]}],"shi_liu_nian":["#","^bg:斷腸崖_日落","/#","#","^fx:dust","/#","#","^clear","/#","^十六年。","\n","^他每年回斷腸崖描一次字。描到後來，那兩行字已經分不清哪一筆是她刻的、哪一筆是他描的。","\n",["ev",{"VAR?":"miao"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^有一年他描完之後忽然停住——他發現自己已經記不得她原本的筆跡了。","\n","^他坐在崖邊想了一夜，第二年就不描了。","\n","^不描之後那兩行字開始風化。他每年來看它淺一點。","\n","^他覺得這樣也好。","\n",{"->":".^.^.^.15"},null]}],[{"->":".^.b"},{"b":["\n","^他一直描到最後一年。","\n",{"->":".^.^.^.15"},null]}],"nop","\n","#","^clear","/#",["ev",{"VAR?":"ming"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^這十六年裡，江湖上的神鵰俠越來越有名。","\n","^有名到楊過偶爾會忘記那個人是自己。","\n","^這件事他不太在意。有一個比他好的人替他活在別人嘴裡，也不錯。","\n",{"->":".^.^.^.22"},null]}],[{"->":".^.b"},{"b":["\n","^這十六年裡，他做了很多事，也沒有留下名字。","\n","^有些村子記得有個一隻手的人來過。多數地方連這個都沒記住。","\n",{"->":".^.^.^.22"},null]}],"nop","\n","#","^clear","/#","^〔那年他四十五歲。〕","\n","^〔約定的日子還剩三個月。〕","\n","^〔第十三回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",21,{"VAR=":"qingyi"},10,{"VAR=":"xiaming"},0,{"VAR=":"nian"},0,{"VAR=":"ming"},0,{"VAR=":"miao"},"/ev","end",null]}],"listDefs":{}},"ch14":{"inkVersion":21,"root":[[{"->":"ke_zhan"},["done",{"#n":"g-0"}],null],"done",{"ke_zhan":[["#","^bg:風陵渡_雪夜","/#","#","^fx:snow","/#","^〔視角：郭襄〕","\n","^風陵渡口的雪下了三天，船停了三天，客棧裡塞滿了走不了的人。","\n","^郭襄十六歲，一個人，騎一頭青驢，從襄陽跑出來已經兩個月。","\n","^她爹娘大概快急死了。她想到這裡有點抱歉，但也就一點點。","\n","#","^clear","/#","^客棧裡人擠人，火盆燒得很旺。她窩在角落的桌子邊上烤手，聽旁邊那一桌講故事。","\n","^講的是神鵰大俠。","\n","#","^clear","/#","^那一桌講得很熱鬧。有人說他一劍劈開三丈城牆，有人說他的鵰能聽懂人話，有人說他一隻手是被天雷劈的。","\n","^郭襄聽得眼睛發亮。","\n","ev","str","^插嘴問","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^搬凳子坐過去","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^假裝沒在聽，其實一個字都沒漏","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ch_wen"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.ch_zuo"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.ch_zhuang"},"\n",{"#f":5}]}],{"ch_wen":["ev",{"VAR?":"xiang"},1,"+",{"VAR=":"xiang","re":true},"/ev","^郭襄：那他長什麼樣子？","\n","^滿桌的人都轉過來看她。","\n","^漢子甲：小姑娘家家的，問這個做什麼。","\n","^郭襄：我問問不行嗎。","\n","^漢子甲：……也是。","\n","^那人想了半天。","\n","^漢子甲：其實沒人見過他的臉。他戴面具。","\n","^郭襄：那你們怎麼知道是他？","\n","^漢子甲：一隻手啊。全天下就他一隻手。","\n","^郭襄「喔」了一聲，心裡想：這算什麼答案。","\n",{"->":"ye_li"},null],"ch_zuo":["ev",{"VAR?":"xiang"},2,"+","/ev",{"VAR=":"xiang","re":true},"^她乾脆搬了凳子坐過去。","\n","^滿桌的人愣了一下，然後就接受了——這姑娘臉皮厚得理直氣壯，很難不接受。","\n","^她一連問了十幾個問題，問到那幾個漢子答不出來為止。","\n","^漢子乙：我說姑娘，你怎麼比我們還熱心。","\n","^郭襄：因為你們講的都不對啊。","\n","^漢子乙：你怎麼知道不對？","\n","^郭襄：一個人要是那麼厲害，為什麼不留名字？","\n","#","^clear","/#","^滿桌安靜了一下。","\n","^沒有人答得出來。","\n",{"->":"ye_li"},null],"ch_zhuang":["^她假裝在烤手，一個字都沒漏。","\n","^她從小聽爹娘講江湖，聽得多了就知道：故事裡越是離奇的部分越假，越是不起眼的細節越可能是真的。","\n","^那些人講的細節裡，只有一個她覺得是真的——","\n","^有人說他每年冬天都會往南邊去一趟，去哪裡沒有人知道，去做什麼也沒有人知道。","\n","^她把這一條記下來了。","\n",{"->":"ye_li"},null]}],"ye_li":[["#","^bg:雪原_夜行","/#","#","^fx:snow","/#","#","^clear","/#","^半夜裡她睡不著，披了衣服出去看雪。","\n","^渡口的冰面上有月光。她站在河邊，忽然聽見上游有動靜。","\n","#","^clear","/#","^一群人正在冰面上圍打一個人。","\n","^那個人很高，穿深色的衣服，一隻袖子是空的。","\n","^郭襄的心跳了一下。","\n","#","^clear","/#","ev","str","^衝上去幫忙","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先在暗處看清楚","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^大喊一聲驚動他們","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"ye_li.y_chong"},"\n",{"#f":5}],"c-1":["^ ",{"->":"ye_li.y_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":"ye_li.y_han"},"\n",{"#f":5}]}],{"y_chong":["ev",{"VAR?":"xiang"},1,"+",{"VAR=":"xiang","re":true},"/ev","^她抄起一根柴就衝下去了。","\n","^她武功不高——她爹娘沒有正經教過她，她會的都是偷學的。但她跑得快，膽子大，而且她從小就沒有怕過人多。","\n","^她衝到一半才想起自己手上拿的是柴。","\n","#","^clear","/#","^那個人只用了三招就把七個人放倒了。","\n","^放倒之後他回頭看了她一眼。","\n","^面具底下看不見表情。但郭襄覺得那一眼裡有一點點……好笑。","\n",{"->":"jin_zhen"},null],"y_kan":["ev",{"VAR?":"xiang"},2,"+","/ev",{"VAR=":"xiang","re":true},"^她躲在岸邊的柳樹後面看。","\n","^看了三招她就明白了：那七個人根本傷不到他。","\n","^她看的不是他怎麼打，是他怎麼站。","\n","#","^clear","/#","^他一直站在同一個位置上，不進不退。","\n","^後來她才發現為什麼——他背後是一戶亮著燈的人家。","\n","^他不是在打架。他是在擋。","\n",{"->":"jin_zhen"},null],"y_han":["ev",{"VAR?":"xiang"},1,"+",{"VAR=":"xiang","re":true},"/ev","^她扯開嗓子喊了一聲：「官兵來啦——！」","\n","^冰面上七個人同時愣住。","\n","^那個一隻袖子的人趁機把他們全放倒了。","\n","^放倒之後他抬頭往岸上看。","\n","^郭襄從柳樹後面探出頭，衝他笑了一下。","\n",{"->":"jin_zhen"},null]}],"jin_zhen":[["#","^clear","/#","^他走上岸，在她面前站住。","\n","^近看更高。面具是很粗糙的皮做的，看得出是自己隨手弄的，不講究。","\n","^他開口的時候聲音有點啞，像是很久沒有跟人說過話。","\n","^神鵰俠：你剛才要做什麼。","\n","ev","str","^「我要幫你啊。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我要看熱鬧。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「我不知道。我就是衝下來了。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.z_bang"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.z_nao"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.z_bu"},"\n",{"#f":5}]}],{"z_bang":["^郭襄：我要幫你啊。","\n","^神鵰俠：拿一根柴。","\n","^郭襄：柴怎麼了。柴很硬。","\n","^神鵰俠：……","\n","^他沉默了一下。","\n","^郭襄覺得他在笑。她不確定，因為面具擋住了。","\n",{"->":"zhen_gei"},null],"z_nao":["^郭襄：我要看熱鬧。","\n","^神鵰俠：那你為什麼衝下來。","\n","^郭襄：看熱鬧要近一點才好看。","\n","^這次她確定他在笑了——因為他的肩膀動了一下。","\n",{"->":"zhen_gei"},null],"z_bu":["ev",{"VAR?":"xiang"},1,"+",{"VAR=":"xiang","re":true},"/ev","^郭襄：我不知道。我就是衝下來了。","\n","^他看著她。","\n","^神鵰俠：以後不要這樣。","\n","^郭襄：為什麼。","\n","^神鵰俠：會死。","\n","^郭襄：那你為什麼這樣。","\n","^神鵰俠：……","\n","^他沒有答。","\n",{"->":"zhen_gei"},null]}],"zhen_gei":[["#","^clear","/#","^他從懷裡拿出三樣東西。","\n","^三枚金針，小小的，很細，在月光下閃著一點光。","\n","^神鵰俠：拿去。","\n","^郭襄：這是什麼。","\n","^神鵰俠：三件事。","\n","#","^clear","/#","^神鵰俠：你拿著這三枚針，可以要我做三件事。","\n","^神鵰俠：什麼事都行。我一定做到。","\n","#","^clear","/#","^郭襄捏著那三枚針，抬頭看他。","\n","^郭襄：為什麼給我。","\n","^神鵰俠：……","\n","^他想了很久。","\n","^神鵰俠：你剛才拿著一根柴衝下來。","\n","^神鵰俠：這種事我很多年沒有看見過了。","\n","#","^clear","/#","ev","str","^「那我現在就用一枚。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「我先收著。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「你把面具拿下來給我看。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.use_now"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.keep"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.mask"},"\n",{"#f":5}]}],{"use_now":["ev",{"VAR?":"zhen"},1,"+",{"VAR=":"zhen","re":true},"/ev","ev",{"VAR?":"xiang"},1,"+",{"VAR=":"xiang","re":true},"/ev","^郭襄：那我現在就用一枚。","\n","^她把一枚針遞回去。","\n","#","^emo:郭襄_笑","/#","^郭襄：我要你陪我看完這場雪。","\n","#","^clear","/#","^他沒有動。","\n","^過了很久，他在她旁邊的石頭上坐下了。","\n","^兩個人一起看著河面上的雪，誰也沒有說話。","\n","#","^clear","/#","^那一夜郭襄十六歲。","\n","^很多年以後她還記得那場雪，記得那個人坐下來的樣子——他坐下來之前遲疑了一下，像是很久沒有跟人一起坐過。","\n",{"->":"ch14_close"},null],"keep":["^郭襄：我先收著。","\n","^神鵰俠：好。","\n","^郭襄：那你要記得。","\n","^神鵰俠：我記得。","\n","^她把三枚針包好，塞進最裡層的口袋。","\n","^包了三層。","\n",{"->":"ch14_close"},null],"mask":["ev",{"VAR?":"xiang"},2,"+","/ev",{"VAR=":"xiang","re":true},"^郭襄：我要你把面具拿下來給我看。","\n","^他的身體僵了一下。","\n","^神鵰俠：這算一件事。","\n","^郭襄：算就算。","\n","#","^clear","/#","^他抬手，把面具摘了下來。","\n","#","^clear","/#","^郭襄看見的是一張很普通的臉。四十多歲，風吹日曬過的，眼角有紋。不好看，也不難看。","\n","^只有一個地方不普通——","\n","^那雙眼睛看人的時候，是穿過去的。像是在看眼前這個人的背後很遠的地方。","\n","#","^clear","/#","^郭襄：你在看什麼。","\n","^神鵰俠：沒有。","\n","^郭襄：你剛才明明在看什麼。","\n","^神鵰俠：……","\n","^他把面具戴回去了。","\n","ev",{"VAR?":"zhen"},1,"+",{"VAR=":"zhen","re":true},"/ev",{"->":"ch14_close"},null]}],"ch14_close":["#","^bg:風陵渡_雪夜","/#","#","^clear","/#","^天快亮的時候他要走了。","\n","^郭襄追了兩步：「喂——」","\n","^他停住。","\n","^郭襄：你叫什麼名字。","\n","#","^clear","/#",["ev",{"VAR?":"xiang"},3,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他站著沒動，站了很久。","\n","^久到郭襄以為他不打算回答。","\n","^神鵰俠：……你以後會知道。","\n","^郭襄：什麼時候。","\n","#","^emo:楊過_斷臂","/#","^神鵰俠：等你聽見有人講一件很難聽的事，而那件事是真的。","\n","^他說完就走了。","\n","^郭襄站在渡口，把這句話想了三年才想明白。","\n",{"->":".^.^.^.19"},null]}],[{"->":".^.b"},{"b":["\n","^神鵰俠：不重要。","\n","^他說完就走了。","\n","^郭襄在後面喊：「怎麼會不重要！」","\n","^沒有人回答她。","\n",{"->":".^.^.^.19"},null]}],"nop","\n","#","^clear","/#","^〔視角回到楊過〕","\n","#","^clear","/#","^他往南走。","\n","^走出十里之後他停下來，回頭看了一眼。","\n","^那個小姑娘還站在渡口，沒有進去。","\n","#","^clear","/#","^他忽然想起很多年前，也有一個人站在渡口，看著一條船走遠。","\n","^那時候他也沒有回頭。","\n","#","^clear","/#","^〔約定的日子還剩兩個月。〕","\n","^〔第十四回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",22,{"VAR=":"qingyi"},13,{"VAR=":"xiaming"},0,{"VAR=":"xiang"},0,{"VAR=":"zhen"},"/ev","end",null]}],"listDefs":{}},"ch15":{"inkVersion":21,"root":[[{"->":"na_yi_tian"},["done",{"#n":"g-0"}],null],"done",{"na_yi_tian":["#","^bg:斷腸崖_日落","/#","#","^fx:dust","/#","^他提早三個月到。","\n","^三個月裡他把崖上崖下走遍了。他清掉了崖邊的雜草，把那塊刻字的石壁擦乾淨，甚至還在旁邊搭了一個很簡陋的棚子——","\n","^搭到一半他停下來，覺得自己這樣很傻。","\n","^然後他把棚子搭完了。","\n","#","^clear","/#","^約定那天他天沒亮就上去了。","\n","#","^clear","/#",{"->":"deng_1"},null],"deng_1":["#","^clear","/#","^天亮了。","\n","^崖上有霧。他站在那兩行字前面，聽著崖下雲海翻動的聲音。","\n","^沒有人來。","\n",{"->":"deng_2"},null],"deng_2":["#","^clear","/#","^日頭上來了。","\n","^霧散了。雲海一層一層往下沉，露出對面的山。","\n","^他坐下來。","\n","^沒有人來。","\n",{"->":"deng_3"},null],"deng_3":["#","^clear","/#","^正午。","\n","^他把水袋裡的水喝完了。他想起自己從昨天到現在什麼也沒吃。","\n","^他不覺得餓。","\n","^沒有人來。","\n",{"->":"deng_4"},null],"deng_4":["#","^clear","/#","^下午。","\n","^那隻鵰在他旁邊臥著，一整天沒有動。","\n","^他伸手摸了摸牠的背。","\n","^沒有人來。","\n",{"->":"deng_5"},null],"deng_5":["#","^clear","/#","^太陽開始往下走。","\n","^雲海被染成橙金與桃紅。那是這座崖一年裡最好看的一個時辰——十六年來他看過十六次。","\n","^十六次他都是一個人看的。","\n","#","^clear","/#","^他站起來，走到崖邊。","\n","^沒有人來。","\n",{"->":"deng_6"},null],"deng_6":["#","^clear","/#","^天黑了。","\n","#","^clear","/#","^他在崖邊站著。站了很久，久到腿麻了又不麻了。","\n","^崖下面是霧。十六年來他往下看過很多次，每一次都看不見底。","\n","#","^clear","/#","^〔她沒有來。〕","\n",{"->":"jue_ding"},null],"jue_ding":[["#","^clear","/#","ev","str","^再等一夜","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^跳下去","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^先問那隻鵰","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.j_deng"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.j_tiao"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.j_diao"},"\n",{"#f":5}]}],{"j_deng":["ev",{"VAR?":"deng"},1,"+",{"VAR=":"deng","re":true},"/ev","^他又等了一夜。","\n","^第二天早上還是沒有人。","\n","^他又等了一天。第三天，第四天。","\n","#","^clear","/#","^第七天他站起來的時候，發現自己已經不太能站穩了。","\n","^那隻鵰擋在他前面，用喙推他，推他往崖下的方向。","\n","^他愣了一下。","\n","^楊過：你也知道啊。","\n",{"->":"tiao_xia"},null],"j_tiao":["ev",0,"/ev",{"VAR=":"deng","re":true},"^他沒有猶豫。","\n","^他站在崖邊，最後看了那兩行字一眼。","\n","#","^clear","/#","^十六年來他讀的都是「十六年後」。","\n","^現在他終於讀懂了另一件事——","\n","#","^clear","/#","^〔一個要走十六年的人，不會挑一塊崖來寫字。〕","\n","^〔她不是要他等。〕","\n","^〔她是要他活。〕","\n","#","^clear","/#","^楊過（很輕）：龍兒，我來找你了。","\n",{"->":"tiao_xia"},null],"j_diao":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他轉頭問那隻鵰。","\n","^楊過：你說她會不會在下面。","\n","^那鵰沒有反應。","\n","^楊過：你要是覺得會，你就叫一聲。","\n","#","^clear","/#","^過了很久，那隻鵰叫了一聲。","\n","^叫得很難聽，像破鑼。","\n","^楊過笑了。他知道那隻鵰根本不懂他在問什麼。","\n","^但他還是笑了。","\n",{"->":"tiao_xia"},null]}],"tiao_xia":["ev",true,"/ev",{"VAR=":"tiao","re":true},"#","^clear","/#","^他跳下去了。","\n","#","^clear","/#","^落下去的時間比他想的長。","\n","^長到他有時間把很多事情想完一遍。","\n","#","^clear","/#",["ev",{"VAR?":"qingyi"},24,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他想的是那三尺。","\n","^石堂裡兩個蒲團之間那三尺，對練時她站的那三尺，大勝關她走過來停住的那三尺。","\n","^十六年了，他一直沒能把那三尺走完。","\n",{"->":".^.^.^.22"},null]}],["ev",{"VAR?":"qingyi"},18,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他想的是那兩行字。","\n","^刻得很淺，刻的人手上沒有力氣。他每年來描一次，描了十六年。","\n","^他從來沒有想過：為什麼那個人沒有力氣。","\n",{"->":".^.^.^.22"},null]}],[{"->":".^.b"},{"b":["\n","^他什麼也沒想。","\n","^他只是覺得，這件事總算有一個結束的方式了。","\n",{"->":".^.^.^.22"},null]}],"nop","\n","#","^clear","/#","^然後是水。","\n",{"->":"gu_di"},null],"gu_di":[["#","^bg:絕情谷底_花海","/#","#","^fx:dust","/#","#","^clear","/#","^谷底有光。","\n","^不是天光。是一整片開著小花的藤蔓，從崖壁一直鋪到地上，在暗處微微地亮。","\n","^那種花他認得。十六年前他碰過一次。","\n","^現在滿谷都是。","\n","#","^clear","/#","^他從水裡爬上來，趴在石頭上吐了很久。","\n","^吐完他抬起頭。","\n","#","^clear","/#","^前面有一間屋子。","\n","#","^clear","/#","^屋子很小，石頭砌的，屋頂鋪著藤蔓。屋前有一塊菜地，菜種得不太好——溝挖得歪歪扭扭，看得出來種的人不熟。","\n","^門開著。","\n","#","^clear","/#","^他站起來。走過去。走得很慢，慢到他自己都覺得不對勁。","\n","^他在門口停住。","\n","#","^clear","/#","^裡面有一個人。","\n","^穿白衣服。正低著頭在做一件事。","\n","#","^clear","/#","^她抬起頭。","\n","#","^clear","/#","ev","str","^叫她的名字","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^〔什麼也說不出來〕","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「我來晚了。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"gu_di.j_ming"},"\n",{"#f":5}],"c-1":["^ ",{"->":"gu_di.j_mo"},"\n",{"#f":5}],"c-2":["^ ",{"->":"gu_di.j_wan"},"\n",{"#f":5}]}],{"j_ming":["ev",{"VAR?":"qingyi"},2,"+","/ev",{"VAR=":"qingyi","re":true},"^楊過：龍兒。","\n","#","^clear","/#","^她站起來，走到他面前。","\n","^三尺。","\n","#","^clear","/#","^然後她又走了三尺。","\n","#","^clear","/#","^十六年來他一直沒能走完的那三尺，她走完了。","\n",{"->":"ch15_close"},null],"j_mo":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他什麼也說不出來。","\n","^不是想不出話。是他不敢出聲——","\n","^這十六年他做過很多次這個夢。每一次只要他一開口，夢就醒了。","\n","#","^clear","/#","^所以他站在門口，一動也不動。","\n","^站到她放下手裡的東西。站到她走過來。站到她伸出手，很輕地按在他的手背上。","\n","#","^clear","/#","^那隻手還是涼的。","\n","#","^clear","/#","^十六年了，她的手還是涼的。","\n","^他這才敢哭。","\n",{"->":"ch15_close"},null],"j_wan":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：我來晚了。","\n","^小龍女：沒有。","\n","^她說得很平，像在說一件跟天氣一樣的事。","\n","#","^emo:小龍女_睜","/#","^小龍女：你剛好。","\n","#","^clear","/#","^他就在門口蹲下去了。","\n","^蹲下去之後他才發現自己在抖——不是哭，是整個人在抖，抖得停不下來。","\n","^她也蹲下來，等他抖完。","\n","^她等了很久。她很會等。","\n",{"->":"ch15_close"},null]}],"ch15_close":["#","^clear","/#","^後來的事他們誰也沒有仔細講過。","\n","^她在谷底住了十六年。她是怎麼活下來的、怎麼從那潭水裡爬出來的、頭幾年怎麼過的——這些事楊過問過幾次，她答得都很簡單。","\n","^小龍女：就是活著。","\n","#","^clear","/#","^他也問過那兩行字。","\n","^楊過：你為什麼要寫十六年。","\n","^小龍女：因為十六年很長。","\n","^楊過：所以呢。","\n","^小龍女：長到你會忘記。","\n","#","^clear","/#","^楊過看著她。","\n","^楊過：我沒有忘記。","\n","^小龍女：我知道。","\n","^她說完低下頭去，繼續整理手裡那把不知道整理了多久的草藥。","\n","#","^clear","/#","^〔她賭輸了。〕","\n","^〔她這輩子只賭過這一次，而她很高興自己賭輸了。〕","\n","#","^clear","/#","^那年他四十五歲，她也不年輕了。","\n","^谷底沒有日曆。他們在那裡住了幾個月，種菜，養蜂，很少說話。","\n","^有一天早上他忽然說：","\n","^楊過：襄陽在打仗。","\n","^她抬起頭看他。","\n","^小龍女：那我們去。","\n","^〔第十五回終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",24,{"VAR=":"qingyi"},14,{"VAR=":"xiaming"},0,{"VAR=":"deng"},false,{"VAR=":"tiao"},"/ev","end",null]}],"listDefs":{}},"ch16":{"inkVersion":21,"root":[[{"->":"gui_lai"},["done",{"#n":"g-0"}],null],"done",{"gui_lai":[["#","^bg:襄陽城牆_戰時","/#","#","^fx:none","/#","^襄陽已經圍了很久。","\n","^他們到的時候，城牆上的人已經換過三批。糧食按人頭配，箭矢用完就撿敵人的。城裡沒有人哭——哭過的都哭完了。","\n","#","^clear","/#","^守城的人認出了小龍女身邊那個一隻手的人。","\n","^先是一個，然後十個，然後整段城牆都在傳。","\n","^有人喊了一聲「神鵰大俠」，喊完自己都愣住——那個活在故事裡十六年的人，居然真的站在這裡。","\n","ev","str","^應了","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^沒有應","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^「我姓楊。」","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.ying"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.bu_ying"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.xing_yang"},"\n",{"#f":5}]}],{"ying":["ev",{"VAR?":"xiaming"},2,"+","/ev",{"VAR=":"xiaming","re":true},"^楊過：在。","\n","^他應了。","\n","^他這輩子第一次應這個稱呼。","\n","#","^clear","/#","^應完他自己也覺得奇怪——十六年他都沒有應過，怎麼今天就應了。","\n","^後來他想明白了：以前不應，是因為覺得自己配不上。","\n","^現在他不在乎配不配了。城牆上這些人需要有一個人應。","\n",{"->":"jin_lun"},null],"bu_ying":["^他沒有應。","\n","^他只是走上城牆，把那塊黑鐵從背上取下來，往垛口一放。","\n","^黑鐵砸在石頭上，發出很悶的一聲。","\n","^那一聲比什麼回答都有用。","\n",{"->":"jin_lun"},null],"xing_yang":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：我姓楊。","\n","^城牆上安靜了一下。","\n","^有個年輕的兵小聲問旁邊的人：「哪個楊？」","\n","^老兵說：「就是那個楊。」","\n","^年輕人「喔」了一聲，好像懂了，其實根本沒懂。","\n","^十六年前那個姓還是句罵人的話。現在它只是個姓了。","\n",{"->":"jin_lun"},null]}],"jin_lun":["#","^clear","/#","^第三天，城破了一角。","\n","^一個和尚從缺口衝上來，手裡五個輪子，一路把守軍往城下扔。","\n","^那是金輪法王。十六年前他們交過手——那時候楊過打不過。","\n","#","^clear","/#","^現在他兩隻手裡只有一隻，而那一隻拖著一塊沒開鋒的黑鐵。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"j1"},null],"j1":[["^〔第一合〕","\n","ev","str","^玄鐵重劍（真氣 −6）","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^先看他的節奏（真氣 −2）","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^跟小龍女合手（真氣 −5）","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"j1.j1_tie"},"\n",{"#f":5}],"c-1":["^ ",{"->":"j1.j1_kan"},"\n",{"#f":5}],"c-2":["^ ",{"->":"j1.j1_he"},"\n",{"#f":5}]}],{"j1_tie":["ev",{"VAR?":"zhenqi"},6,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"shi"},1,"+",{"VAR=":"shi","re":true},"/ev","^黑鐵下去。","\n","^沒有招式，就是一劈。重、慢、不講道理。","\n","^輪子碎了兩個。","\n","^金輪法王：你這一劍，比十六年前重。","\n","^楊過：嗯。","\n","^金輪法王：你這十六年練了什麼。","\n","^楊過：沒練什麼。我沒有別的事做。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"j2"},null],"j1_kan":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"shi"},1,"+",{"VAR=":"shi","re":true},"/ev","^他不急著出手，先看。","\n","^五個輪子，五個節奏。第三個最慢——那是因為那隻手要換勁。","\n","^十六年前他看不出這個。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"j2"},null],"j1_he":["ev",{"VAR?":"zhenqi"},5,"-","/ev",{"VAR=":"zhenqi","re":true},["ev",{"VAR?":"qingyi"},24,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^兩把兵器同時動。玉女素心劍法——隔了十六年，居然還在。","\n","^他們誰也沒有練過。但十六年沒有磨掉那個東西。","\n","^金輪法王退了三步。","\n",{"->":".^.^.^.8"},null]}],[{"->":".^.b"},{"b":["\n","^他們想合手，但十六年沒有一起出過手。","\n","^差了半息。半息就是差。","\n",{"->":".^.^.^.8"},null]}],"nop","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"j2"},null]}],"j2":[["^〔第二合〕","\n","#","^clear","/#","^打到一半，城下傳來一聲喊。","\n","^金輪法王擄了一個人上城樓——一個十六歲的姑娘，被綁著，還在掙扎。","\n","#","^clear","/#","^〔郭襄。〕","\n","ev","str","^衝上去","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^喊她的名字","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^停手","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":"j2.j2_chong"},"\n",{"#f":5}],"c-1":["^ ",{"->":"j2.j2_han"},"\n",{"#f":5}],"c-2":["^ ",{"->":"j2.j2_ting"},"\n",{"#f":5}]}],{"j2_chong":["ev",{"VAR?":"zhenqi"},4,"-","/ev",{"VAR=":"zhenqi","re":true},"ev",{"VAR?":"jiu_xiang"},1,"+",{"VAR=":"jiu_xiang","re":true},"/ev","^他衝上去。","\n","^衝到一半就知道來不及——城樓太高，中間隔著一整段被火燒著的木架。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"an_ran"},null],"j2_han":["ev",{"VAR?":"jiu_xiang"},2,"+","/ev",{"VAR=":"jiu_xiang","re":true},"^楊過：郭襄！","\n","^那姑娘在火裡回頭。","\n","^她看見了他，然後她笑了——被綁著、在火裡、還在笑。","\n","#","^emo:郭襄_笑","/#","^郭襄：我就知道是你！","\n","#","^clear","/#","^楊過站在原地，忽然覺得心口一緊。","\n","^十六年前有一個人也是這樣，在他快要撐不住的時候，用一句最沒有道理的話把他撐住。","\n",{"->":"an_ran"},null],"j2_ting":["ev",{"VAR?":"zhenqi"},2,"-","/ev",{"VAR=":"zhenqi","re":true},"^他停手了。","\n","^金輪法王：你在乎這丫頭？","\n","^楊過：不在乎。","\n","^金輪法王：那我扔了。","\n","^楊過：……","\n","^他沒有動。但金輪法王看見了他握著劍的那隻手在抖。","\n","^〔真氣 ","ev",{"VAR?":"zhenqi"},"out","/ev","^〕","\n",{"->":"an_ran"},null]}],"an_ran":[["#","^clear","/#","^十六年裡他練過一路掌法。","\n","^那是他一個人在海邊、在雪地裡、在沒有人的荒山上一點一點想出來的。想的時候他不是在想怎麼打人，是在想別的。","\n","^那一路掌法沒有名字。","\n","#","^clear","/#","^自從谷底上來之後，他一次也沒有使出來過。","\n","^他試過幾次，每一次都差一點。他一開始以為是手生了。","\n","^後來他明白了——","\n","#","^clear","/#","^〔那一路掌法要的東西，他已經沒有了。〕","\n","^〔他不再是一個人了。〕","\n","#","^clear","/#","^可是現在城樓上有個十六歲的姑娘在火裡。","\n","#","^clear","/#","^而他忽然又想起了那種感覺：","\n","^〔快要失去一個人，而你來不及。〕","\n","#","^clear","/#","ev",true,"/ev",{"VAR=":"anran","re":true},"^他出手了。","\n","ev","str","^第一掌","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["^ ",{"->":"an_ran.a1"},"\n",{"#f":5}]}],{"a1":[["#","^clear","/#","^第一掌，他想的是石門關上的那一聲。","\n","#","^clear","/#","^第二掌，他想的是石堂裡兩個蒲團之間那三尺。","\n","#","^clear","/#","^第三掌，他想的是斷腸崖上那兩行字，刻的人手上沒有力氣。","\n","#","^clear","/#","^第四掌，他想的是十六年裡他每年回去描一次，描到最後分不清哪一筆是誰的。","\n","#","^clear","/#","^第五掌他什麼也沒有想。","\n","#","^clear","/#","ev",{"VAR?":"shi"},3,"+","/ev",{"VAR=":"shi","re":true},"^金輪法王退了。","\n","^金輪法王：這是什麼功夫。","\n","^楊過：……","\n","^金輪法王：我問你這是什麼功夫。","\n","#","^clear","/#","ev","str","^「沒有名字。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「黯然銷魂掌。」","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["^ ",{"->":"an_ran.nm_wu"},"\n",{"#f":5}],"c-1":["^ ",{"->":"an_ran.nm_you"},"\n",{"#f":5}]}],null],"nm_wu":["^楊過：沒有名字。","\n","^他說的是實話。他從來沒有替它取過名字。","\n","^後來江湖上有人替它取了一個，取得很難聽，但也很準。","\n",{"->":"jl_end"},null],"nm_you":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：黯然銷魂掌。","\n","^他說完自己愣了一下——這個名字他從來沒有說出口過。","\n","^他是剛剛才想到的。","\n",{"->":"jl_end"},null]}],"jl_end":["#","^clear","/#","^〔勝〕","\n","^金輪法王從城樓上掉下去的時候，楊過沒有看。","\n","^他在接那個從火裡掉下來的姑娘。","\n","#","^clear","/#",["ev",{"VAR?":"jiu_xiang"},2,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他用一隻手接住了她。","\n","^郭襄在他懷裡喘了半天，然後說：","\n","^郭襄：我那三枚金針還沒用完呢。","\n","^楊過：……","\n","^郭襄：這次不算。這次是你自己要來的。","\n","^楊過笑了。","\n",{"->":"jl_end.14"},null]}],[{"->":".^.b"},{"b":["\n","^他接住了她。","\n","^姑娘在他懷裡沒有出聲。過了很久她才說：","\n","^郭襄：你來晚了。","\n","^楊過：對不起。","\n","^郭襄：……騙你的。","\n",{"->":"jl_end.14"},null]}],"nop","\n",{"->":"meng_ge"},null],"meng_ge":[["#","^bg:襄陽城牆_戰時","/#","#","^clear","/#","^蒙古人退了半里，重新整隊。","\n","^城下的陣裡有一個人騎在馬上，穿的東西跟別人都不一樣。所有的旗都朝著他。","\n","^那是他們的大汗。","\n","#","^clear","/#","^他離城牆很遠。遠到城上的弓箭夠不著，遠到沒有人想過那是一個可以打得到的距離。","\n","#","^clear","/#","^楊過彎下腰，從腳邊撿了一塊石頭。","\n","#","^clear","/#","ev","str","^扔","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["^ ",{"->":".^.^.^.reng_shi"},"\n",{"#f":5}]}],{"reng_shi":["#","^clear","/#","^石頭出去了。","\n","#","^clear","/#","^飛了很久。","\n","^久到城上城下所有人都停下手，跟著那塊石頭看。","\n","#","^clear","/#","^那個穿得跟別人都不一樣的人，從馬上掉下去了。","\n","#","^clear","/#","^蒙古人退了。","\n","^不是退一里。是退回北方。","\n","^這場打了十幾年的仗，在那塊石頭落地之後，結束了。","\n","#","^clear","/#","^〔全作唯一一次：武力真的改變了世界。〕","\n","^〔而扔石頭的那個人，練這隻手臂練了十六年——〕","\n","^〔練的時候，一次也沒有想過襄陽。〕","\n",{"->":"hua_shan"},null]}],"hua_shan":[["#","^bg:華山之巔_黎明","/#","#","^fx:dust","/#","#","^clear","/#","^那年秋天他們上了華山。","\n","^沒有什麼理由。小龍女說想看看高的地方，他就帶她來了。","\n","#","^clear","/#","^山頂是一片裸露的岩台，四面是斷崖，崖下是雲海。天剛要亮，雲被染成金色與粉色。","\n","^兩個人在岩台邊上坐下來。","\n","#","^clear","/#","ev","str","^「這十六年值了。」","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^「這十六年本來可以不用。」","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^〔什麼也沒說〕","/str","/ev",{"*":".^.c-2","flg":20},{"c-0":["^ ",{"->":".^.^.^.h_zhi"},"\n",{"#f":5}],"c-1":["^ ",{"->":".^.^.^.h_bu"},"\n",{"#f":5}],"c-2":["^ ",{"->":".^.^.^.h_mo"},"\n",{"#f":5}]}],{"h_zhi":["ev",{"VAR?":"xiaming"},1,"+",{"VAR=":"xiaming","re":true},"/ev","^楊過：這十六年值了。","\n","^小龍女：什麼叫值。","\n","^楊過：……就是換得過來。","\n","^小龍女：換什麼。","\n","^楊過：換現在。","\n","^她想了想。","\n","^小龍女：那我不知道。我沒有別的十六年可以比。","\n",{"->":"jie_ju"},null],"h_bu":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^楊過：這十六年本來可以不用的。","\n","^小龍女：嗯。","\n","^楊過：你當初要是不跳……","\n","^小龍女：那你就死了。","\n","^她說得很平常。","\n","#","^emo:小龍女_笑","/#","^小龍女：我算過的。","\n","^楊過：你算過？","\n","^小龍女：我不會算數。但那件事我算得出來。","\n",{"->":"jie_ju"},null],"h_mo":["ev",{"VAR?":"qingyi"},1,"+",{"VAR=":"qingyi","re":true},"/ev","^他什麼也沒說。","\n","^他只是伸手，把她的手握住。","\n","^十六年前他沒敢握。十六年後他握了。","\n","^她也沒有抽開。","\n",{"->":"jie_ju"},null]}],"jie_ju":["#","^clear","/#","^後來的事，江湖上有很多說法。","\n","^有人說神鵰大俠帶著夫人隱居去了。有人說他們回了終南山。有人說在南邊某座島上見過一個一隻手的老人。","\n","^沒有人確定。因為他再也沒有出來過。","\n","#","^clear","/#",["ev",{"VAR?":"xiaming"},18,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他救了襄陽。這件事寫進了書裡。","\n","^書裡的那個人很高大，很完整，做每一件事都有道理。","\n","^真正的那個人不是那樣。真正的那個人偷過雞、認過賊做父、當著幾百個人說過一句讓自己身敗名裂的話。","\n","^但書裡不寫這些。書只寫他扔了一塊石頭。","\n",{"->":"jie_ju.15"},null]}],["ev",{"VAR?":"xiaming"},8,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他救了襄陽。有些人記得，有些人不記得。","\n","^他自己不太提這件事。有人問起，他只說：那天風向剛好。","\n",{"->":"jie_ju.15"},null]}],[{"->":".^.b"},{"b":["\n","^他救了襄陽，然後就走了。","\n","^多數人只記得有那麼一個人，一隻手，帶著一隻很醜的大鳥。","\n",{"->":"jie_ju.15"},null]}],"nop","\n","#","^clear","/#",["ev",{"VAR?":"qingyi"},28,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他們在一起活了很久。","\n","^他們沒有生孩子，也沒有收徒弟。兩個人住在一個很安靜的地方，過著一種在外人看來大概很無聊的日子。","\n","^他很滿意。","\n","^他這輩子想要的東西一直只有一樣，而且要了很久才要到。","\n",{"->":"jie_ju.23"},null]}],["ev",{"VAR?":"qingyi"},20,">=","/ev",{"->":".^.b","c":true},{"b":["\n","^他們在一起活了很久。","\n","^有時候他還是會想起那十六年。想起來的時候他會安靜一陣子，她也不問。","\n","^她從來不問。","\n",{"->":"jie_ju.23"},null]}],[{"->":".^.b"},{"b":["\n","^他們在一起活了很久。","\n","^但那十六年在他身上留了些東西，留了一輩子。","\n","^她看得出來。她不知道要怎麼辦，所以她就一直在。","\n",{"->":"jie_ju.23"},null]}],"nop","\n","#","^clear","/#","^〔很多年以後——〕","\n","^〔有一個姓郭的姑娘在峨嵋山上開了一派，收了很多徒弟。〕","\n","^〔徒弟們說，師父有三枚金針，是很年輕的時候別人給的。〕","\n","^〔沒有人見她用過。也沒有人敢問。〕","\n","#","^clear","/#","^〔全書終〕","\n","^〔情意 ","ev",{"VAR?":"qingyi"},"out","/ev","^　俠名 ","ev",{"VAR?":"xiaming"},"out","/ev","^〕","\n","end",null],"global decl":["ev",26,{"VAR=":"qingyi"},15,{"VAR=":"xiaming"},14,{"VAR=":"zhenqi"},false,{"VAR=":"anran"},0,{"VAR=":"shi"},0,{"VAR=":"jiu_xiang"},"/ev","end",null]}],"listDefs":{}}};
